(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.guerra||(w.guerra={});a[3]={"work":"guerra","book":3,"title":"Φλαυίου Ἰωσήπου ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους βιβλίον γ.","chapters":{"1":[{"number":1,"text":"Νέρωνι δʼ ὡς ἠγγέλη τὰ κατὰ τὴν Ἰουδαίαν πταίσματα, λεληθυῖα μὲν ὡς εἰκὸς ἔκπληξις ἐμπίπτει καὶ δέος, φανερῶς δὲ ὑπερηφάνει καὶ προσωργίζετο,"},{"number":2,"text":"στρατηγῶν μὲν ῥᾳστώνῃ μᾶλλον ἢ ταῖς τῶν πολεμίων ἀρεταῖς γεγονέναι τὰ συμβάντα λέγων, πρέπειν δʼ ἡγούμενος ἑαυτῷ διὰ τὸν ὄγκον τῆς ἡγεμονίας κατασοβαρεύεσθαι τῶν σκυθρωπῶν καὶ δοκεῖν δεινοῦ παντὸς ἐπάνω τὴν ψυχὴν ἔχειν."},{"number":3,"text":"διηλέγχετό γε μὴν ὁ τῆς ψυχῆς θόρυβος ὑπὸ τῶν φροντίδων σκεπτομένου τίνι πιστεύσει κινουμένην τὴν ἀνατολήν, ὃς τιμωρήσεται μὲν τὴν τῶν Ἰουδαίων ἐπανάστασιν, προκαταλήψεται δʼ αὐτοῖς ἤδη καὶ τὰ πέριξ ἔθνη συννοσοῦντα."},{"number":4,"text":"μόνον εὑρίσκει Οὐεσπασιανὸν ταῖς χρείαις ἀναλογοῦντα καὶ τηλικούτου πολέμου μέγεθος ἀναδέξασθαι δυνάμενον, ἄνδρα ταῖς ἀπὸ νεότητος στρατείαις ἐγγεγηρακότα καὶ προειρηνεύσαντα μὲν πάλαι Ῥωμαίοις τὴν ἑσπέραν ὑπὸ Γερμανῶν ταρασσομένην, προσκτησάμενον δὲ τοῖς ὅπλοις Βρεττανίαν τέως λανθάνουσαν,"},{"number":5,"text":"ὅθεν αὐτοῦ καὶ τῷ πατρὶ Κλαυδίῳ παρέσχε χωρὶς ἱδρῶτος ἰδίου θρίαμβον καταγαγεῖν."},{"number":6,"text":"Ταῦτά τε δὴ προκλῃδονιζόμενος καὶ σταθερὰν μετʼ ἐμπειρίας τὴν ἡλικίαν ὁρῶν, μέγα δὲ πίστεως αὐτοῦ τοὺς υἱοὺς ὅμηρον καὶ τὰς τούτων ἀκμὰς χεῖρα τῆς πατρῴας συνέσεως, τάχα τι καὶ περὶ τῶν ὅλων ἤδη τοῦ θεοῦ προοικονομουμένου,"},{"number":7,"text":"πέμπει τὸν ἄνδρα ληψόμενον τὴν ἡγεμονίαν τῶν ἐπὶ Συρίας στρατευμάτων, πολλὰ πρὸς τὸ ἐπεῖγον οἷα κελεύουσιν αἱ ἀνάγκαι μειλιξάμενός τε καὶ προθεραπεύσας."},{"number":8,"text":"ὁ δʼ ἀπὸ τῆς Ἀχαΐας, ἔνθα συνῆν τῷ Νέρωνι, τὸν μὲν υἱὸν Τίτον ἀπέστειλεν ἐπʼ Ἀλεξανδρείας τὸ πέμπτον καὶ δέκατον ἐκεῖθεν ἀναστήσοντα τάγμα, περάσας δʼ αὐτὸς τὸν Ἑλλήσποντον πεζὸς εἰς Συρίαν ἀφικνεῖται κἀκεῖ τάς τε Ῥωμαϊκὰς δυνάμεις συνήγαγε καὶ συχνοὺς παρὰ τῶν γειτνιώντων βασιλέων συμμάχους."}],"2":[{"number":9,"text":"Ἰουδαῖοι δὲ μετὰ τὴν Κεστίου πληγὴν ἐπηρμένοι ταῖς ἀδοκήτοις εὐπραγίαις ἀκρατεῖς ἦσαν ὁρμῆς καὶ ὥσπερ ἐκριπιζόμενοι τῇ τύχῃ προσωτέρω τὸν πόλεμον ἐξῆγον· πᾶν γοῦν εὐθέως ὅσον ἦν μαχιμώτατον αὐτοῖς ἀθροισθέντες ὥρμησαν ἐπʼ Ἀσκάλωνα."},{"number":10,"text":"πόλις ἐστὶν ἀρχαία τῶν Ἱεροσολύμων εἴκοσι πρὸς τοῖς πεντακοσίοις ἀπέχουσα σταδίους ἀεὶ διὰ μίσους Ἰουδαίοις γεγενημένη, διὸ καὶ τότε ταῖς πρώταις ὁρμαῖς ἐγγίων ἔδοξεν."},{"number":11,"text":"ἐξηγοῦντο δὲ τῆς καταδρομῆς τρεῖς ἄνδρες ἀλκήν τε κορυφαῖοι καὶ συνέσει, Νίγερ τε ὁ Περαΐτης καὶ ὁ Βαβυλώνιος Σίλας, πρὸς οἷς Ἰωάννης ὁ Ἐσσαῖος."},{"number":12,"text":"ἡ δὲ Ἀσκάλων ἐτετείχιστο μὲν καρτερῶς, βοηθείας δὲ ἦν σχεδὸν ἔρημος· ἐφρουρεῖτο γὰρ ὑπό τε σπείρας πεζῶν καὶ ὑπὸ μιᾶς ἴλης ἱππέων, ἧς ἐπῆρχεν Ἀντώνιος."},{"number":13,"text":"Οἱ μὲν οὖν πολὺ ταῖς ὁρμαῖς συντονώτερον ὁδεύσαντες ὡς ἐγγύθεν ὡρμημένοι καὶ δὴ παρῆσαν·"},{"number":14,"text":"ὁ δὲ Ἀντώνιος, οὐ γὰρ ἠγνόει μέλλουσαν ἔτι τὴν ἔφοδον αὐτῶν, προεξήγαγε τοὺς ἱππεῖς καὶ οὐδὲν οὔτε πρὸς τὸ πλῆθος οὔτε τὴν τόλμαν ὑποδείσας τῶν πολεμίων καρτερῶς τὰς πρώτας ὁρμὰς ἀνεδέξατο καὶ τοὺς ἐπὶ τὸ τεῖχος ὠθουμένους ἀνέστειλεν."},{"number":15,"text":"οἱ δὲ πρὸς ἐμπείρους πολέμων ἄπειροι καὶ πεζοὶ πρὸς ἱππεῖς, ἀσύντακτοί τε πρὸς ἡνωμένους καὶ πρὸς ὁπλίτας ἐξηρτυμένους εἰκαιότερον ὡπλισμένοι, θυμῷ τε πλέον ἢ βουλῇ στρατηγούμενοι πρὸς εὐπειθεῖς καὶ νεύματι πάντα πράττοντας ἀντιτασσόμενοι πονοῦσιν ῥᾳδίως·"},{"number":16,"text":"ὡς γὰρ αὐτῶν ἅπαξ ἤδη συνεταράχθησαν αἱ πρῶται φάλαγγες, ὑπὸ τῆς ἵππου τρέπονται, καὶ τοῖς κατόπιν αὐτῶν ἐπὶ τὸ τεῖχος βιαζομένοις περιπίπτοντες ἀλλήλων ἦσαν πολέμιοι, μέχρι πάντες ταῖς τῶν ἱππέων ἐμβολαῖς εἴξαντες ἐσκεδάσθησαν ἀνὰ πᾶν τὸ πεδίον· τὸ δὲ ἦν πολὺ καὶ πᾶν ἱππάσιμον."},{"number":17,"text":"ὃ δὴ καὶ τοῖς Ῥωμαίοις συνεργῆσαν πλεῖστον εἰργάσατο τῶν Ἰουδαίων φόνον· τούς τε γὰρ φεύγοντας αὐτῶν φθάνοντες ἐπέστρεφον καὶ τῶν ὑπὸ τοῦ δρόμου συνειλουμένων διεκπαίοντες ἀπείρους ἀνῄρουν, ἄλλοι δὲ ἄλλους ὅπῃ τρέποιντο κυκλούμενοι καὶ περιελαύνοντες κατηκόντιζον ῥᾳδίως."},{"number":18,"text":"καὶ τοῖς μὲν Ἰουδαίοις τὸ ἴδιον πλῆθος ἐρημία παρὰ τὰς ἀμηχανίας κατεφαίνετο, Ῥωμαῖοι δὲ ἐν ταῖς εὐπραγίαις καίπερ ὄντες ὀλίγοι τῷ πολέμῳ καὶ περισσεύειν σφᾶς αὐτοὺς ὑπελάμβανον."},{"number":19,"text":"καὶ τῶν μὲν προσφιλονεικούντων τοῖς πταίσμασιν αἰδοῖ τε φυγῆς ταχείας καὶ μεταβολῆς ἐλπίδι, τῶν δὲ μὴ κοπιώντων ἐν οἷς εὐτύχουν, παρέτεινεν ἡ μάχη μέχρι δείλης, ἕως ἀνῃρέθησαν μὲν μύριοι τῶν Ἰουδαίων τὸν ἀριθμὸν ἄνδρες καὶ δύο τῶν ἡγεμόνων, Ἰωάννης τε καὶ Σίλας·"},{"number":20,"text":"οἱ λοιποὶ δὲ τραυματίαι τὸ πλέον σὺν τῷ περιλειπομένῳ τῶν ἡγεμόνων Νίγερι τῆς Ἰδουμαίας εἰς πολίχνην τινά, Χάαλλις καλεῖται, συνέφυγον."},{"number":21,"text":"ὀλίγοι δέ τινες καὶ τῶν Ῥωμαίων ἐπὶ τῆσδε τῆς παρατάξεως ἐτρώθησαν."},{"number":22,"text":"Οὐ μὴν οἱ Ἰουδαῖοι τηλικαύτῃ συμφορᾷ κατεστάλησαν τὰ φρονήματα, μᾶλλον δʼ αὐτῶν τὸ πάθος ἤγειρε τὰς τόλμας, ὑπερορῶντές τε τοὺς ἐν ποσὶ νεκροὺς ἐδελεάζοντο τοῖς προτέροις κατορθώμασιν ἐπὶ πληγὴν δευτέραν."},{"number":23,"text":"διαλιπόντες γοῦν οὐδʼ ὅσον ἰάσασθαι τὰ τραύματα καὶ τὴν δύναμιν πᾶσαν ἐπισυλλέξαντες ὀργιλώτερον καὶ πολλῷ πλείους ἐπαλινδρόμουν ἐπὶ τὴν Ἀσκάλωνα."},{"number":24,"text":"παρείπετο δʼ αὐτοῖς μετά τε τῆς ἀπειρίας καὶ τῶν ἄλλων πρὸς πόλεμον ἐλασσωμάτων ἡ προτέρα τύχη·"},{"number":25,"text":"τοῦ γὰρ Ἀντωνίου τὰς παρόδους προλοχίσαντος ἀδόκητοι ταῖς ἐνέδραις ἐμπεσόντες καὶ ὑπὸ τῶν ἱππέων πρὶν εἰς μάχην συντάξασθαι κυκλωθέντες, πάλιν πίπτουσι μὲν ὑπὲρ ὀκτακισχιλίους, οἱ λοιποὶ δὲ πάντες ἔφυγον, σὺν οἷς καὶ Νίγερ, πολλὰ κατὰ τὴν φυγὴν εὐτολμίας ἐπιδειξάμενος ἔργα, συνελαύνονταί τε προσκειμένων τῶν πολεμίων εἴς τινα πύργον ὀχυρὸν κώμης Βελζεδὲκ καλουμένης."},{"number":26,"text":"οἱ δὲ περὶ τὸν Ἀντώνιον ὡς μήτε τρίβοιντο περὶ τὸν πύργον ὄντα δυσάλωτον μήτε ζῶντα τὸν ἡγεμόνα καὶ γενναιότατον τῶν πολεμίων περιίδοιεν, ὑποπιμπρᾶσι τὸ τεῖχος."},{"number":27,"text":"φλεγομένου δὲ τοῦ πύργου Ῥωμαῖοι μὲν ἀναχωροῦσι γεγηθότες ὡς διεφθαρμένου καὶ Νίγερος, ὁ δὲ εἰς τὸ μυχαίτατον τοῦ φρουρίου σπήλαιον καταπηδήσας ἐκ τοῦ πύργου διασώζεται, καὶ μεθʼ ἡμέρας τρεῖς τοῖς μετʼ ὀλοφυρμοῦ πρὸς κηδείαν αὐτὸν ἐρευνῶσιν ὑποφθέγγεται."},{"number":28,"text":"προελθὼν δὲ χαρᾶς ἀνελπίστου πάντας ἐπλήρωσεν Ἰουδαίους ὡς προνοίᾳ θεοῦ σωθεὶς αὐτοῖς στρατηγὸς εἰς τὰ μέλλοντα."},{"number":29,"text":"Οὐεσπασιανὸς δὲ τὰς δυνάμεις ἀναλαβὼν ἐκ τῆς Ἀντιοχείας, ἣ μητρόπολίς ἐστι τῆς Συρίας, μεγέθους τε ἕνεκα καὶ τῆς ἄλλης εὐδαιμονίας τρίτον ἀδηρίτως ἐπὶ τῆς ὑπὸ Ῥωμαίοις οἰκουμένης ἔχουσα τόπον, ἔνθα μετὰ πάσης τῆς ἰδίας ἰσχύος ἐκδεχόμενον αὐτοῦ τὴν ἄφιξιν καὶ Ἀγρίππαν τὸν βασιλέα κατειλήφει, ἐπὶ Πτολεμαΐδος ἠπείγετο."},{"number":30,"text":"καὶ κατὰ ταύτην ὑπαντῶσιν αὐτῷ τὴν πόλιν οἱ τῆς Γαλιλαίας Σέπφωριν νεμόμενοι πόλιν, μόνοι τῶν τῇδε εἰρηνικὰ φρονοῦντες·"},{"number":31,"text":"οἳ καὶ τῆς ἑαυτῶν σωτηρίας καὶ τῆς Ῥωμαίων ἰσχύος οὐκ ἀπρονόητοι πρὶν ἀφικέσθαι Οὐεσπασιανὸν Καισεννίῳ Γάλλῳ πίστεις τε ἔδοσαν καὶ δεξιὰς ἔλαβον καὶ παρεδέξαντο φρουράν."},{"number":32,"text":"τότε γε μὴν φιλοφρόνως ἐκδεξάμενοι τὸν ἡγεμόνα προθύμως σφᾶς αὐτοὺς ὑπέσχοντο κατὰ τῶν ὁμοφύλων συμμάχους·"},{"number":33,"text":"οἷς ὁ στρατηγὸς ἀξιώσασι τέως πρὸς ἀσφάλειαν ἱππεῖς τε καὶ πεζοὺς παραδίδωσιν ὅσους ἀνθέξειν ταῖς καταδρομαῖς, εἴ τι Ἰουδαῖοι παρακινοῖεν, ὑπελάμβανον·"},{"number":34,"text":"καὶ γὰρ οὐ μικρὸν ἐδόκει τὸ κινδύνευμα πρὸς τὸν μέλλοντα πόλεμον ἀφαιρεθῆναι τὴν Σέπφωριν, μεγίστην μὲν οὖσαν τῆς Γαλιλαίας πόλιν, ἐρυμνοτάτῳ δʼ ἐπιτετειχισμένην χωρίῳ καὶ φρουρὰν ὅλου τοῦ ἔθνους ἐσομένην."}],"3":[{"number":35,"text":"Δύο δʼ οὔσας τὰς Γαλιλαίας, τήν τε ἄνω καὶ τὴν κάτω προσαγορευομένην, περιίσχει μὲν ἡ Φοινίκη τε καὶ Συρία, διορίζει δὲ ἀπὸ μὲν δύσεως ἡλίου Πτολεμαῒς τοῖς τῆς χώρας τέρμασι καὶ Κάρμηλος, τὸ πάλαι μὲν Γαλιλαίων, νῦν δὲ Τυρίων ὄρος·"},{"number":36,"text":"ᾧ προσίσχει Γαβαά, πόλις ἱππέων, οὕτω προσαγορευομένη διὰ τὸ τοὺς ὑφʼ Ἡρώδου βασιλέως ἀπολυομένους ἱππεῖς ἐν αὐτῇ κατοικεῖν·"},{"number":37,"text":"ἀπὸ δὲ μεσημβρίας Σαμαρεῖτίς τε καὶ Σκυθόπολις μέχρι τῶν Ἰορδάνου ναμάτων. πρὸς ἕω δὲ Ἱππηνῇ τε καὶ Γαδάροις ἀποτέμνεται καὶ τῇ Γαυλωνίτιδι· ταύτῃ καὶ τῆς Ἀγρίππα βασιλείας ὅροι."},{"number":38,"text":"τὰ προσάρκτια δʼ αὐτῆς Τύρῳ τε καὶ τῇ Τυρίων χώρᾳ περατοῦται. καὶ τῆς μὲν κάτω καλουμένης Γαλιλαίας ἀπὸ Τιβεριάδος μέχρι Χαβουλών, ἧς ἐν τοῖς παραλίοις Πτολεμαῒς γείτων, τὸ μῆκος ἐκτείνεται."},{"number":39,"text":"πλατύνεται δʼ ἀπὸ τῆς ἐν τῷ μεγάλῳ πεδίῳ κειμένης κώμης, Ἐξαλὼθ καλεῖται, μέχρι Βηρσάβης, ἣ καὶ τῆς ἄνω Γαλιλαίας εἰς εὖρος ἀρχὴ μέχρι Βακὰ κώμης· αὕτη δὲ τὴν Τυρίων γῆν ὁρίζει."},{"number":40,"text":"μηκύνεται δὲ μέχρι Μηρὼθ ἀπὸ Θελλᾶ κώμης Ἰορδάνου γείτονος."},{"number":41,"text":"Τηλικαῦται δʼ οὖσαι τὸ μέγεθος καὶ τοσούτοις ἔθνεσιν ἀλλοφύλοις κεκυκλωμέναι πρὸς πᾶσαν ἀεὶ πολέμου πεῖραν ἀντέσχον·"},{"number":42,"text":"μάχιμοί τε γὰρ ἐκ νηπίων καὶ πολλοὶ Γαλιλαῖοι πάντοτε, καὶ οὔτε δειλία ποτὲ τοὺς ἄνδρας οὔτε λιπανδρία τὴν χώραν κατέσχεν, ἐπειδὴ πίων τε πᾶσα καὶ εὔβοτος καὶ δένδρεσι παντοίοις κατάφυτος, ὡς ὑπὸ τῆς εὐπετείας προκαλέσασθαι καὶ τὸν ἥκιστα γῆς φιλόπονον."},{"number":43,"text":"προσησκήθη γοῦν ὑπὸ τῶν οἰκητόρων πᾶσα, καὶ μέρος αὐτῆς ἀργὸν οὐδέν, ἀλλὰ καὶ πόλεις πυκναὶ καὶ τὸ τῶν κωμῶν πλῆθος πανταχοῦ πολυάνθρωπον διὰ τὴν εὐθηνίαν, ὡς τὴν ἐλαχίστην ὑπὲρ πεντακισχιλίους πρὸς τοῖς μυρίοις ἔχειν οἰκήτορας."},{"number":44,"text":"Καθόλου δέ, εἰ καὶ τῷ μεγέθει τις ἐλαττώσειε τῆς Περαίας τὴν Γαλιλαίαν, προέλοιτο δʼ ἂν τῇ δυνάμει· ἡ μὲν γὰρ ἐνεργὸς ὅλη καὶ συνεχής ἐστιν καρποφόρος, ἡ Περαία δὲ πολὺ μὲν μείζων, ἔρημος δὲ καὶ τραχεῖα τὸ πλέον πρός τε καρπῶν ἡμέρων αὔξησιν ἀγριωτέρα,"},{"number":45,"text":"τό γε μὴν μαλθακὸν αὐτῆς καὶ πάμφορον, καὶ τὰ πεδία δένδρεσι ποικίλοις κατάφυτα τὸ πλεῖστόν τε ἐλαίαν [τε] καὶ ἄμπελον καὶ φοινικῶνας ἤσκηται, διαρδομένη χειμάρροις τε τοῖς ἀπὸ τῶν ὀρῶν καὶ πηγαῖς ἀεννάοις ἅλις, εἴ ποτʼ ἐκεῖνοι σειρίῳ φθίνοιεν."},{"number":46,"text":"μῆκος μὲν [οὖν] αὐτῆς ἀπὸ Μαχαιροῦντος εἰς Πέλλαν, εὖρος δʼ ἀπὸ Φιλαδελφείας μέχρι Ἰορδάνου."},{"number":47,"text":"καὶ Πέλλῃ μέν, ἣν προειρήκαμεν, τὰ πρὸς ἄρκτον ὁρίζεται, πρὸς ἑσπέραν δὲ Ἰορδάνῃ· μεσημβρινὸν δʼ αὐτῆς πέρας ἡ Μωαβῖτις, καὶ πρὸς ἀνατολὴν Ἀραβίᾳ τε καὶ Σιλωνίτιδι, πρὸς δὲ Φιλαδελφηνῇ καὶ Γεράσοις ἀποτέμνεται."},{"number":48,"text":"Ἡ δὲ Σαμαρεῖτις χώρα μέση μὲν τῆς Γαλιλαίας ἐστὶ καὶ τῆς Ἰουδαίας· ἀρχομένη γὰρ ἀπὸ τῆς ἐν τῷ πεδίῳ κειμένης Γηνεὼς ὄνομα κώμης ἐπιλήγει τῆς Ἀκραβετηνῶν τοπαρχίας· φύσιν δὲ τῆς Ἰουδαίας κατʼ οὐδὲν διάφορος."},{"number":49,"text":"ἀμφότεραι γὰρ ὀρειναὶ καὶ πεδιάδες, εἴς τε γεωργίαν μαλθακαὶ καὶ πολύφοροι κατάδενδροί τε καὶ ὀπώρας ὀρεινῆς καὶ ἡμέρου μεσταί, παρʼ ὅσον οὐδαμοῦ φύσει διψάδες, ὕονται δὲ τὸ πλέον·"},{"number":50,"text":"γλυκὺ δὲ νᾶμα πᾶν διαφόρως ἐν αὐταῖς, καὶ διὰ πλῆθος πόας ἀγαθῆς τὰ κτήνη πλέον ἢ παρʼ ἄλλοις γαλακτοφόρα. μέγιστόν γε μὴν τεκμήριον ἀρετῆς καὶ εὐθηνίας τὸ πληθύειν ἀνδρῶν ἑκατέραν."},{"number":51,"text":"Μεθόριος δʼ αὐτῶν ἡ Ἀνουάθου Βόρκαιος προσαγορευομένη κώμη· πέρας αὕτη τῆς Ἰουδαίας τὰ πρὸς βορέαν, τὰ νότια δʼ αὐτῆς ἐπὶ μῆκος μετρουμένης ὁρίζει προσκυροῦσα τοῖς Ἀράβων ὅροις κώμη, καλοῦσι δʼ αὐτὴν Ἰορδὰν οἱ τῇδε Ἰουδαῖοι. εὖρός γε μὴν ἀπὸ Ἰορδάνου ποταμοῦ μέχρις Ἰόππης ἀναπέπταται."},{"number":52,"text":"μεσαιτάτη δʼ αὐτῆς πόλις τὰ Ἱεροσόλυμα κεῖται, παρʼ ὃ καί τινες οὐκ ἀσκόπως ὀμφαλὸν τὸ ἄστυ τῆς χώρας ἐκάλεσαν."},{"number":53,"text":"ἀφῄρηται δʼ οὐδὲ τῶν ἐκ θαλάσσης τερπνῶν ἡ Ἰουδαία τοῖς παραλίοις κατατείνουσα μέχρι Πτολεμαΐδος."},{"number":54,"text":"μερίζεται δʼ εἰς ἕνδεκα κληρουχίας, ὧν ἄρχει μὲν βασίλειον τὰ Ἱεροσόλυμα προανίσχουσα τῆς περιοίκου πάσης ὥσπερ ἡ κεφαλὴ σώματος· αἱ λοιπαὶ δὲ μετʼ αὐτὴν διῄρηνται τὰς τοπαρχίας."},{"number":55,"text":"Γοφνὰ δευτέρα καὶ μετὰ ταύτην Ἀκραβετά, Θαμνὰ πρὸς ταύταις καὶ Λύδδα, Ἀμμαοῦς καὶ Πέλλη καὶ Ἰδουμαία καὶ Ἐνγαδδαὶ καὶ Ἡρώδειον καὶ Ἱεριχοῦς,"},{"number":56,"text":"μεθʼ ἃς Ἰάμνεια καὶ Ἰόππη τῶν περιοίκων ἀφηγοῦνται, κἀπὶ ταύταις ἥ τε Γαμαλιτικὴ καὶ Γαυλανῖτις Βαταναία τε καὶ Τραχωνῖτις, αἳ καὶ τῆς Ἀγρίππα βασιλείας εἰσὶ μοῖραι."},{"number":57,"text":"ἀρχομένη δὲ ἀπὸ Λιβάνου ὄρους καὶ τῶν Ἰορδάνου πηγῶν ἡ χώρα μέχρι τῆς πρὸς Τιβεριάδα λίμνης εὐρύνεται, ἀπὸ δὲ κώμης καλουμένης Ἀρφᾶς μέχρις Ἰουλιάδος ἐκτείνεται τὸ μῆκος. οἰκοῦσι δʼ αὐτὴν μιγάδες Ἰουδαῖοί τε καὶ Σύροι."},{"number":58,"text":"τὰ μὲν δὴ περὶ τῆς Ἰουδαίων τε καὶ πέριξ χώρας ὡς ἐνῆν μάλιστα συντόμως ἀπηγγέλκαμεν."}],"4":[{"number":59,"text":"Ἡ δʼ ὑπὸ Οὐεσπασιανοῦ πεμφθεῖσα Σεπφωρίταις βοήθεια, χίλιοι μὲν ἱππεῖς ἑξακισχίλιοι δὲ πεζοί, Πλακίδου χιλιαρχοῦντος αὐτῶν ἐν τῷ μεγάλῳ πεδίῳ στρατοπεδευσάμενοι διαιροῦνται, καὶ τὸ μὲν πεζὸν ἐν τῇ πόλει πρὸς φυλακὴν αὐτῆς, τὸ δʼ ἱππικὸν ἐπὶ τῆς παρεμβολῆς αὐλίζεται."},{"number":60,"text":"προϊόντες δὲ ἑκατέρωθεν συνεχῶς καὶ τὰ πέριξ τῆς χώρας κατατρέχοντες μεγάλα τοὺς περὶ τὸν Ἰώσηπον ἐκάκουν ἀτρεμοῦντα τάς τε πόλεις ἔξωθεν λῃζόμενοι καὶ προθέοντας ὁπότε θαρρήσειαν ἀνακόπτοντες."},{"number":61,"text":"ὥρμησέ γε μὴν Ἰώσηπος ἐπὶ τὴν πόλιν αἱρήσειν ἐλπίσας, ἣν αὐτὸς πρὶν ἀποστῆναι Γαλιλαίων ἐτείχισεν ὡς καὶ Ῥωμαίοις δυσάλωτον εἶναι· διὸ καὶ τῆς ἐλπίδος ἀφήμαρτεν τοῦ τε βιάζεσθαι καὶ τοῦ μεταπείθειν Σεπφωρίτας ἀσθενέστερος εὑρεθείς."},{"number":62,"text":"παρώξυνεν δὲ μᾶλλον τὸν πόλεμον ἐπὶ τὴν χώραν, καὶ οὔτε νύκτωρ οὔτε μεθʼ ἡμέραν ὀργῇ τῆς ἐπιβολῆς οἱ Ῥωμαῖοι διέλιπον δῃοῦντες αὐτῶν τὰ πεδία καὶ διαρπάζοντες τὰ ἐπὶ τῆς χώρας κτήματα, καὶ κτείνοντες μὲν ἀεὶ τὸ μάχιμον, ἀνδραποδιζόμενοι δὲ τοὺς ἀσθενεῖς."},{"number":63,"text":"πυρὶ δὲ ἡ Γαλιλαία καὶ αἵματι πεπλήρωτο πᾶσα πάθους τε οὐδενὸς ἢ συμφορᾶς ἀπείρατος ἦν· μία γὰρ καταφυγὴ διωκομένοις αἱ ὑπὸ τοῦ Ἰωσήπου τειχισθεῖσαι πόλεις ἦσαν."},{"number":64,"text":"Ὁ δὲ Τίτος περαιωθεὶς ἀπὸ τῆς Ἀχαΐας εἰς τὴν Ἀλεξάνδρειαν ὠκύτερον ἢ κατὰ χειμῶνος ὥραν, παραλαμβάνει μὲν ἐφʼ ἣν ἔσταλτο δύναμιν, συντόνῳ δὲ χρώμενος πορείᾳ διὰ τάχους εἰς Πτολεμαΐδα ἀφικνεῖται."},{"number":65,"text":"κἀκεῖ καταλαβὼν τὸν πατέρα δυσὶ τοῖς ἅμα αὐτῷ τάγμασιν, ἦν δὲ τὰ ἐπισημότατα τὸ πέμπτον καὶ τὸ δέκατον, ζεύγνυσι τὸ ἀχθὲν ὑπʼ αὐτοῦ πεντεκαιδέκατον."},{"number":66,"text":"τούτοις εἵποντο ὀκτωκαίδεκα σπεῖραι· προσεγένοντο δὲ καὶ ἀπὸ Καισαρείας πέντε καὶ ἱππέων ἴλη μία, πέντε δʼ ἕτεραι τῶν ἀπὸ Συρίας ἱππέων."},{"number":67,"text":"τῶν δὲ σπειρῶν αἱ δέκα μὲν εἶχον ἀνὰ χιλίους πεζούς, αἱ δὲ λοιπαὶ δεκατρεῖς ἀνὰ ἑξακοσίους μὲν πεζούς, ἱππεῖς δὲ ἑκατὸν εἴκοσιν. συχνὸν δὲ καὶ παρὰ τῶν βασιλέων συνήχθη συμμαχικόν,"},{"number":68,"text":"Ἀντιόχου μὲν καὶ Ἀγρίππα καὶ Σοαίμου παρασχομένων ἀνὰ δισχιλίους πεζοὺς τοξότας καὶ χιλίους ἱππεῖς, τοῦ δὲ Ἄραβος Μάλχου χιλίους πέμψαντος ἱππεῖς ἐπὶ πεζοῖς πεντακισχιλίοις, ὧν τὸ πλέον ἦσαν τοξόται,"},{"number":69,"text":"ὡς τὴν πᾶσαν δύναμιν συνεξαριθμουμένων τῶν βασιλικῶν ἱππέας τε καὶ πεζοὺς εἰς ἓξ ἀθροίζεσθαι μυριάδας δίχα θεραπόντων, οἳ παμπληθεῖς μὲν εἵποντο, διὰ δὲ συνάσκησιν πολεμικὴν οὐκ ἂν ἀποτάσσοιντο τοῦ μαχίμου, κατὰ μὲν εἰρήνην ἐν ταῖς μελέταις τῶν δεσποτῶν ἀεὶ στρεφόμενοι, συγκινδυνεύοντες δʼ ἐν πολέμοις, ὡς μήτʼ ἐμπειρίᾳ μήτʼ ἀλκῇ τινος πλὴν τῶν δεσποτῶν ἐλαττοῦσθαι."}],"5":[{"number":70,"text":"Κἀν τούτῳ μὲν οὖν θαυμάσαι τις ἂν Ῥωμαίων τὸ προμηθὲς κατασκευαζομένων ἑαυτοῖς τὸ οἰκετικὸν οὐ μόνον εἰς τὰς τοῦ βίου διακονίας ἀλλὰ καὶ πρὸς τοὺς πολέμους χρήσιμον."},{"number":71,"text":"εἰ δέ τις αὐτῶν καὶ εἰς τὴν ἄλλην σύνταξιν τῆς στρατιᾶς ἀπίδοι, γνώσεται τὴν τοσήνδε ἡγεμονίαν αὐτοὺς ἀρετῆς κτῆμα ἔχοντας, οὐ δῶρον τύχης."},{"number":72,"text":"οὐ γὰρ αὐτοῖς ἀρχὴ τῶν ὅπλων πόλεμος, οὐδʼ ἐπὶ μόνας τὰς χρείας τὼ χεῖρε κινοῦσιν ἐν εἰρήνῃ προηργηκότες, ἀλλʼ ὥσπερ συμπεφυκότες τοῖς ὅπλοις οὐδέποτε τῆς ἀσκήσεως λαμβάνουσιν ἐκεχειρίαν οὐδὲ ἀναμένουσιν τοὺς καιρούς."},{"number":73,"text":"αἱ μελέται δʼ αὐτοῖς οὐδὲν τῆς κατὰ ἀλήθειαν εὐτονίας ἀποδέουσιν, ἀλλʼ ἕκαστος ὁσημέραι στρατιώτης πάσῃ προθυμίᾳ καθάπερ ἐν πολέμῳ γυμνάζεται."},{"number":74,"text":"διὸ κουφότατα τὰς μάχας διαφέρουσιν· οὔτε γὰρ ἀταξία διασκίδνησιν αὐτοὺς ἀπὸ τῆς ἐν ἔθει συντάξεως οὔτε δέος ἐξίστησιν οὔτε δαπανᾷ πόνος, ἕπεται δὲ τὸ κρατεῖν ἀεὶ κατὰ τῶν οὐχ ὁμοίων βέβαιον."},{"number":75,"text":"καὶ οὐκ ἂν ἁμάρτοι τις εἰπὼν τὰς μὲν μελέτας αὐτῶν χωρὶς αἵματος παρατάξεις, τὰς παρατάξεις δὲ μεθʼ αἵματος μελέτας."},{"number":76,"text":"οὐδὲ γὰρ ἐξ ἐπιδρομῆς εὐάλωτοι πολεμίοις· ὅπῃ δʼ ἂν ἐμβάλωσιν εἰς ἐχθρῶν γῆν, οὐ πρὶν ἅπτονται μάχης ἢ τειχίσαι στρατόπεδον."},{"number":77,"text":"τὸ δὲ οὐκ εἰκαῖον οὐδὲ ἀνώμαλον ἐγείρουσιν οὐδὲ πάντες ἢ ἀτάκτως διαλαβόντες, ἀλλʼ εἰ μὲν ἀνώμαλος ὢν τύχοι χῶρος, ἐξομαλίζεται· διαμετρεῖται δὲ παρεμβολὴ τετράγωνος αὐτοῖς."},{"number":78,"text":"καὶ τεκτόνων πλῆθος ἕπεται τῶν τε πρὸς τὴν δόμησιν ἐργαλείων."},{"number":79,"text":"Καὶ τὸ μὲν ἔνδον εἰς σκηνὰς διαλαμβάνουσιν, ἔξωθεν δʼ ὁ κύκλος τείχους ὄψιν ἐπίχει πύργοις ἐξ ἴσου διαστήματος κεκοσμημένος."},{"number":80,"text":"ἐπὶ δὲ τῶν μεταπυργίων τούς τε ὀξυβελεῖς καὶ καταπέλτας καὶ λιθοβόλα καὶ πᾶν ἀφετήριον ὄργανον τιθέασιν, πάντα πρὸς τὰς βολὰς ἕτοιμα."},{"number":81,"text":"πύλαι δὲ ἐνοικοδομοῦνται τέσσαρες καθʼ ἕκαστον τοῦ περιβόλου κλίμα, πρός τε εἰσόδους τῶν ὑποζυγίων εὐμαρεῖς καὶ πρὸς τὰς ἐκδρομὰς αὐτῶν, εἰ κατεπείγοι, πλατεῖαι."},{"number":82,"text":"ῥυμοτομοῦσι δʼ εὐδιαθέτως εἴσω τὸ στρατόπεδον, καὶ μέσας μὲν τὰς τῶν ἡγεμόνων σκηνὰς τίθενται, μεσαίτατον δὲ τούτων τὸ στρατήγιον ναῷ παραπλήσιον·"},{"number":83,"text":"ὥσπερ δὲ ἐν σχεδίῳ πόλις καὶ ἀγορά τις ἀποδείκνυται καὶ χειροτέχναις χωρίον θῶκοί τε λοχαγοῖς καὶ ταξιάρχοις, ὅπῃ δικάζοιεν, εἴ τινες διαφέροιντο."},{"number":84,"text":"τειχίζεται δὲ ὁ περίβολος καὶ τὰ ἐν αὐτῷ πάντα θᾶττον ἐπινοίας πλήθει καὶ ἐπιστήμῃ τῶν πονούντων· εἰ δʼ ἐπείγοι, καὶ τάφρος ἔξωθεν περιβάλλεται βάθος τετράπηχυς καὶ εὖρος ἴση."},{"number":85,"text":"Φραξάμενοι δʼ αὐλίζονται κατὰ συντάξεις ἕκαστοι μεθʼ ἡσυχίας τε καὶ κόσμου. πάντα δʼ αὐτοῖς καὶ τὰ ἄλλα μετʼ εὐταξίας ἀνύεται καὶ ἀσφαλείας, ξυλεία τε καὶ ἐπισιτισμός, εἰ δέοιντο, καὶ ὑδρεία κατὰ συντάξεις ἑκάστοις."},{"number":86,"text":"οὐδὲ γὰρ δεῖπνον ἢ ἄριστον ὁπότε θελήσειαν αὐτεξούσιον ἑκάστῳ, πᾶσιν δʼ ὁμοῦ, τούς τε ὕπνους αὐτοῖς καὶ τὰς φυλακὰς καὶ τὰς ἐξεγέρσεις σάλπιγγες προσημαίνουσιν, οὐδʼ ἔστιν ὅ τι γίνεται δίχα παραγγέλματος."},{"number":87,"text":"ὑπὸ δὲ τὴν ἕω τὸ στρατιωτικὸν μὲν ἐπὶ τοὺς ἑκατοντάρχας ἕκαστοι, πρὸς δὲ τοὺς χιλιάρχους οὗτοι συνίασιν ἀσπασόμενοι, μεθʼ ὧν πρὸς τὸν ἡγεμόνα τῶν ὅλων οἱ ταξίαρχοι πάντες."},{"number":88,"text":"ὁ δʼ αὐτοῖς τό τε ἐξ ἔθους σημεῖον καὶ τἆλλα παραγγέλματα δίδωσιν διαφέρειν εἰς τοὺς ὑποτεταγμένους· ὃ δὴ κἀπὶ παρατάξεως πράττοντες ἐπιστρέφονταί τε ταχέως, ἵνα δέοι, καὶ πρὸς τὰς ἐφόδους αὐτοῖς καὶ πρὸς τὰς ἀνακλήσεις ὑποχωροῦσιν ἀθρόοι."},{"number":89,"text":"Ἐξιέναι δὲ τοῦ στρατοπέδου δέον ὑποσημαίνει μὲν ἡ σάλπιγξ, ἠρεμεῖ δʼ οὐδείς, ἀλλʼ ἅμα νεύματι τὰς μὲν σκηνὰς ἀναιροῦσιν, πάντα δʼ ἐξαρτύονται πρὸς τὴν ἔξοδον."},{"number":90,"text":"καὶ πάλιν αἱ σάλπιγγες ὑποσημαίνουσιν παρεσκευάσθαι. οἱ δʼ ἐν τάχει τοῖς τε ὀρεῦσιν καὶ τοῖς ὑποζυγίοις ἐπιθέντες τὴν ἀποσκευὴν ἑστᾶσιν ὥσπερ ἐφʼ ὕσπληγος ἐξορμᾶν ἕτοιμοι, ὑποπιμπρᾶσίν τε ἤδη τὴν παρεμβολὴν ὡς αὐτοῖς μὲν ὂν ῥᾴδιον ἐκεῖ πάλιν τειχίσασθαι, μὴ γένοιτο δʼ ἐκεῖνό ποτε τοῖς πολεμίοις χρήσιμον."},{"number":91,"text":"καὶ τρίτον δʼ ὅμως αἱ σάλπιγγες προσημαίνουσιν τὴν ἔξοδον ἐπισπέρχουσαι τοὺς διʼ αἰτίαν τινὰ βραδύναντας, ὡς μή τις ἀπολειφθείη τάξεως."},{"number":92,"text":"ὅ τε κῆρυξ δεξιὸς τῷ πολεμάρχῳ παραστάς, εἰ πρὸς πόλεμόν εἰσιν ἕτοιμοι, τῇ πατρίῳ γλώσσῃ τρὶς ἀναπυνθάνεται. κἀκεῖνοι τοσαυτάκις ἀντιβοῶσιν μέγα τι καὶ πρόθυμον ἕτοιμοι λέγοντες εἶναι, φθάνουσιν δὲ τὸν ἐπερωτῶντα, καί τινος ἀρηΐου πνεύματος ὑποπιμπλάμενοι τῇ βοῇ συνεξαίρουσιν τὰς δεξιάς."},{"number":93,"text":"Ἔπειτα προϊόντες ὁδεύουσιν ἡσυχῇ καὶ μετὰ κόσμου πάντες, ὥσπερ ἐν πολέμῳ τὴν ἰδίαν τάξιν ἕκαστος φυλάσσων, οἱ μὲν πεζοὶ θώραξιν πεφραγμένοι καὶ κράνεσιν καὶ μαχαιροφοροῦντες ἀμφοτέρωθεν."},{"number":94,"text":"μακρότερον δʼ αὐτῶν τὸ λαιὸν ξίφος πολλῷ· τὸ γὰρ κατὰ τὸ δεξιὸν σπιθαμῆς οὐ πλέον ἔχει τὸ μῆκος."},{"number":95,"text":"φέρουσι δʼ οἱ μὲν περὶ τὸν στρατηγὸν ἐπίλεκτοι πεζοὶ λόγχην καὶ ἀσπίδα, ἡ δὲ λοιπὴ φάλαγξ ξυστόν τε καὶ θυρεὸν ἐπιμήκη, πρὸς οἷς πρίονα καὶ κόφινον ἄμην τε καὶ πέλεκυν, πρὸς δὲ ἱμάντα καὶ δρέπανον καὶ ἅλυσιν, ἡμερῶν τε τριῶν ἐφόδιον· ὡς ὀλίγον ἀποδεῖν τῶν ἀχθοφορούντων ὀρέων τὸν πεζόν."},{"number":96,"text":"τοῖς δὲ ἱππεῦσιν μάχαιρα μὲν ἐκ δεξιῶν μακρὰ καὶ κοντὸς ἐπιμήκης ἐν χειρί, θυρεὸς δὲ παρὰ πλευρὸν ἵππου πλάγιος, καὶ κατὰ γωρυτοῦ παρήρτηνται τρεῖς ἢ πλείους ἄκοντες, πλατεῖς μὲν αἰχμάς, οὐκ ἀποδέοντες δὲ δοράτων μέγεθος·"},{"number":97,"text":"κράνη δὲ καὶ θώρακες ὁμοίως τοῖς πεζοῖς ἅπασιν. οὐδενὶ δὲ ὅπλων διαλλάττουσιν οἱ περὶ τὸν στρατηγὸν ἔκκριτοι τῶν ἐν ταῖς ἴλαις ἱππέων. κλήρῳ δὲ τῶν ταγμάτων ἀεὶ τὸ λαχὸν ἡγεῖται."},{"number":98,"text":"Τοιαῦται μὲν οὖν αἱ Ῥωμαίων πορεῖαί τε καὶ καταλύσεις, πρὸς δὲ ὅπλων διαφοραί, οὐδὲν δὲ ἀπροβούλευτον ἐν ταῖς μάχαις οὐδὲ αὐτοσχέδιον, ἀλλὰ γνώμη μὲν ἀεὶ παντὸς ἔργου προάγει, τοῖς δοχθεῖσι δὲ ἕπεται τὰ ἔργα·"},{"number":99,"text":"παρʼ ὃ καὶ σφάλλονται μὲν ἥκιστα, κἂν πταίσωσι δέ, ῥᾳδίως ἀναλαμβάνουσι τὰ σφάλματα."},{"number":100,"text":"ἡγοῦνταί τε τῶν ἀπὸ τύχης ἐπιτευγμάτων ἀμείνους τὰς ἐπὶ τοῖς προβουλευθεῖσιν διαμαρτίας, ὡς τοῦ μὲν αὐτομάτου καλοῦ δελεάζοντος εἰς ἀπρομήθειαν, τῆς σκέψεως δέ, κἂν ἀτυχήσῃ ποτέ, πρὸς τὸ μὴ αὖθις καλὴν ἐχούσης μελέτην·"},{"number":101,"text":"καὶ τῶν μὲν αὐτομάτων ἀγαθῶν οὐ τὸν λαβόντα αἴτιον εἶναι, τῶν δὲ παρὰ γνώμην προσπεσόντων σκυθρωπῶν παραμυθίαν τό γε προσηκόντως βεβουλεῦσθαι."},{"number":102,"text":"Παρασκευάζουσι μὲν οὖν ἐν ταῖς μελέταις τῶν ὅπλων οὐ τὰ σώματα μόνον ἀλλὰ καὶ τὰς ψυχὰς ἀλκίμους, προσασκοῦνται δὲ καὶ τῷ φόβῳ."},{"number":103,"text":"οἵ τε γὰρ νόμοι παρʼ αὐτοῖς οὐ λιποταξίου μόνον ἀλλὰ καὶ ῥᾳστώνης ὀλίγης θανατικοὶ οἵ τε στρατηγοὶ τῶν νόμων φοβερώτεροι· ταῖς γὰρ πρὸς τοὺς ἀγαθοὺς τιμαῖς ῥύονται τὸ δοκεῖν ὠμοὶ πρὸς τοὺς κολαζομένους."},{"number":104,"text":"τοσοῦτον δʼ αὐτῶν τὸ πρὸς τοὺς ἡγεμόνας πειθήνιον, ὡς ἔν τε εἰρήνῃ κόσμον εἶναι καὶ ἐπὶ παρατάξεως ἓν σῶμα τὴν ὅλην στρατιάν."},{"number":105,"text":"οὕτως αὐτῶν ἀσφαλεῖς μὲν αἱ τάξεις, εὔστροφοι δʼ εἰσὶν αἱ περιαγωγαί, ὀξεῖαι δʼ ἀκοαὶ μὲν παραγγέλμασιν, ὄψεις δὲ σημείοις, ἔργοις δὲ χεῖρες."},{"number":106,"text":"ὅθεν δρᾶσαι μὲν ἀεὶ ταχεῖς, βραδύτατοι δὲ παθεῖν εἰσιν, οὐδʼ ἔστιν ὅπου σταθέντες ἢ πλήθους ἡσσήθησαν ἢ στρατηγημάτων ἢ δυσχωρίας, ἀλλʼ οὐδὲ τύχης· καὶ γὰρ ταύτης αὐτοῖς τὸ κρατεῖν βεβαιότερον."},{"number":107,"text":"οἷς οὖν βουλὴ μὲν ἄρχει παρατάξεως, ἕπεται δὲ τοῖς βεβουλευμένοις στρατὸς οὕτω δραστήριος, τί θαυμαστόν, εἰ πρὸς ἕω μὲν Εὐφράτης, ὠκεανὸς δὲ πρὸς ἑσπέραν, μεσημβρινὸν δὲ Λιβύης τὸ πιότατον καὶ πρὸς ἄρκτον Ἴστρος τε καὶ Ῥῆνος τῆς ἡγεμονίας ὅροι; δεόντως γὰρ ἄν τις εἴποι τὸ κτῆμα τῶν κτησαμένων ἔλασσον."},{"number":108,"text":"Ταῦτα μὲν οὖν διεξῆλθον οὐ Ῥωμαίους ἐπαινέσαι προαιρούμενος τοσοῦτον, ὅσον εἴς τε παραμυθίαν τῶν κεχειρωμένων καὶ εἰς ἀποτροπὴν τῶν νεωτεριζόντων·"},{"number":109,"text":"εἴη δʼ ἂν τοῖς ἀγνοοῦσιν τῶν φιλοκαλούντων καὶ πρὸς ἐμπειρίας ἡ ἀγωγὴ τῆς Ῥωμαίων στρατιᾶς. ἐπάνειμι δʼ ὅθεν ἐπὶ ταῦτʼ ἐξέβην."}],"6":[{"number":110,"text":"Οὐεσπασιανὸς μὲν ἅμα τῷ παιδὶ Τίτῳ διατρίβων τέως ἐν τῇ Πτολεμαΐδι συνέτασσεν τὰς δυνάμεις, ὁ δὲ τὴν Γαλιλαίαν κατατρέχων Πλάκιδος ἐπεὶ πολὺ μὲν πλῆθος ἀνῃρήκει τῶν καταλαμβανομένων, τοῦτο δʼ ἦν τὸ ἀσθενέστερον Γαλιλαίων καὶ ταῖς φυγαῖς ἐναποκάμνον,"},{"number":111,"text":"ὁρῶν δὲ συμφεῦγον ἀεὶ τὸ μάχιμον εἰς τὰς ὑπὸ τοῦ Ἰωσήπου τειχισθείσας πόλεις ὥρμησεν ἐπὶ τὴν ὀχυρωτάτην αὐτῶν Ἰωταπάταν, οἰόμενος ἐξ ἐφόδου μὲν αἱρήσειν ῥᾳδίως, μέγα δὲ κλέος αὐτῷ παρὰ τοῖς ἡγεμόσιν κἀκείνοις ὄφελος εἰς τὰ λοιπὰ παρέξειν· προσχωρήσειν γὰρ δέει τὰς ἄλλας πόλεις τῆς καρτερωτάτης ἐχομένης."},{"number":112,"text":"πολύ γε μὴν διήμαρτεν τῆς ἐλπίδος· ἐπιόντα γὰρ αὐτὸν οἱ Ἰωταπατηνοὶ προαισθόμενοι πρὸ τῆς πόλεως ἐκδέχονται, καὶ τοῖς Ῥωμαίοις συρραγέντες ἀδοκήτοις πολλοὶ καὶ πρὸς μάχην ἕτοιμοι πρόθυμοί τε ὡς ἂν ὑπὲρ κινδυνευούσης πατρίδος καὶ γυναικῶν καὶ τέκνων, τρέπονται ταχέως."},{"number":113,"text":"καὶ πολλοὺς μὲν τιτρώσκουσι τῶν Ῥωμαίων, ἑπτὰ δὲ ἀναιροῦσιν διὰ τὸ μήτε ἄτακτον αὐτῶν τὴν ὑποχώρησιν γενέσθαι καὶ τὰς πληγὰς ἐπιπολαίους πεφραγμένων πάντοθεν τῶν σωμάτων, τούς τε Ἰουδαίους πόρρωθεν βάλλειν πλέον ἢ συμπλέκεσθαι θαρρεῖν γυμνῆτας ὁπλίταις."},{"number":114,"text":"ἔπεσον δὲ καὶ τῶν Ἰουδαίων τρεῖς ἄνδρες καὶ ἐτρώθησαν ὀλίγοι. Πλάκιδος μὲν οὖν τῆς ἐπὶ τὴν πόλιν ὁρμῆς ἀτονώτερος εὑρεθεὶς φεύγει."},{"number":115,"text":"Οὐεσπασιανὸς δὲ ὡρμημένος αὐτὸς ἐμβαλεῖν εἰς τὴν Γαλιλαίαν ἐξελαύνει τῆς Πτολεμαΐδος διατάξας τὴν στρατιὰν ὁδεύειν καθὰ Ῥωμαίοις ἔθος."},{"number":116,"text":"τοὺς μέν γε ψιλοὺς τῶν ἐπικούρων καὶ τοξότας προάγειν ἐκέλευσεν, ὡς ἀνακόπτοιεν τὰς ἐξαπιναίους τῶν πολεμίων ἐπιδρομὰς καὶ διερευνῷεν τὰς ὑπόπτους καὶ λοχᾶσθαι δυναμένας ὕλας, οἷς εἵπετο καὶ Ῥωμαίων ὁπλιτικὴ μοῖρα πεζοί τε καὶ ἱππεῖς."},{"number":117,"text":"τούτοις ἀφʼ ἑκάστης ἑκατονταρχίας ἠκολούθουν δέκα τήν τε ἑαυτῶν σκευὴν καὶ τὰ μέτρα τῆς παρεμβολῆς φέροντες,"},{"number":118,"text":"καὶ μετʼ αὐτοὺς ὁδοποιοί, τά τε σκολιὰ τῆς λεωφόρου κατευθύνειν καὶ χθαμαλοῦν τὰ δύσβατα καὶ τὰς ἐμποδίους ὕλας προανακόπτειν, ὡς μὴ ταλαιπωροῖτο δυσποροῦν τὸ στράτευμα."},{"number":119,"text":"κατόπιν δὲ τούτων τάς τε ἰδίας καὶ τὰς τῶν ὑπʼ αὐτὸν ἡγεμόνων ἔταξεν ἀποσκευὰς καὶ συχνοὺς ἐπὶ τούτοις πρὸς ἀσφάλειαν τῶν ἱππέων."},{"number":120,"text":"μεθʼ οὓς αὐτὸς ἐξήλαυνεν τούς τε ἐπιλέκτους τῶν πεζῶν καὶ ἱππέων καὶ τοὺς λογχοφόρους ἔχων. εἵπετο δʼ αὐτῷ τὸ ἴδιον τοῦ τάγματος ἱππικόν· ἴδιοι γὰρ ἑκάστου τάγματος εἴκοσι πρὸς τοῖς ἑκατὸν ἱππεῖς."},{"number":121,"text":"τούτοις δʼ ἠκολούθουν οἱ τὰς ἑλεπόλεις φέροντες ὀρεῖς καὶ τὰ λοιπὰ μηχανήματα."},{"number":122,"text":"μετὰ τούτους ἡγεμόνες τε καὶ σπειρῶν ἔπαρχοι σὺν χιλιάρχοις, ἐπιλέκτους περὶ σφᾶς στρατιώτας ἔχοντες·"},{"number":123,"text":"ἔπειτα αἱ σημαῖαι περιίσχουσαι τὸν ἀετόν, ὃς παντὸς ἄρχει Ῥωμαίοις τάγματος, βασιλεύς τε οἰωνῶν ἁπάντων καὶ ἀλκιμώτατος ὤν· ὃ δὴ καὶ τῆς ἡγεμονίας τεκμήριον αὐτοῖς καὶ κλῃδών, ἐφʼ οὓς ἂν ἴωσιν, τοῦ κρατήσειν δοκεῖ."},{"number":124,"text":"τοῖς δὲ ἱεροῖς ἠκολούθουν οἱ σαλπιγκταί, καὶ κατόπιν αὐτῶν ἡ φάλαγξ τὸ στῖφος εἰς ἓξ πλατύνασα. τούτοις παρείπετό τις ἑκατόνταρχος ἐξ ἔθους τὴν τάξιν ἐπισκοπούμενος."},{"number":125,"text":"τὸ δʼ οἰκετικὸν ἑκάστου τάγματος ἅπαν τοῖς πεζοῖς εἵπετο, τὰς ἀποσκευὰς τῶν στρατιωτῶν ἐπὶ τοῖς ὀρεῦσιν καὶ τοῖς ὑποζυγίοις ἄγοντες·"},{"number":126,"text":"κατόπιν δὲ πάντων [τῶν ταγμάτων] ὁ μίσθιος ὄχλος, οἷς οὐραγοὶ πρὸς ἀσφάλειαν ἠκολούθουν πεζοί τε καὶ ὁπλῖται καὶ τῶν ἱππέων συχνοί."},{"number":127,"text":"Οὕτως ὁδεύσας Οὐεσπασιανὸς μετὰ τῆς δυνάμεως εἰς τοὺς ὅρους ἀφικνεῖται τῆς Γαλιλαίας, ἔνθα καταστρατοπεδευσάμενος ὡρμημένους εἰς πόλεμον τοὺς στρατιώτας κατεῖχεν, ἐπιδεικνύμενος τὴν στρατιὰν εἰς κατάπληξιν τοῖς πολεμίοις καὶ μετανοίας καιρὸν διδούς, εἰ πρὸ μάχης μεταβάλοιντο· ἅμα δὲ καὶ πρὸς πολιορκίαν τῶν ἐρυμάτων ἐξηρτύετο."},{"number":128,"text":"μετάνοιαν μὲν οὖν τῆς ἀποστάσεως ὀφθεὶς ὁ στρατηγὸς πολλοῖς ἐνειργάσατο, κατάπληξιν δὲ πᾶσιν·"},{"number":129,"text":"οἱ μὲν γὰρ περὶ τὸν Ἰώσηπον ἐστρατοπεδευκότες οὐκ ἄπωθεν τῆς Σεπφώρεως παρὰ πόλιν Γαρὶν καλουμένην ἐπεὶ πλησιάζοντα τὸν πόλεμον ἤκουσαν ὅσον τε οὔπω τοὺς Ῥωμαίους συμμίξοντας σφίσιν, οὐ μόνον πρὸ μάχης, ἀλλὰ καὶ πρὶν ἰδεῖν τοὺς ἐχθροὺς διασκίδνανται φυγῇ."},{"number":130,"text":"καταλείπεται δʼ ὁ Ἰώσηπος μετʼ ὀλίγων, καὶ κατιδὼν ὡς οὔτε δέχεσθαι τοὺς πολεμίους ἀρκετὴν ἔχει δύναμιν καὶ πεπτώκοι τὰ φρονήματα τῶν Ἰουδαίων ἄσμενοί τʼ ἄν, εἰ πιστεύοιντο, χωροῖεν οἱ πλείους ἐπὶ σπονδάς, ἐδεδίει μὲν ἤδη περὶ παντὸς τοῦ πολέμου,"},{"number":131,"text":"τότε δʼ ὡς πορρωτάτω χωρίζεσθαι τῶν κινδύνων ἔκρινεν. ἀναλαβὼν δὲ τοὺς συμμείναντας εἰς Τιβεριάδα καταφεύγει."}],"7":[{"number":132,"text":"Οὐεσπασιανὸς δὲ τῇ πόλει τῶν Γαδάρων ἐπελθὼν αἱρεῖ τε κατὰ πρώτην ἔφοδον αὐτὴν μαχίμου πλήθους ἔρημον καταλαβών,"},{"number":133,"text":"καὶ παρελθὼν εἴσω πάντας ἡβηδὸν ἀναιρεῖ μηδεμιᾶς τῶν Ῥωμαίων ἡλικίας ἔλεον ποιουμένων μίσει πρὸς τὸ ἔθνος καὶ μνήμῃ τῆς κατὰ τὸν Κέστιον αὐτῶν παρανομίας."},{"number":134,"text":"ἐμπίμπρησιν δὲ οὐ μόνον αὐτὴν τὴν πόλιν, ἀλλὰ καὶ τὰς πέριξ κώμας πάσας τε καὶ πολίχνας, ἃς μὲν παντελῶς ἐκλελειμμένας, ἔστιν δʼ ἃς αὐτὸς ἐξανδραποδιζόμενος."},{"number":135,"text":"Ὁ δʼ Ἰώσηπος ἣν πρὸς ἀσφάλειαν εἵλετο πόλιν αὐτὸς ἐνέπλησεν δέους καταφυγών. οἱ δὲ ἀπὸ τῆς Τιβεριάδος οὐκ ἄν, εἰ μὴ πρὸς τὸ πᾶν ἀπεγνώκει τὸν πόλεμον, τραπῆναί ποτε αὐτὸν ᾤοντο."},{"number":136,"text":"καὶ κατὰ τοῦτό γε οὐ διημάρτανον αὐτοῦ τῆς γνώμης· ἑώρα μὲν γάρ, ποῖ ῥέψει τὰ Ἰουδαίων τέλους, καὶ μίαν αὐτῶν ᾔδει σωτηρίαν, εἰ μεταβάλοιντο."},{"number":137,"text":"αὐτὸς δὲ καίπερ συγγνωσθήσεσθαι παρὰ Ῥωμαίοις προσδοκῶν, ὅμως τεθνάναι μᾶλλον εἵλετο πολλάκις ἢ καταπροδοὺς τὴν πατρίδα καὶ τὴν ἐμπιστευθεῖσαν αὐτῷ στρατηγίαν ὑβρίσας εὐτυχεῖν παρʼ οἷς πολεμήσων ἐπέμφθη."},{"number":138,"text":"γράφειν οὖν τοῖς ἐν τέλει τῶν Ἱεροσολύμων διέγνω μετὰ ἀκριβείας τὰ πράγματα, ὡς μήτʼ ἐπὶ μεῖζον ἐξάρας τὴν τῶν πολεμίων ἰσχὺν αὖθις εἰς δειλίαν κακίζοιτο μήτε ἐνδεέστερον ἀπαγγείλας κἂν μετανοήσαντας ἴσως θρασύνοιεν,"},{"number":139,"text":"ἵνα τε ἢ σπονδὰς αἱρούμενοι ταχέως ἀντιγράψωσιν ἢ πολεμεῖν ἐγνωκότες πρὸς Ῥωμαίους ἀξιόμαχον αὐτῷ πέμψωσι δύναμιν."},{"number":140,"text":"ὁ μὲν οὖν ταῦτʼ ἐπιστείλας πέμπει διὰ τάχους ἐπὶ Ἱεροσολύμων τοὺς τὰ γράμματα κομίζοντας."},{"number":141,"text":"Οὐεσπασιανὸς δὲ ὡρμημένος ἐξαιρεῖν τὴν Ἰωταπάταν, πέπυστο γὰρ εἰς αὐτὴν πλείστους τῶν πολεμίων συμπεφευγέναι καὶ ἄλλως ὁρμητήριον ἰσχυρὸν οὖσαν αὐτῶν, πέμπει πεζούς τε καὶ ἱππεῖς τοὺς προεξομαλιοῦντας τὴν ὁδὸν ὀρεινὴν ὑπάρχουσαν καὶ πετρώδη, δύσβατον δὲ καὶ πεζοῖς, ἱππεῦσιν δʼ ἀμήχανον."},{"number":142,"text":"οἱ μὲν οὖν τέσσαρσιν ἡμέραις ἐξειργάσαντο καὶ πλατεῖαν ἤνοιξαν τῇ στρατιᾷ λεωφόρον· τῇ πέμπτῃ δʼ ὁ Ἰώσηπος, αὕτη δʼ ἦν Ἀρτεμισίου μηνὸς μία καὶ εἰκάς, φθάνει παρελθὼν εἰς τὴν Ἰωταπάταν ἐκ τῆς Τιβεριάδος καὶ πεπτωκότα τοῖς Ἰουδαίοις ἐγείρει τὰ φρονήματα."},{"number":143,"text":"Οὐεσπασιανῷ δέ τις εὐαγγελίζεται τὴν μετάβασιν τοῦ ἀνδρὸς αὐτόμολος καὶ κατήπειγεν ἐπὶ τὴν πόλιν ὡς μετʼ ἐκείνης αἱρήσοντα πᾶσαν Ἰουδαίαν, εἰ λάβοι τὸν Ἰώσηπον ὑποχείριον."},{"number":144,"text":"ὁ δʼ ἁρπάσας ὥσπερ μέγιστον εὐτύχημα τὴν ἀγγελίαν, καὶ προνοίᾳ θεοῦ τὸν συνετώτατον εἶναι δοκοῦντα τῶν πολεμίων οἰόμενος εἰς εἱρκτὴν αὐθαίρετον παρελθεῖν, εὐθέως μὲν σὺν χιλίοις ἱππεῦσιν πέμπει Πλάκιδον καὶ δεκαδάρχην Αἰβούτιον, ἄνδρα τῶν ἐπισήμων κατὰ χεῖρα καὶ σύνεσιν, περικατασχεῖν κελεύσας τὴν πόλιν, ὡς μὴ λάθοι διαδρὰς ὁ Ἰώσηπος."},{"number":145,"text":"Αὐτὸς δὲ μετὰ μίαν ἡμέραν ἀναλαβὼν πᾶσαν τὴν δύναμιν εἵπετο καὶ μέχρι δείλης ὁδεύσας πρὸς τὴν Ἰωταπάταν ἀφικνεῖται."},{"number":146,"text":"ἀναλαβὼν δὲ τὴν στρατιὰν εἰς τὸ προσάρκτιον αὐτῆς μέρος ἔν τινι λόφῳ στρατοπεδεύεται διέχοντι σταδίους ἑπτὰ τῆς πόλεως, πειρώμενος ὡς μάλιστα τοῖς πολεμίοις εὐσύνοπτος εἶναι πρὸς ἔκπληξιν·"},{"number":147,"text":"ἣ καὶ παραχρῆμα τοσαύτη τοὺς Ἰουδαίους κατέσχεν, ὡς μηδένα τοῦ τείχους τολμῆσαι προελθεῖν."},{"number":148,"text":"Ῥωμαῖοι δʼ εὐθὺς μὲν ἀπώκνησαν προσβαλεῖν διʼ ὅλης ὡδευκότες ἡμέρας, διπλῇ δὲ τῇ φάλαγγι κυκλοῦνται τὴν πόλιν καὶ τρίτην ἔξωθεν περιιστᾶσιν τὴν ἵππον, πάσας ἀποφράσσοντες αὐτοῖς τὰς ἐξόδους."},{"number":149,"text":"τοῦτʼ ἐν ἀπογνώσει σωτηρίας παρώξυνε τοὺς Ἰουδαίους πρὸς τόλμαν· οὐδὲν γὰρ ἀνάγκης ἐν πολέμῳ μαχιμώτερον."},{"number":150,"text":"Γενομένης δὲ μεθʼ ἡμέραν προσβολῆς τὸ μὲν πρῶτον Ἰουδαῖοι κατὰ χώραν μένοντες ἀντεῖχον ἀντικρὺ τῶν Ῥωμαίων ἐστρατοπεδευκότες πρὸ τοῦ τείχους·"},{"number":151,"text":"ὡς δὲ Οὐεσπασιανὸς τούτοις μὲν τοὺς τοξότας καὶ σφενδονήτας καὶ πᾶν τὸ τῶν ἑκηβόλων πλῆθος ἐπιστήσας ἐπέτρεψεν βάλλειν, αὐτὸς δὲ μετὰ τῶν πεζῶν εἰς τὸ πρόσαντες ἀνώθει καθʼ ὃ τὸ τεῖχος ἦν εὐάλωτον, δείσας ὁ Ἰώσηπος περὶ τῇ πόλει προπηδᾷ καὶ σὺν αὐτῷ πᾶν τὸ τῶν Ἰουδαίων πλῆθος."},{"number":152,"text":"συμπεσόντες δὲ τοῖς Ῥωμαίοις ἀθρόοι τοῦ μὲν τείχους ἀνέστειλαν αὐτούς, πολλὰ δʼ ἐπεδείκνυντο χειρῶν ἔργα καὶ τόλμης."},{"number":153,"text":"οὐκ ἔλασσόν γε μὴν ὧν ἔδρων ἀντέπασχον· ὅσον γὰρ αὐτοὺς ἡ τῆς σωτηρίας ἀπόγνωσις, τοσοῦτο τοὺς Ῥωμαίους αἰδὼς παρεκρότει, καὶ τοὺς μὲν ἐμπειρία μετʼ ἀλκῆς, τοὺς δὲ θράσος ὥπλιζε τῷ θυμῷ στρατηγουμένους."},{"number":154,"text":"παραταξάμενοι δὲ διʼ ὅλης ἡμέρας νυκτὶ διαλύονται, τρώσαντες μὲν πλείστους Ῥωμαίων, δεκατρεῖς δʼ ἀνελόντες· αὐτῶν δʼ ἔπεσον μὲν δεκαεπτά, τραυματίαι δʼ ἐγένοντο ἑξακόσιοι."},{"number":155,"text":"Τῇ δʼ ὑστεραίᾳ πάλιν προσβάλλουσι τοῖς Ῥωμαίοις ἐπεξελθόντες καὶ πολὺ καρτερώτερον ἀντιπαρετάξαντο, θαρραλεώτεροι μὲν ἐκ τοῦ παρὰ λόγον ἀντισχεῖν τῇ προτέρᾳ γεγενημένοι, χρώμενοι δὲ καὶ τοῖς Ῥωμαίοις μαχιμωτέροις·"},{"number":156,"text":"ὑπὸ γὰρ αἰδοῦς εἰς ὀργὴν ἐξεκαίοντο τὸ μὴ ταχέως νικᾶν ἧτταν ἡγούμενοι."},{"number":157,"text":"καὶ μέχρι πέμπτης ἡμέρας προσβολαὶ μὲν ἐγίνοντο τῶν Ῥωμαίων ἀδιάλειπτοι, ἐκδρομαὶ δὲ τῶν Ἰωταπατηνῶν καὶ τειχομαχίαι καρτερώτεραι, καὶ οὔτε Ἰουδαῖοι τὴν τῶν πολεμίων ἰσχὺν κατωρρώδουν οὔτε Ῥωμαῖοι πρὸς τὸ τῆς πόλεως δυσάλωτον ἀπέκαμνον."},{"number":158,"text":"Ἔστιν δʼ Ἰωταπάτα πλὴν ὀλίγου πᾶσα κρημνός, ἐκ μὲν τῶν ἄλλων μερῶν πάντοθεν φάραγξιν ἀπείροις ἀπότομος, ὡς τῶν κατιδεῖν πειρωμένων τὰς ὄψεις προεξασθενεῖν τοῦ βάθους, ἀπὸ βορέου δὲ προσιτὴ μόνον, καθʼ ὃ λήγοντι τῷ ὄρει πλαγίῳ προσέκτισται."},{"number":159,"text":"καὶ τοῦτο δʼ ὁ Ἰώσηπος ἐμπεριειλήφει τειχίζων τὴν πόλιν, ὡς ἀκατάληπτον εἶναι πολεμίοις τὴν ὑπὲρ αὐτῆς ἀκρώρειαν."},{"number":160,"text":"κυκλόθεν δʼ ἄλλοις ὄρεσιν καλυπτομένη, πρὶν εἰσαφίκοιτό τις εἰς αὐτήν, παντελῶς ἀόρατος ἦν. εἶχε μὲν οὖν οὕτως ὀχυρότητος Ἰωταπάτη·"},{"number":161,"text":"Οὐεσπασιανὸς δὲ τῇ τε φύσει τοῦ χωρίου καὶ ταῖς τόλμαις τῶν Ἰουδαίων ἀντιφιλονεικῶν ἔγνω καρτερώτερον ἅπτεσθαι τῆς πολιορκίας, καὶ προσκαλεσάμενος τοὺς ὑπʼ αὐτὸν ἡγεμόνας ἐβουλεύετο περὶ τῆς προσβολῆς."},{"number":162,"text":"δόξαν δὲ χῶσαι τὸ προσιτὸν τοῦ τείχους ἐπὶ συγκομιδὴν ὕλης ἐκπέμπει πᾶν τὸ στράτευμα, καὶ κοπέντων τῶν περὶ τὴν πόλιν ὀρῶν συναλισθείσης τε ἅμα τοῖς ξύλοις ἀπείρου χερμάδος,"},{"number":163,"text":"οἱ μὲν πρὸς ἀλεωρὰν τῶν ὕπερθεν ἀφιεμένων βελῶν γέρρα διατείναντες ὑπὲρ χαρακωμάτων ἔχουν ὑπʼ αὐτοῖς οὐδὲν ἢ μικρὰ βλαπτόμενοι ταῖς ἀπὸ τοῦ τείχους βολαῖς·"},{"number":164,"text":"οἱ δὲ τοὺς πλησίον ὄχθους ἀνασπῶντες γῆν αὐτοῖς ἀδιαλείπτως ἔφερον, καὶ τριχῆ διῃρημένων ἀργὸς ἦν οὐδείς."},{"number":165,"text":"οἱ δὲ Ἰουδαῖοι πέτρας τε μεγάλας ἀπὸ τῶν τειχῶν τοῖς σκεπάσμασιν αὐτῶν ἐπηφίεσαν καὶ πᾶν εἶδος βελῶν· ἦν δὲ καὶ μὴ διικνουμένων πολὺς ὁ ψόφος καὶ φοβερὸς ἐμπόδιον τοῖς ἐργαζομένοις."},{"number":166,"text":"Οὐεσπασιανὸς δὲ ἐν κύκλῳ τὰς ἀφετηρίους μηχανὰς ἐπιστήσας, τὰ πάντα δʼ ἦν ἑκατὸν ἑξήκοντα ὄργανα, βάλλειν ἐκέλευσεν τοὺς ἐπὶ τοῦ τείχους."},{"number":167,"text":"ὁμοῦ δὲ οἵ τε καταπέλται τὰς λόγχας ἀνερροίζουν καὶ ταλαντιαῖοι λίθοι μέγεθος ἐκ τῶν πετροβόλων ἐβάλλοντο πῦρ τε καὶ πλῆθος ἀθρόων οἰστῶν, ἅπερ οὐ μόνον τὸ τεῖχος ἀνεπίβατον τοῖς Ἰουδαίοις ἐποίησεν, ἀλλὰ καὶ τὴν ἐντὸς ὅσης ἐφικνεῖτο χώρας·"},{"number":168,"text":"καὶ γὰρ καὶ τὸ τῶν Ἀράβων τοξοτῶν πλῆθος ἀκοντισταί τε καὶ σφενδονῆται πάντες ἅμα τοῖς μηχανήμασιν ἔβαλλον."},{"number":169,"text":"οὐ μὴν εἰργόμενοι τῆς καθύπερθεν ἀμύνης ἠρέμουν· ἐκτρέχοντες γὰρ λῃστρικώτερον κατὰ λόχους περιέσπων τε τῶν ἐργαζομένων τὰς σκέπας καὶ τοὺς γυμνουμένους ἔπαιον, καὶ καθʼ ὃ παρείκοιεν ἐκεῖνοι διερρίπτουν τε τὸ χῶμα καὶ τὰ χαρακώματα σὺν τοῖς γέρροις ἐνεπίμπρασαν,"},{"number":170,"text":"μέχρι συνεὶς Οὐεσπασιανὸς τὴν διαίρεσιν τῶν ἔργων αἰτίαν εἶναι τῆς βλάβης, τὰ γὰρ διαστήματα τοῖς Ἰουδαίοις προσβολῆς παρεῖχεν τόπον, ἑνοῖ τὰ σκεπάσματα, καὶ συναφθείσης ἅμα αὐτοῖς τῆς δυνάμεως ἀνείρχθησαν αἱ τῶν Ἰουδαίων παραδύσεις."},{"number":171,"text":"Ἐγειρομένου δὲ τοῦ χώματος ἤδη καὶ ταῖς ἐπάλξεσιν ὅσον οὔπω πλησιάζοντος δεινὸν ὁ Ἰώσηπος νομίσας, εἰ μηδὲν ἀντιμηχανήσαιτο τῇ πόλει σωτήριον, συναθροίζει τέκτονας καὶ τὸ τεῖχος ἐκέλευσεν ὑψοῦν."},{"number":172,"text":"τῶν δʼ ἀδύνατον εἶναι φαμένων οἰκοδομεῖν τοσούτοις βέλεσι βαλλομένους, σκέπην αὐτοῖς ἐπινοεῖ τοιάνδε·"},{"number":173,"text":"δρυφάκτους πήξασθαι κελεύσας ἐμπετάσαι τε βύρσας νεοδόρους βοῶν, ὡς ἀναδέχοιντο μὲν τοὺς ἀπὸ τῶν πετροβόλων λίθους κολπούμεναι, περιολισθάνοι δὲ ἀπʼ αὐτῶν καὶ τὰ λοιπὰ βέλη καὶ τὸ πῦρ ὑπὸ τῆς ἰκμάδος εἴργοιτο, προανίστησιν τῶν τεκτόνων."},{"number":174,"text":"ὑφʼ οἷς ἀσφαλῶς ἐργαζόμενοι διʼ ἡμέρας τε καὶ νυκτὸς τὸ τεῖχος ἤγειραν εἰς εἴκοσι πήχεις τὸ ὕψος, καὶ συχνοὺς μὲν πύργους ἐνῳκοδόμησαν αὐτῷ, καρτερὰν δὲ ἔπαλξιν ἐφηρμόσαντο."},{"number":175,"text":"τοῦτο τοῖς Ῥωμαίοις ἤδη τῆς πόλεως ἐντὸς οἰομένοις εἶναι πολλὴν ἐποίησεν ἀθυμίαν, καὶ πρός τε τὴν ἐπίνοιαν τοῦ Ἰωσήπου καὶ τὸ παράστημα τῶν ἐπὶ τῆς πόλεως κατεπλάγησαν."},{"number":176,"text":"Οὐεσπασιανὸς δὲ καὶ πρὸς τὸ πανοῦργον τοῦ στρατηγήματος καὶ πρὸς τὰς τόλμας παρωξύνετο τῶν Ἰωταπατηνῶν·"},{"number":177,"text":"πάλιν γὰρ ἀναθαρσήσαντες ἐπὶ τῷ τειχισμῷ τοῖς Ῥωμαίοις ἐπεξέθεον, καὶ καθʼ ἡμέραν ἐγίνοντο συμπλοκαὶ κατὰ λόχους ἐπίνοιά τε λῃστρικὴ πᾶσα καὶ τῶν προστυχόντων ἁρπαγαὶ καὶ τῶν ἄλλων ἔργων πυρπολήσεις,"},{"number":178,"text":"ἕως Οὐεσπασιανὸς ἀναπαύσας τὴν στρατιὰν μάχης διέγνω προσκαθεζόμενος σπάνει τῶν ἐπιτηδείων αἱρεῖν τὴν πόλιν·"},{"number":179,"text":"ἢ γὰρ ἀναγκαζομένους ταῖς ἀπορίαις ἱκετεύσειν αὐτὸν ἢ μέχρι παντὸς ἀπαυθαδισαμένους διαφθαρήσεσθαι λιμῷ."},{"number":180,"text":"πολύ τε ῥᾴοσιν αὐτοῖς ἠξίου χρήσεσθαι κατὰ τὴν μάχην, εἰ διαλιπὼν αὖθις ἐκτετρυχωμένοις ἐπιπέσοι. φρουρεῖν δὴ πάσας αὐτῶν ἐκέλευσεν τὰς ἐξόδους."},{"number":181,"text":"Τοῖς δὲ σίτου μὲν πλῆθος ἦν ἔνδον καὶ τῶν ἄλλων πλὴν ἁλὸς ἁπάντων, ἔνδεια δὲ ὕδατος ὡς ἂν πηγῆς μὲν οὐκ οὔσης κατὰ τὴν πόλιν, τῷ δʼ ὀμβρίῳ διαρκουμένων τῶν ἐν αὐτῇ· σπάνιον δʼ εἴ ποτε τὸ κλίμα θέρους ὕεται."},{"number":182,"text":"καὶ κατὰ ταύτην τὴν ὥραν πολιορκουμένων ἀθυμία δεινὴ πρὸς τὴν τοῦ δίψους ἐπίνοιαν ἦν, ἀσχαλλόντων ἤδη ὡς καθάπαν ἐπιλελοιπότος ὕδατος·"},{"number":183,"text":"ὁ γὰρ Ἰώσηπος τήν τε πόλιν ὁρῶν τῶν ἄλλων ἐπιτηδείων εὔπορον καὶ τὰ φρονήματα γενναῖα τῶν ἀνδρῶν, βουλόμενός τε παρʼ ἐλπίδα τοῖς Ῥωμαίοις ἐκτεῖναι τὴν πολιορκίαν, μέτρῳ τὸ ποτὸν αὐτοῖς διένειμεν εὐθέως."},{"number":184,"text":"οἱ δὲ τὸ ταμιεύεσθαι χαλεπώτερον ἐνδείας ὑπελάμβανον, καὶ τὸ μὴ αὐτεξούσιον αὐτῶν πλέον ἐκίνει τὴν ὄρεξιν, καὶ καθάπερ εἰς ἔσχατον ἤδη δίψους προήκοντες ἀπέκαμνον. διακείμενοι δὲ οὕτως οὐκ ἐλάνθανον τοὺς Ῥωμαίους·"},{"number":185,"text":"ἀπὸ γὰρ τοῦ κατάντους ἑώρων αὐτοὺς ὑπὲρ τὸ τεῖχος ἐφʼ ἕνα συρρέοντας τόπον καὶ μετρουμένους τὸ ὕδωρ, ἐφʼ ὃν καὶ τοῖς ὀξυβελέσιν ἐξικνούμενοι πολλοὺς ἀνῄρουν."},{"number":186,"text":"Καὶ Οὐεσπασιανὸς μὲν οὐκ εἰς μακρὰν τῶν ἐκδοχείων κενωθέντων ἤλπιζεν ὑπὸ τῆς ἀνάγκης αὐτῷ παραδοθήσεσθαι τὴν πόλιν·"},{"number":187,"text":"ὁ δὲ Ἰώσηπος κλάσαι τὴν ἐλπίδα ταύτην αὐτῷ προαιρούμενος ἐμβρέξαι κελεύει πλείστους τὰ ἱμάτια καὶ κατακρεμάσαι περὶ τὰς ἐπάλξεις, ὥστε περιρρεῖσθαι πᾶν ἐξαπίνης τὸ τεῖχος."},{"number":188,"text":"πρὸς τοῦτʼ ἀθυμία τῶν Ῥωμαίων καὶ κατάπληξις ἦν θεασαμένων εἰς χλεύην τοσοῦτον παραναλίσκοντας ὕδατος οὓς οὐδὲ ποτὸν ἔχειν ὑπελάμβανον, ὥστε καὶ τὸν στρατηγὸν ἀπογνόντα τὴν διʼ ἐνδείας ἅλωσιν τρέπεσθαι πάλιν πρὸς ὅπλα καὶ βίαν."},{"number":189,"text":"ὃ δὴ τοῖς Ἰουδαίοις διʼ ἐπιθυμίας ἦν· ἀπεγνωκότες γὰρ ἑαυτοὺς καὶ τὴν πόλιν πρὸ λιμοῦ καὶ δίψης τὸν ἐν πολέμῳ θάνατον ᾑροῦντο."},{"number":190,"text":"Ὁ μέντοι γε Ἰώσηπος πρὸς τῷδε τῷ στρατηγήματι καὶ ἕτερον ἐπενόησεν εἰς περιουσίαν αὐτῷ·"},{"number":191,"text":"διά τινος χαράδρας δυσβάτου καὶ διὰ τοῦθʼ ὑπὸ τῶν φυλάκων ἀμελουμένης κατὰ τὰ πρὸς δύσιν μέρη τῆς φάραγγος ἐκπέμπων τινὰς γράμματά τε πρὸς οὓς ἠβούλετο τῶν ἔξω Ἰουδαίων διεπέμψατο καὶ παρʼ αὐτῶν ἐλάμβανεν, παντός τε ἐπιτηδείου τῶν ἀνὰ τὴν πόλιν ἐπιλελοιπότων εὐπόρησεν,"},{"number":192,"text":"ἕρπειν τὰ πολλὰ παρὰ τὰς φυλακὰς κελεύσας τοῖς ἐξιοῦσιν καὶ τὰ νῶτα καλύπτειν νάκεσιν, ὡς εἰ καὶ κατίδοι τις αὐτοὺς νύκτωρ, φαντασίαν παρέχοιεν κυνῶν, μέχρι συναισθόμενοι τὴν ἐπίνοιαν οἱ φρουροὶ περιίσχουσιν τὴν χαράδραν."},{"number":193,"text":"Καὶ τόθʼ ὁ Ἰώσηπος μὲν τὴν πόλιν οὐκ εἰς μακρὰν ὁρῶν ἀνθέξειν, ἐν ἀπόρῳ δὲ τὴν ἑαυτῶν σωτηρίαν εἰ μένοι, δρασμὸν ἅμα τοῖς δυνατοῖς ἐβουλεύετο. συναισθόμενοι δὲ τὸ πλῆθος καὶ περιχυθὲν αὐτῷ κατηντιβόλουν μὴ σφᾶς περιιδεῖν ἐπʼ αὐτῷ μόνῳ κειμένους·"},{"number":194,"text":"εἶναι γὰρ τῇ πόλει καὶ σωτηρίας μὲν ἐλπὶς παραμένων, παντὸς ἀγωνισομένου διʼ αὐτὸν προθύμως, κἂν ἁλῶσιν δέ, παραμυθίαν."},{"number":195,"text":"πρέπειν δʼ αὐτῷ μήτε φυγεῖν τοὺς ἐχθροὺς μήτʼ ἐγκαταλιπεῖν τοὺς φίλους μήτʼ ἀποπηδᾶν ὥσπερ χειμαζομένης νεώς, εἰς ἣν ἐν γαλήνῃ παρῆλθεν·"},{"number":196,"text":"ἐπιβαπτίσειν γὰρ αὐτοῖς τὴν πόλιν μηδενὸς ἔτι τοῖς πολεμίοις τολμῶντος ἀνθίστασθαι διʼ ὃν ἂν θαρσοῖεν οἰχομένου."},{"number":197,"text":"Ὁ δὲ Ἰώσηπος τὸ κατʼ αὐτὸν ἀσφαλὲς ὑποστελλόμενος ὑπὲρ αὐτῶν ἔφασκεν ποιεῖσθαι τὴν ἔξοδον·"},{"number":198,"text":"μένων μὲν γὰρ οὔτʼ ἂν ὠφελῆσαί τι μέγα σωζομένους, κἂν ἁλίσκωνται, συναπολεῖσθαι περιττῶς, ἐκδὺς δὲ τῆς πολιορκίας ἔξωθεν αὐτοὺς ὠφελήσειν μέγιστα·"},{"number":199,"text":"τούς τε γὰρ ἐκ τῆς χώρας Γαλιλαίους συναθροίσειν ᾗ τάχος καὶ Ῥωμαίους ἑτέρῳ πολέμῳ τῆς πόλεως αὐτῶν ἀντιπερισπάσειν."},{"number":200,"text":"οὐχ ὁρᾶν δέ, τί παρακαθεζόμενος αὐτοῖς χρήσιμος εἴη νῦν, πλὴν εἰ μὴ Ῥωμαίους παροξύνων μᾶλλον ἐπὶ τὴν πολιορκίαν, οὓς περὶ πλείστου ποιεῖσθαι λαβεῖν αὐτόν· εἰ δʼ ἐκδράντα πύθοιντο, πολὺ τῆς ἐπὶ τὴν πόλιν ὁρμῆς ἀνήσειν."},{"number":201,"text":"οὐκ ἔπειθεν δὲ τούτοις, ἀλλὰ μᾶλλον ἐξέκαυσεν τὸ πλῆθος αὐτοῦ περιέχεσθαι· παιδία γοῦν καὶ γέροντες καὶ γύναια μετὰ νηπίων ὀδυρόμενα προσέπιπτον αὐτῷ καὶ τοῖς ποσὶν ἐμπλεκόμενοι πάντες εἴχοντο,"},{"number":202,"text":"καὶ μετὰ κωκυτῶν κοινωνὸν σφίσι τῆς τύχης μένειν ἱκέτευον, οὐ φθόνῳ τῆς ἐκείνου σωτηρίας, ἔμοιγε δοκεῖν, ἀλλʼ ἐλπίδι τῆς ἑαυτῶν· οὐδὲν γὰρ ἠξίουν πείσεσθαι δεινὸν Ἰωσήπου μένοντος."},{"number":203,"text":"Ὁ δὲ πειθομένῳ μὲν ἱκετηρίαν ταῦτα νομίσας, βιαζομένῳ δὲ φρουράν, πολὺ δʼ αὐτοῦ τῆς εἰς τὴν ἀπόλειψιν ὁρμῆς καὶ ὁ τῶν ὀδυρομένων ἔκλασεν οἶκτος,"},{"number":204,"text":"μένειν τε ἔγνω, καὶ τὴν κοινὴν τῆς πόλεως ἀπόγνωσιν ὁπλισάμενος, νῦν καιρός, εἰπών, ἄρχεσθαι μάχης, ὅτʼ ἐλπὶς οὐκ ἔστι σωτηρίας· καλὸν εὔκλειαν ἀντικαταλλαξάμενον τοῦ βίου καὶ δράσαντά τι γενναῖον εἰς μνήμην ὀψιγενῶν πεσεῖν, ἐπʼ ἔργα τρέπεται."},{"number":205,"text":"καὶ προελθὼν μετὰ τῶν μαχιμωτάτων διεσκίδνα τε τοὺς φρουροὺς καὶ μέχρι τοῦ στρατοπέδου τῶν Ῥωμαίων κατέτρεχεν, καὶ τὰς μὲν ἐπὶ τῶν χωμάτων δέρρεις, αἷς ὑπεσκήνουν, διέσπα, τοῖς δὲ ἔργοις ἐνέβαλλεν πῦρ."},{"number":206,"text":"τῇ τε ἑξῆς ὁμοίως καὶ τῇ τρίτῃ καὶ ἐπὶ συχνὰς ἡμέρας καὶ νύκτας πολεμῶν οὐκ ἔκαμνεν."},{"number":207,"text":"Οὐεσπασιανὸς δὲ τῶν [τε] Ῥωμαίων κακουμένων ταῖς ἐκδρομαῖς, τρέπεσθαί τε γὰρ ὑπὸ Ἰουδαίων ᾐδοῦντο καὶ τραπέντων ἐπιδιώκειν βάρει τῶν ὅπλων ἦσαν βραδεῖς, οἵ τε Ἰουδαῖοι πρίν τι παθεῖν ἀεὶ δρῶντες ἀνέφευγον εἰς τὴν πόλιν,"},{"number":208,"text":"τοῖς μὲν ὁπλίταις τὰς ὁρμὰς αὐτῶν ἐκκλίνειν ἐκέλευσεν καὶ μὴ συμπλέκεσθαι θανατῶσιν ἀνθρώποις·"},{"number":209,"text":"οὐδὲν γὰρ ἀλκιμώτερον εἶναι τῆς ἀπογνώσεως, περισβέννυσθαι δὲ αὐτῶν τὰς ὁρμὰς σκοπῶν ἀπορουμένας ὥσπερ ὕλης τὸ πῦρ·"},{"number":210,"text":"προσήκειν γε μὴν καὶ Ῥωμαίοις μετὰ ἀσφαλείας καὶ τὸ νικᾶν, ὡς ἂν οὐκ ἐξ ἀνάγκης πολεμοῦσιν, ἀλλὰ προσκτωμένοις."},{"number":211,"text":"τοῖς δὲ τῶν Ἀράβων τοξόταις καὶ τοῖς ἀπὸ τῆς Συρίας σφενδονήταις καὶ λιθοβόλοις τὰ πολλὰ τοὺς Ἰουδαίους ἀνέστελλεν· ἠρέμει δὲ οὐδὲ τῶν ἀφετηρίων ὀργάνων τὸ πλῆθος."},{"number":212,"text":"οἱ δὲ τούτοις μὲν εἶκον κακούμενοι, τῶν δὲ πόρρω βαλλομένων ἐνδοτέρω γινόμενοι προσέκειντο τοῖς Ῥωμαίοις χαλεποὶ καὶ ψυχῆς καὶ σώματος ἀφειδοῦντες ἐμάχοντο, ἐκ διαδοχῆς ἑκάτεροι τὸ κεκμηκὸς ἑαυτῶν ἀναλαμβάνοντες."},{"number":213,"text":"Οὐεσπασιανὸς δὲ ἡγούμενος τῷ μήκει τοῦ χρόνου καὶ ταῖς ἐκδρομαῖς ἀντιπολιορκεῖσθαι, τῶν χωμάτων ἤδη τοῖς τείχεσι πελαζόντων προσάγειν ἔγνω τὸν κριόν."},{"number":214,"text":"ὁ δʼ ἐστὶν ὑπερμεγέθης δοκὸς ἱστῷ νηὸς παραπλήσιος· ἐστόμωται δὲ παχεῖ σιδήρῳ κατʼ ἄκρον εἰς κριοῦ προτομήν, ἀφʼ οὗ καὶ καλεῖται, τετυπωμένῳ."},{"number":215,"text":"καταιωρεῖται δὲ κάλοις μέσος ὥσπερ ἀπὸ πλάστιγγος ἑτέρας δοκοῦ, σταυροῖς ἑκατέρωθεν ἑδραίοις ὑπεστηριγμένης."},{"number":216,"text":"ἀνωθούμενος δὲ ὑπὸ πλήθους ἀνδρῶν εἰς τὸ κατόπιν, τῶν αὐτῶν ἀθρόως πάλιν εἰς τοὔμπροσθεν ἐπιβρισάντων τύπτει τὰ τείχη τῷ προανέχοντι σιδήρῳ."},{"number":217,"text":"καὶ οὐδεὶς οὕτως καρτερὸς πύργος ἢ περίβολος πλατύς, ὃς κἂν τὰς πρώτας πληγὰς ἐνέγκῃ κατίσχυσεν τῆς ἐπιμονῆς."},{"number":218,"text":"ἐπὶ ταύτην τὴν πεῖραν ὁ στρατηγὸς τῶν Ῥωμαίων μετέβαινεν βίᾳ τὴν πόλιν ἑλεῖν σπεύδων, ὡς τὸ προσκαθέζεσθαι βλαβερὸν ἦν Ἰουδαίων οὐκ ἠρεμούντων."},{"number":219,"text":"οἱ μὲν οὖν τούς τε καταπέλτας καὶ τὰ λοιπὰ τῶν ἀφετηρίων, ὡς ἐξικνοῖτο τῶν ἐπὶ τοῦ τείχους κωλύειν πειρωμένων, ἔγγιον προσαγαγόντες ἔβαλλον· ὁμοίως δὲ συνήγγιζον οἱ τοξόται καὶ σφενδονῆται."},{"number":220,"text":"διὰ δὲ ταῦτα μηδενὸς τῶν περιβόλων ἐπιβῆναι τολμῶντος προσῆγον ἕτεροι τὸν κριὸν γέρροις τε διηνεκέσι καὶ καθύπερθεν πεφραγμένον δέρρει πρός τε αὐτῶν καὶ τοῦ μηχανήματος ἀσφάλειαν."},{"number":221,"text":"καὶ κατὰ τὴν πρώτην πληγὴν διεσείσθη μὲν τὸ τεῖχος, κραυγὴ δὲ μεγίστη παρὰ τῶν ἔνδον ἤρθη καθάπερ ἑαλωκότων ἤδη."},{"number":222,"text":"Πολλάκις δὲ εἰς τὸν αὐτὸν παίοντας τόπον ὁ Ἰώσηπος ὁρῶν ὅσον οὔπω καταρριφθησόμενον τὸ τεῖχος, σοφίζεται κατʼ ὀλίγον τὴν βίαν τοῦ μηχανήματος."},{"number":223,"text":"σάκκους ἀχύρων πληρώσαντας ἐκέλευσεν καθιμᾶν καθʼ ὃ φερόμενον ἀεὶ τὸν κριὸν ὁρῷεν, ὡς πλάζοιτό τε ἡ ἐμβολή, καὶ δεχόμενοι τὰς πληγὰς ἐκκενοῖεν τῇ χαυνότητι."},{"number":224,"text":"τοῦτο πλείστην διατριβὴν παρέσχεν τοῖς Ῥωμαίοις, καθʼ ὃ μὲν τρέποιεν τὴν μηχανὴν ἀντιπαραγόντων τοὺς σάκκους τῶν ὕπερθεν, ὑποβαλλόντων δὲ ταῖς ἐμβολαῖς, ὡς μηδὲν κατʼ ἀντιτυπίαν βλάπτεσθαι τὸ τεῖχος·"},{"number":225,"text":"ἕως ἀντεπινοήσαντες κοντοὺς οἱ Ῥωμαῖοι μακροὺς καὶ δρέπανα δήσαντες ἐπʼ ἄκρων τοὺς σάκους ἀπέτεμνον."},{"number":226,"text":"ἐνεργοῦς δὲ οὕτω τῆς ἑλεπόλεως γενομένης καὶ τοῦ τείχους, νεοπαγὲς γὰρ ἦν, ἐνδιδόντος ἤδη, τὸ λοιπὸν ἐπὶ τὴν ἐκ πυρὸς ἄμυναν οἱ περὶ τὸν Ἰώσηπον ὥρμησαν."},{"number":227,"text":"ἁψάμενοι δὲ ὅσον αὔης εἶχον ὕλης τριχόθεν ἐπεκθέουσιν, καὶ τά τε μηχανήματα καὶ τὰ γέρρα καὶ τὰ χώματα τῶν Ῥωμαίων ὑπεπίμπρασαν."},{"number":228,"text":"οἱ δὲ κακῶς ἐπεβοήθουν πρός τε τὴν τόλμαν αὐτῶν καταπεπληγότες καὶ ὑπὸ τῆς φλογὸς τὰς ἀμύνας φθανόμενοι· ξηρᾶς γὰρ ὕλης, πρὸς δὲ ἀσφάλτου τε καὶ πίσσης, ἔτι δὲ θείου διίπτατο τὸ πῦρ ἐπινοίας τάχιον, καὶ τὰ πολλῷ καμάτῳ πεπονημένα τοῖς Ῥωμαίοις ἐπὶ μιᾶς ὥρας ἐνέμετο."},{"number":229,"text":"Ἔνθα καὶ ἀνήρ τις ἐξεφάνη Ἰουδαίων λόγου καὶ μνήμης ἄξιος· Σαμίου μὲν παῖς ἦν, Ἐλεάζαρος δὲ ἐκαλεῖτο, Σαβὰ δὲ πατρὶς αὐτῷ τῆς Γαλιλαίας·"},{"number":230,"text":"ὑπερμεγέθη δὲ πέτραν ἀράμενος ἀφίησιν ἀπὸ τοῦ τείχους ἐπὶ τὴν ἑλέπολιν μετὰ τοσαύτης βίας, ὥστε ἀπορρῆξαι τὴν κεφαλὴν τοῦ μηχανήματος, ἣν καὶ καταπηδήσας ἐκ μέσων αἴρεται τῶν πολεμίων καὶ μετὰ πολλῆς ἀδείας ἐπὶ τὸ τεῖχος ἔφερεν."},{"number":231,"text":"σκοπὸς δὲ πᾶσιν τοῖς ἐχθροῖς γενόμενος καὶ γυμνῷ τῷ σώματι τὰς πληγὰς δεξάμενος πέντε μὲν διαπείρεται βέλεσιν,"},{"number":232,"text":"πρὸς οὐδὲν δὲ τούτων ἐπιστραφείς, ὅτε τὸ τεῖχος ἀνέβη καὶ περίοπτος πᾶσιν τῆς εὐτολμίας ἔστη, τότε ἰλυσπώμενος ὑπὸ τῶν τραυμάτων μετὰ τοῦ κριοῦ κατέπεσεν."},{"number":233,"text":"ἄριστοι μετʼ αὐτὸν ἐφάνησαν ἀδελφοὶ δύο Νετείρας καὶ Φίλιππος, ἀπὸ Ῥούμας κώμης, Γαλιλαῖοι καὶ αὐτοί, οἳ προπηδῶσι μὲν εἰς τοὺς ἀπὸ τοῦ δεκάτου τάγματος, τοσούτῳ δὲ ῥοίζῳ καὶ βίᾳ τοῖς Ῥωμαίοις συνέπεσον, ὡς διαρρῆξαί τε τὰς τάξεις καὶ τρέψασθαι καθʼ οὓς ἐφορμήσειαν ἅπαντας."},{"number":234,"text":"Μετὰ τούτους ὅ τε Ἰώσηπος καὶ τὸ λοιπὸν πλῆθος ἀράμενοι πῦρ πάλιν τὰ μηχανήματα καὶ τὰς ὑποδύσεις ἅμα τοῖς ἔργοις ὑφῆψαν τοῦ τε πέμπτου καὶ τοῦ δεκάτου τραπέντος τάγματος, οἱ λοιποὶ δὲ φθάσαντες καὶ τὰ ὄργανα καὶ πᾶσαν ὕλην κατέχωσαν."},{"number":235,"text":"περὶ δὲ δείλην πάλιν ἀναστήσαντες προσῆγον τὸν κριὸν ᾗ προπεπονήκει τυπτόμενον τὸ τεῖχος."},{"number":236,"text":"ἔνθα τις τῶν ἀμυνομένων ἀπʼ αὐτοῦ βάλλει τὸν Οὐεσπασιανὸν βέλει κατὰ τὸν ταρσὸν τοῦ ποδὸς καὶ τιτρώσκει μὲν ἐπιπολαίως προεκλύσαντος τὸ βληθὲν τοῦ διαστήματος, μέγιστον δὲ θόρυβον ἐνεποίησεν τοῖς Ῥωμαίοις·"},{"number":237,"text":"πρὸς γὰρ τὸ αἷμα ταραχθέντων τῶν πλησίον φήμη διὰ παντὸς ἐπῄει τοῦ στρατοῦ, καὶ τῆς πολιορκίας οἱ πλείους ἀφέμενοι μετʼ ἐκπλήξεως καὶ δέους ἐπὶ τὸν στρατηγὸν συνέθεον."},{"number":238,"text":"πρὸ δὲ πάντων Τίτος δείσας περὶ τῷ πατρὶ παρῆν, ὡς τὸ πλῆθος καὶ τῇ πρὸς τὸν ἡγούμενον εὐνοίᾳ καὶ τῇ τοῦ παιδὸς ἀγωνίᾳ συγχυθῆναι. ῥᾷστα μέντοι τόν τε υἱὸν ὁ πατὴρ δεδιότα καὶ τὴν στρατιὰν ἔπαυσεν τοῦ θορύβου·"},{"number":239,"text":"τῶν γὰρ ἀλγηδόνων ἐπάνω γενόμενος καὶ πᾶσιν τοῖς ἐπτοημένοις διʼ αὐτὸν ὀφθῆναι σπουδάσας χαλεπώτερον Ἰουδαίοις ἐπῆρεν τὸν πόλεμον· ἕκαστος γὰρ ὡς τιμωρὸς τοῦ στρατηγοῦ προκινδυνεύειν ἤθελεν, καὶ βοῇ παρακροτοῦντες ἀλλήλους ἐπὶ τὸ τεῖχος ὥρμων."},{"number":240,"text":"Οἱ δὲ περὶ τὸν Ἰώσηπον καίπερ ἐπʼ ἀλλήλοις πίπτοντες ὑπὸ τῶν καταπελτικῶν καὶ τῶν πετροβόλων, ὅμως οὐκ ἀπετρέποντο τοῦ τείχους, ἀλλὰ πυρὶ καὶ σιδήρῳ καὶ πέτροις τοὺς ἐπὶ τὰ γέρρα τὸν κριὸν ἐπιβρίθοντας ἔβαλλον."},{"number":241,"text":"καὶ ἤνυον μὲν οὐδὲν ἢ μικρόν, αὐτοὶ δὲ ἀδιαλείπτως ἔπιπτον ὑπὸ μὴ βλεπομένων καθορώμενοι·"},{"number":242,"text":"αὐτοί τε γὰρ ὑπὸ τῆς σφετέρας περιλαμπόμενοι φλογὸς σκοπὸς ἦσαν τοῖς πολεμίοις εὐσύνοπτος ὥσπερ ἐν ἡμέρᾳ, καὶ τῶν ὀργάνων πόρρωθεν μὴ βλεπομένων δυσφύλακτον ἦν τὸ βαλλόμενον."},{"number":243,"text":"ἥ τε οὖν τῶν ὀξυβελῶν καὶ καταπελτῶν βία πολλοὺς ἅμα διήλαυνεν, καὶ τῶν ὑπὸ τῆς μηχανῆς ἀφιεμένων πετρῶν ὁ ῥοῖζος ἐπάλξεις τε ἀπέσυρεν καὶ γωνίας ἀπέθρυπτε πύργων."},{"number":244,"text":"ἀνδρῶν μὲν γὰρ † οὕτως ἰσχυρὸν στῖφος, ὃ μὴ μέχρις ἐσχάτης στρώννυται φάλαγγος βίᾳ τε καὶ μεγέθει τοῦ λίθου."},{"number":245,"text":"μάθοι δʼ ἄν τις τὴν τοῦ μηχανήματος ἀλκὴν ἐκ τῶν ἐπὶ τῆσδε τῆς νυκτὸς γενομένων· πληγεὶς γάρ τις ἀπʼ αὐτοῦ τῶν περὶ τὸν Ἰώσηπον ἑστώτων ἀνὰ τὸ τεῖχος ἀπαράσσεται τὴν κεφαλὴν ὑπὸ τῆς πέτρας, καὶ τὸ κρανίον ἀπὸ τριῶν ἐσφενδονήθη σταδίων."},{"number":246,"text":"γυναικός τε μεθʼ ἡμέραν ἐγκύμονος πληγείσης τὴν γαστέρα, προῄει δὲ νέον ἐξ οἰκίας, ἐξέσεισεν ἐφʼ ἡμιστάδιον τὸ βρέφος· τοσαύτη ἦν ἡ τοῦ λιθοβόλου βία."},{"number":247,"text":"τῶν οὖν ὀργάνων φοβερώτερος ὁ ῥοῖζος, τῶν δὲ βαλλομένων ἦν [ὁ] ψόφος."},{"number":248,"text":"ἐπάλληλοι δὲ ἐκτύπουν οἱ νεκροὶ κατὰ τοῦ τείχους ῥιπτόμενοι, καὶ δεινὴ μὲν ἔνδοθεν κραυγὴ γυναικῶν ἠγείρετο, συνήχουν δʼ ἔξωθεν οἰμωγαὶ φονευομένων."},{"number":249,"text":"αἵματι δʼ ἐρρεῖτο πᾶς ὁ πρὸ τῆς μάχης περίβολος, καὶ προσβατὸν ὑπὸ πτωμάτων τὸ τεῖχος ἐγίνετο."},{"number":250,"text":"φοβερωτέραν δὲ ἐποίουν τὴν βοὴν περιηχοῦντα τὰ ὄρη, καὶ οὐδὲν ἐπʼ ἐκείνης τῆς νυκτὸς οὔτε εἰς ἀκοῆς οὔτε εἰς ὄψεως κατάπληξιν ἀπελείπετο."},{"number":251,"text":"πλεῖστοι μέν γε τῶν ἐπὶ τῆς Ἰωταπάτης ἀγωνιζόμενοι γενναίως ἔπεσον, πλεῖστοι δʼ ἐγένοντο τραυματίαι, καὶ μόλις περὶ τὴν ἑωθινὴν φυλακὴν ἐνδίδωσι τοῖς μηχανήμασι τὸ τεῖχος ἀδιαλείπτως τυπτόμενον·"},{"number":252,"text":"οἱ δὲ φραξάμενοι τοῖς σώμασι καὶ τοῖς ὅπλοις τὸ καταρριφθὲν ἀντωχύρωσαν πρὶν βληθῆναι τὰς ἐπιβατηρίους ὑπὸ τῶν Ῥωμαίων μηχανάς."},{"number":253,"text":"Ὑπὸ δὲ τὴν ἕω Οὐεσπασιανὸς ἐπὶ τὴν κατάληψιν τῆς πόλεως συνῆγεν τὴν στρατιὰν ὀλίγον ἀπὸ τοῦ νυκτερινοῦ πόνου διαναπαύσας."},{"number":254,"text":"βουλόμενος δʼ ἀπὸ τῶν καταρριφθέντων περισπάσαι τοὺς εἴργοντας τοὺς μὲν γενναιοτάτους τῶν ἱππέων ἀποβήσας [τῶν ἵππων] τριχῇ διέταξεν κατὰ τὰ πεπτωκότα τοῦ τείχους, πάντοθεν πεφραγμένους τοῖς ὅπλοις καὶ τοὺς κοντοὺς προΐσχοντας, ὡς ὁπότε τὰς ἐπιβατηρίους βάλλοιεν μηχανὰς κατάρχοιντο τῆς εἰσόδου·"},{"number":255,"text":"κατόπιν δὲ αὐτῶν ἔταξεν τοῦ πεζοῦ τὸ ἀκμαιότατον, τὸ δὲ λοιπὸν ἱππικὸν ἀντιπαρεξέτεινεν τῷ τείχει κατὰ πᾶσαν τὴν ὀρεινὴν πρὸς τὸ μηδένα τῶν ἀναφευγόντων ἐκ τῆς ἁλώσεως διαλαθεῖν."},{"number":256,"text":"κατόπιν δὲ τούτων περιέστησεν τοὺς τοξότας ἔχειν κελεύσας ἕτοιμα τὰ βέλη πρὸς ἄφεσιν, ὁμοίως δὲ καὶ σφενδονήτας καὶ τοὺς ἐπὶ τῶν μηχανημάτων,"},{"number":257,"text":"ἑτέρους δὲ κλίμακας ἀραμένους προσφέρειν ἐπάνω τοῖς ἀκεραίοις τείχεσιν, ἵνʼ οἱ μὲν τούτους κωλύειν πειρώμενοι καταλίποιεν τὴν ἐπὶ τοῖς καταρριφθεῖσιν φυλακήν, οἱ λοιποὶ δὲ ὑπʼ ἀθρόων βιαζόμενοι τῶν βελῶν εἴξωσιν τῆς εἰσόδου."},{"number":258,"text":"Ἰώσηπος δὲ συνιεὶς τὴν ἐπίνοιαν ἐπὶ μὲν τοῦ μένοντος τείχους σὺν τοῖς κεκμηκόσιν ἵστησι τοὺς γηραιοὺς ὡς μηδὲν ταύτῃ βλαβησομένους, εἰς δὲ τὰ παρερρωγότα τοῦ τείχους τοὺς δυνατωτάτους καὶ πρὸ πάντων ἀνὰ ἓξ ἄνδρας, μεθʼ ὧν καὶ αὐτὸς εἰς τὸ προκινδυνεύειν ἐκληρώσατο."},{"number":259,"text":"ἐκέλευσέν τε πρὸς μὲν τὸν ἀλαλαγμὸν τῶν ταγμάτων ἀποφράξαι τὰς ἀκοάς, ὡς ἂν μὴ καταπλαγεῖεν, πρὸς δὲ τὸ πλῆθος τῶν βελῶν συνοκλάσαντας καλύψασθαι καθύπερθεν τοῖς θυρεοῖς ὑποχωρῆσαί τε πρὸς ὀλίγον, ἕως τὰς φαρέτρας κενώσωσιν οἱ τοξόται."},{"number":260,"text":"βαλλόντων δὲ τὰς ἐπιβατηρίους μηχανὰς αὐτοὺς προπηδᾶν καὶ διὰ τῶν ἰδίων ὀργάνων ἀπαντᾶν τοῖς πολεμίοις, ἀγωνίζεσθαί τε ἕκαστον οὐχ ὡς ὑπὲρ σωθησομένης, ἀλλʼ ὡς ὑπὲρ ἀπολωλυίας ἤδη τῆς πατρίδος ἀμυνόμενον,"},{"number":261,"text":"λαμβάνειν τε πρὸ ὀφθαλμῶν σφαγησομένους γέροντας καὶ τέκνα καὶ γυναῖκας ἀναιρεθησομένας ὑπὸ τῶν ἐχθρῶν ὅσον οὐδέπω, καὶ τὸν ἐπὶ ταῖς μελλούσαις συμφοραῖς θυμὸν προαλίσαντας ἐναφεῖναι τοῖς δράσουσιν αὐτάς."},{"number":262,"text":"Ἔταξεν μὲν οὖν οὕτως ἑκάτερον· τὸ δʼ ἀργὸν ἀπὸ τῆς πόλεως· πλῆθος, γύναια καὶ παῖδες, ὡς ἐθεάσαντο τριπλῇ μὲν φάλαγγι τὴν πόλιν ἐζωσμένην, οὐδὲν γὰρ εἰς τὴν μάχην μετακεκίνητο τῶν πάλαι φυλακῶν, πρὸς δὲ τοῖς βεβλημένοις τείχεσιν τοὺς πολεμίους ξιφήρεις καὶ τὴν καθύπερθεν ὀρεινὴν λαμπομένην ὅπλοις, τά τε βέλη τοῖς τοξόταις ἐπανέχοντα τῶν Ἀράβων, ὕστατόν τινα κωκυτὸν ἁλώσεως συνήχησαν ὡς οὐκ ἀπειλουμένων ἔτι τῶν κακῶν ἀλλʼ ἤδη παρόντων."},{"number":263,"text":"ὁ δὲ Ἰώσηπος τὰς μὲν γυναῖκας, ὡς μὴ θηλύνοιεν οἴκτῳ τὰς ὁρμὰς τῶν σφετέρων, κατακλείει ταῖς οἰκίαις μετʼ ἀπειλῆς ἡσυχάζειν κελεύσας· αὐτὸς δὲ ἐπὶ τῶν ἐρειφθέντων ᾗ ἔλαχεν παρῄει."},{"number":264,"text":"τοῖς μὲν οὖν καθʼ ἕτερα προσφέρουσι τὰς κλίμακας οὐ προσεῖχεν, ἀπεκαραδόκει δὲ τὴν ὁρμὴν τῶν βελῶν."},{"number":265,"text":"Ὁμοῦ δʼ οἵ τε σαλπικταὶ τῶν ταγμάτων ἁπάντων συνήχησαν καὶ δεινὸν ἐπηλάλαξεν ἡ στρατιά, καὶ πάντοθεν ἀφιεμένων ἀπὸ συνθήματος τῶν βελῶν τὸ φῶς ὑπετέμνετο."},{"number":266,"text":"μεμνημένοι γε μὴν τῶν τοῦ Ἰωσήπου προσταγμάτων οἱ σὺν αὐτῷ τάς τε ἀκοὰς πρὸς τὴν βοὴν καὶ τὰ σώματα πρὸς τὰς ἀφέσεις ἐφράξαντο,"},{"number":267,"text":"καὶ βαλλόντων τὰς μηχανὰς ἐπεξέδραμον διʼ αὐτῶν πρὶν ἐπιβῆναι τοὺς βαλόντας,"},{"number":268,"text":"συμπλεκόμενοί τε τοῖς ἀνιοῦσιν παντοῖα καὶ χειρῶν ἔργα καὶ ψυχῆς ἐναπεδείκνυντο, πειρώμενοι παρὰ τὰς ἐσχάτας συμφορὰς μὴ χείρους φαίνεσθαι τῶν ἐν ἀκινδύνῳ τῷ κατὰ σφᾶς ἀνδριζομένων·"},{"number":269,"text":"ὥστε οὐ πρότερον ἀπερρήγνυντο τῶν Ῥωμαίων πρὶν ἢ πεσεῖν ἢ διαφθεῖραι."},{"number":270,"text":"ὡς δʼ οἱ μὲν ἔκαμνον διηνεκῶς ἀμυνόμενοι καὶ τοὺς προμάχους ἀμείβειν οὐκ ἔχοντες, τὸ κεκμηκὸς δὲ τῶν Ῥωμαίων ἀκραιφνεῖς διεδέχοντο καὶ ταχέως ἀντὶ τῶν ἀποβιασθέντων ἐπέβαινον ἕτεροι, παρακελευσάμενοί τε ἀλλήλοις καὶ πλευρὰν μὲν ἑνώσαντες, τοῖς δὲ θυρεοῖς καθύπερθεν φραξάμενοι στῖφος ἄρρηκτον ἐγένοντο καὶ καθάπερ ἑνὶ σώματι πάσῃ τῇ φάλαγγι τοὺς Ἰουδαίους ἀνωθοῦντες ἤδη τοῦ τείχους ἐπέβαινον."},{"number":271,"text":"Ὁ δὲ Ἰώσηπος ἐν ταῖς ἀμηχανίαις σύμβουλον λαβὼν τὴν ἀνάγκην, ἡ δέ ἐστιν δεινὴ πρὸς ἐπίνοιαν, ὅταν αὐτὴν ἀπόγνωσις ἐρεθίζῃ, ζέον ἔλαιον ἐκέλευσεν καταχέειν τῶν συνησπικότων."},{"number":272,"text":"οἱ δʼ ὡς παρεσκευασμένον ἔχοντες μετὰ τάχους πολλοὶ καὶ πολὺ πάντοθεν τῶν Ῥωμαίων κατέχεον συνεπαφιέντες καὶ τὰ ἀγγεῖα βρασσόμενα τῇ θέρμῃ."},{"number":273,"text":"τοῦτο καιομένων τῶν Ῥωμαίων διεσκέδασεν τὴν τάξιν, καὶ μετὰ δεινῶν ἀλγηδόνων ἀπεκυλινδοῦντο τοῦ τείχους·"},{"number":274,"text":"ῥᾷστα μὲν γὰρ τὸ ἔλαιον ἀπὸ κορυφῆς μέχρι ποδῶν ὑπὸ τὰς πανοπλίας διέρρει τοῦ σώματος ὅλου καὶ τὴν σάρκα φλογὸς οὐδὲν ἔλασσον ἐπεβόσκετο, θερμαινόμενόν τε φύσει ταχέως καὶ ψυχόμενον βραδέως διὰ τὴν πιότητα."},{"number":275,"text":"τοῖς δὲ θώραξιν καὶ τοῖς κράνεσιν ἐνδεδεμένων ἀπαλλαγὴ τῆς καύσεως οὐκ ἦν, πηδῶντες δὲ καὶ συνειλούμενοι ταῖς ἀλγηδόσιν ἀπὸ τῶν γεφυρωμάτων ἔπιπτον· οἱ δὲ τραπέντες εἰς τοὺς σφετέρους πρόσω βιαζομένους εὐχείρωτοι τοῖς κατόπιν τιτρώσκουσιν ἦσαν."},{"number":276,"text":"Ἐπέλιπεν δὲ οὔτε Ῥωμαίους ἐν ταῖς κακοπραγίαις ἰσχὺς οὔτε τοὺς Ἰουδαίους σύνεσις, ἀλλʼ οἱ μὲν καίπερ οἰκτρὰ πάσχοντας ὁρῶντες τοὺς καταχυθέντας ὅμως εἰς τοὺς καταχέοντας ἐφέροντο τὸν πρὸ αὐτοῦ κακίζων ἕκαστος ὡς ἐμπόδιον ὄντα τῆς ῥώμης·"},{"number":277,"text":"οἱ δὲ Ἰουδαῖοι δόλῳ δευτέρῳ τὰς προσβάσεις αὐτῶν ἐπέσφαλλον τῆλιν ἑφθὴν ὑποχέοντες ταῖς σανίσιν, ἧς ἐπολισθάνοντες ὑπεσύροντο;"},{"number":278,"text":"καὶ οὔτε τῶν τρεπομένων οὔτε τῶν προσβαινόντων τις ὀρθὸς ἔμενεν, ἀλλʼ οἱ μὲν ἐπʼ αὐτῶν ὑπτιαζόμενοι τῶν ἐπιβατηρίων μηχανῶν συνεπατοῦντο, πολλοὶ δὲ ἐπὶ τὸ χῶμα κατέπιπτον."},{"number":279,"text":"ἐπαίοντο δʼ ὑπὸ τῶν Ἰουδαίων οἱ πεσόντες· ἐσφαλμένων γὰρ τῶν Ῥωμαίων οὗτοι τῆς κατὰ χεῖρα συμπλοκῆς ἐλευθερωθέντες εἰς τὰς βολὰς εὐσχόλουν."},{"number":280,"text":"πολλὰ δὲ κακουμένους ἐν τῇ προσβολῇ τοὺς στρατιώτας ὁ στρατηγὸς περὶ δείλην ἀνεκάλει."},{"number":281,"text":"ἔπεσον δὲ τούτων μὲν οὐκ ὀλίγοι καὶ πλείους ἐτρώθησαν, τῶν δʼ ἀπὸ τῆς Ἰωταπάτης ἀπέθανον μὲν ἓξ ἄνδρες, τραυματίαι δʼ ὑπὲρ τριακοσίους ἀνεκομίσθησαν."},{"number":282,"text":"εἰκάδι μὲν Δαισίου μηνὸς ἡ παράταξις ἦν."},{"number":283,"text":"Οὐεσπασιανὸς δὲ ἐπὶ τοῖς συμβεβηκόσι τὴν στρατιὰν παραμυθούμενος, ὡς θυμουμένους ἑώρα καὶ οὐ προτροπῆς ἀλλʼ ἔργων δεομένους,"},{"number":284,"text":"προσυψῶσαι μὲν τὰ χώματα, πύργους δὲ τρεῖς πεντήκοντα ποδῶν τὸ ὕψος ἕκαστον κατασκευάσαι κελεύσας πάντοθεν σιδήρῳ κεκαλυμμένους, ὡς ἑδραῖοί τε εἶεν ὑπὸ βρίθους καὶ δυσάλωτοι πυρί,"},{"number":285,"text":"τῶν χωμάτων ἐπέστησεν, συνεπιβήσας αὐτοῖς ἀκοντιστάς τε καὶ τοξότας καὶ τῶν ἀφετηρίων ὀργάνων τὰ κουφότερα, πρὸς δὲ τοὺς ῥωμαλεωτάτους σφενδονήτας·"},{"number":286,"text":"οἳ μὴ καθορώμενοι διὰ τὸ ὕψος καὶ τὰ θωράκια τῶν πύργων εἰς καθορωμένους τοὺς ἐπὶ τοῦ τείχους ἔβαλλον."},{"number":287,"text":"οἱ δὲ μήτε κατὰ κόρσης φερομένων τῶν βελῶν ἐκκλίνειν ῥᾳδίως δυνάμενοι μήτε τοὺς ἀφανεῖς ἀμύνεσθαι, καὶ τὸ μὲν ὕψος τῶν πύργων δυσέφικτον ὁρῶντες ἐκ χειρὸς βέλει, πυρὶ δὲ τὸν περὶ αὐτοῖς σίδηρον ἀνάλωτον, ἔφευγον ἀπὸ τοῦ τείχους καὶ προσβάλλειν πειρωμένοις ἐπεξέθεον."},{"number":288,"text":"καὶ οἱ μὲν ἐπὶ τῆς Ἰωταπάτης ἀντεῖχον οὕτως, ἀναιρούμενοί τε καθʼ ἡμέραν πολλοὶ καὶ μηδὲν ἀντικακοῦν τοὺς πολεμίους, ὅτι μὴ μετὰ κινδύνων ἀνείργειν ἔχοντες."},{"number":289,"text":"Κατὰ δὲ τὰς αὐτὰς ἡμέρας Οὐεσπασιανὸς ἐπί τινα τῶν τῆς Ἰωταπάτης ἀστυγειτόνων πόλιν, Ἴαφα καλεῖται, νεωτερίζουσαν καὶ τῶν Ἰωταπατηνῶν παρὰ δόξαν ἀντεχόντων ἐπαιρομένην, Τραϊανὸν ὄντα τοῦ δεκάτου τάγματος ἡγεμόνα ἐκπέμπει παραδοὺς αὐτῷ χιλίους μὲν ἱππεῖς πεζοὺς δὲ δισχιλίους."},{"number":290,"text":"ὁ δὲ τὴν μὲν πόλιν δυσάλωτον καταλαβών, πρὸς γὰρ τῷ φύσει καρτερὰ τυγχάνειν οὖσα καὶ διπλῷ περιβόλῳ τετείχιστο, προαπηντηκότας δὲ τοὺς ἐξ αὐτῆς ἑτοίμους εἰς μάχην ἰδὼν συμβάλλει καὶ πρὸς ὀλίγον ἀντισχόντας ἐδίωκεν."},{"number":291,"text":"συμφυγόντων δὲ εἰς τὸ πρῶτον τεῖχος οἱ Ῥωμαῖοι κατὰ πόδας προσκείμενοι συνεισέπεσον."},{"number":292,"text":"ὁρμήσαντας δὲ πάλιν εἰς τὸ δεύτερον τεῖχος ἀποκλείουσιν τῆς πόλεως οἱ σφέτεροι δείσαντες μὴ συνεισβάλωσιν οἱ πολέμιοι."},{"number":293,"text":"θεὸς δʼ ἦν ἄρα ὁ Ῥωμαίοις τὰ Γαλιλαίων πάθη χαριζόμενος, ὃς καὶ τότε τὸν τῆς πόλεως λαὸν αὔτανδρον χερσὶν οἰκείαις ἐκκλεισθέντα πρὸς ἀπώλειαν ἔκδοτον φονῶσιν ἐχθροῖς παρέστησεν."},{"number":294,"text":"ἐμπίπτοντες γὰρ ἀθρόοι ταῖς πύλαις καὶ πολλὰ τοὺς ἐπʼ αὐτῶν ὀνομαστὶ καλοῦντες ἐν μέσαις ἀπεσφάττοντο ταῖς ἱκεσίαις."},{"number":295,"text":"καὶ τὸ μὲν πρῶτον αὐτοῖς τεῖχος οἱ πολέμιοι, τὸ δεύτερον δʼ ἔκλεισαν οἱ σφέτεροι,"},{"number":296,"text":"μέσοι δὲ τοῖν δυοῖν κατειλούμενοι περιβόλων βύζην, πολλοὶ μὲν τοῖς ἀλλήλων, πολλοὶ δὲ τοῖς ἰδίοις περιεπείροντο ξίφεσιν, ἄπειροι δὲ ὑπὸ Ῥωμαίων ἔπιπτον οὐδὲ ὅσον εἰς ἄμυναν ἀναθαρροῦντες· πρὸς γὰρ τῷ καταπεπλῆχθαι τοὺς πολεμίους τὰς ψυχὰς αὐτῶν ἔκλασεν ἡ τῶν οἰκείων προδοσία."},{"number":297,"text":"πέρας ἔθνησκον οὐ Ῥωμαίοις ἀλλὰ τοῖς ἰδίοις καταρώμενοι, μέχρι πάντες ἀπώλοντο μύριοι καὶ δισχίλιοι τὸν ἀριθμὸν ὄντες."},{"number":298,"text":"κενὴν δὲ μαχίμων λογιζόμενος εἶναι τὴν πόλιν ὁ Τραϊανός, εἰ δὲ καί τινες ἔνδον εἶεν, οἰόμενος μηδὲν αὐτοὺς τολμήσειν ὑπὸ δέους, ἀνετίθει τῷ στρατηγῷ τὴν ἅλωσιν, καὶ στείλας ἀγγέλους πρὸς Οὐεσπασιανὸν ᾐτεῖτο πέμψαι τὸν υἱὸν αὐτῷ Τίτον ἐπιθήσοντα τῇ νίκῃ τέλος."},{"number":299,"text":"ὁ δὲ συμβαλὼν ὑπολείπεσθαί τινα πόνον μετὰ στρατιᾶς τὸν υἱὸν ἐπιπέμπει πεντακοσίων μὲν ἱππέων χιλίων δὲ πεζῶν."},{"number":300,"text":"ὁ δὲ πρὸς τὴν πόλιν ἐλθὼν διὰ τάχους καὶ διατάξας τὴν στρατιὰν ἐπὶ μὲν τοῦ λαιοῦ κέρως τὸν Τραϊανὸν ἵστησιν, αὐτὸς δὲ τὸ δεξιὸν ἔχων ἐξηγεῖτο πρὸς τὴν πολιορκίαν."},{"number":301,"text":"τῶν δὲ στρατιωτῶν κλίμακας πάντοθεν τῷ τείχει προσφερόντων πρὸς ὀλίγον οἱ Γαλιλαῖοι καθύπερθεν ἀμυνόμενοι λείπουσιν τὸν περίβολον,"},{"number":302,"text":"ἐπιπηδήσαντες δὲ οἱ περὶ τὸν Τίτον τῆς μὲν πόλεως ἐκράτησαν ταχέως, πρὸς δὲ τοὺς ἔνδον αὐτοῖς συστραφέντας καρτερὰ μάχη συρρήγνυται·"},{"number":303,"text":"καὶ γὰρ ἐν τοῖς στενωποῖς οἱ δυνατοὶ προσέπιπτον καὶ ἀπὸ τῶν οἰκιῶν αἱ γυναῖκες ἔβαλλον πᾶν τὸ προστυχὸν αὐταῖς."},{"number":304,"text":"καὶ μέχρι μὲν ἓξ ὡρῶν ἀντεῖχον μαχόμενοι, δαπανηθέντων δὲ τῶν μαχίμων τὸ λοιπὸν πλῆθος ἔν τε τοῖς ὑπαίθροις καὶ κατὰ τὰς οἰκίας ἀπεσφάττοντο νέοι τε ὁμοῦ καὶ γέροντες· οὐδὲν γὰρ ἄρρεν ὑπελείφθη δίχα νηπίων, ἃ μετὰ γυναικῶν ἐξηνδραποδίσαντο."},{"number":305,"text":"τῶν μὲν οὖν ἀναιρεθέντων ἀνά τε τὴν πόλιν κἀπὶ τῆς προτέρας παρατάξεως ἀριθμὸς μύριοι πρὸς τοῖς πεντακισχιλίοις ἦν, τὰ δʼ αἰχμάλωτα δισχίλια ἑκατὸν καὶ τριάκοντα."},{"number":306,"text":"τοῦτο συνέβη τὸ πάθος Γαλιλαίοις πέμπτῃ καὶ εἰκάδι Δαισίου μηνός."},{"number":307,"text":"Ἔμειναν δὲ οὐδὲ Σαμαρεῖς ἀπείρατοι συμφορῶν· ἀθροισθέντες γὰρ ἐπὶ τὸ Γαριζεὶν καλούμενον ὄρος, ὅπερ αὐτοῖς ἐστιν ἅγιον, κατὰ χώραν μὲν ἔμενον, πολέμου δʼ εἶχεν ἀπειλὴν ἥ τε σύνοδος αὐτῶν καὶ τὰ φρονήματα."},{"number":308,"text":"καὶ οὐδὲ τοῖς γειτνιῶσι κακοῖς ἐσωφρονίζοντο, πρὸς δὲ τὰς Ῥωμαίων εὐπραγίας ἐν ἀλογίστῳ τὴν κατὰ σφᾶς ἀσθένειαν ᾤδουν καὶ μετέωροι πρὸς ταραχὴν ὑπῆρχον."},{"number":309,"text":"ἐδόκει δὲ Οὐεσπασιανῷ φθάσαι τὸ κίνημα καὶ τὰς ὁρμὰς αὐτῶν ὑποτέμνεσθαι· καὶ γὰρ φρουραῖς ἡ Σαμαρεῖτις ὅλη διείληπτο τό τε πλῆθος τῶν ἐληλυθότων καὶ ἡ σύνταξις ἦν φοβερά."},{"number":310,"text":"Κερεάλιον οὖν ἔπαρχον ὄντα τοῦ πέμπτου τάγματος μετὰ ἑξακοσίων ἱππέων καὶ πεζῶν τρισχιλίων πέμπει."},{"number":311,"text":"τούτῳ προσβαίνειν μὲν τὸ ὄρος καὶ συνάπτειν μάχην οὐκ ἀσφαλὲς ἔδοξεν πολλῶν καθύπερθεν τῶν πολεμίων ὄντων, κυκλωσάμενος δὲ τῇ δυνάμει πᾶσαν τὴν ὑπόρειον διʼ ὅλης αὐτοὺς ἐφρούρει τῆς ἡμέρας."},{"number":312,"text":"συνέβη δὲ ὕδατος ἀπορουμένων τῶν Σαμαρέων ἐκφλεγῆναι τότε καὶ καῦμα δεινόν, ὥρα δʼ ἦν θέρους καὶ τῶν ἐπιτηδείων τὸ πλῆθος ἀπαράσκευον,"},{"number":313,"text":"ὡς τοὺς μὲν αὐθημερὸν ὑπὸ τοῦ δίψους ἀποθανεῖν, πολλοὺς δὲ τῆς τοιαύτης ἀπωλείας τὸ δουλεύειν προαιρουμένους Ῥωμαίοις προσφυγεῖν."},{"number":314,"text":"ἐξ ὧν συνεὶς ὁ Κερεάλιος καὶ τοὺς ἔτι συμμένοντας ὑπὸ τῶν δεινῶν κατεαγότας ἐπαναβαίνει τῷ ὄρει, καὶ τὴν δύναμιν ἐν κύκλῳ περιστήσας τοῖς πολεμίοις τὸ μὲν πρῶτον ἐπὶ δεξιὰς προυκαλεῖτο καὶ σώζεσθαι παρεκάλει διαβεβαιούμενος ἀσφάλειαν τὰ ὅπλα ῥίψασιν·"},{"number":315,"text":"ὡς δʼ οὐκ ἔπειθεν, προσπεσὼν ἀπέκτεινεν πάντας, χιλίους ἑξακοσίους ἐπὶ μυρίοις ὄντας· ἑβδόμῃ καὶ εἰκάδι Δαισίου μηνὸς ἐπράχθη. καὶ τοιαύταις μὲν συμφοραῖς Σαμαρεῖται ἐχρήσαντο."},{"number":316,"text":"Τῶν δʼ ἀνὰ τὰ Ἰωτάπατα καρτερούντων καὶ παρʼ ἐλπίδα τοῖς δεινοῖς ἀντεχόντων τεσσαρακοστῇ μὲν ἡμέρᾳ καὶ ἑβδόμῃ τὰ χώματα τῶν Ῥωμαίων ὑπερήρθη τὸ τεῖχος,"},{"number":317,"text":"αὐτομολεῖ δέ τις πρὸς τὸν Οὐεσπασιανὸν τῆς αὐτῆς ἡμέρας τήν τε ὀλιγότητα τῶν ἐπὶ τῆς πόλεως ἐξαγγέλλων καὶ τὴν ἀσθένειαν,"},{"number":318,"text":"καὶ ὡς ἀγρυπνίᾳ διηνεκεῖ καὶ μάχαις ἐπαλλήλοις δεδαπανημένοι δυνατοὶ μὲν εἶεν οὐδὲ βιαζομένους ἔτι φέρειν, καὶ δόλῳ δʼ ἂν ἁλοῖεν, εἴ τις ἐπιθοῖτο·"},{"number":319,"text":"περὶ γὰρ τὴν ἐσχάτην φυλακήν, καθʼ ἣν ἄνεσίν τε τῶν δεινῶν ἐδόκουν ἔχειν καὶ καθάπτεται μάλιστα κεκοπωμένων ἑωθινὸς ὕπνος, καταδαρθάνειν ἔφασκεν τοὺς φύλακας συνεβούλευέν τε κατὰ ταύτην τὴν ὥραν ἐπελθεῖν."},{"number":320,"text":"τῷ δʼ ἦν μὲν διʼ ὑπονοίας ὁ αὐτόμολος τό τε πρὸς ἀλλήλους πιστὸν εἰδότι τῶν Ἰουδαίων καὶ τὴν πρὸς τὰς κολάσεις ὑπεροψίαν,"},{"number":321,"text":"ἐπειδὴ καὶ πρότερον ληφθείς τις τῶν ἀπὸ τῆς Ἰωταπάτης πρὸς πᾶσαν αἰκίαν βασάνων ἀντέσχεν καὶ μηδὲν διὰ πυρὸς ἐξερευνῶσι τοῖς πολεμίοις περὶ τῶν ἔνδον εἰπὼν ἀνεσταυρώθη τοῦ θανάτου καταμειδιῶν·"},{"number":322,"text":"τά γε μὴν εἰκότα πιστὸν ἐποίει τὸν προδότην, καὶ τάχα μὲν ἀληθεύειν ἐκεῖνον, μηδὲν δʼ αὐτὸς ἐξ ἐνέδρας πείσεσθαι μέγα προσδοκῶν, τὸν μὲν φυλάσσειν ἐκέλευσεν, ἐπὶ δὲ τὴν κατάληψιν τῆς πόλεως παρεσκεύαζε τὴν στρατιάν."},{"number":323,"text":"Κατὰ δὲ τὴν μηνυθεῖσαν ὥραν ᾔεσαν ἡσυχῆ πρὸς τὸ τεῖχος."},{"number":324,"text":"καὶ πρῶτος ἐπιβαίνει Τίτος σὺν ἑνὶ τῶν χιλιάρχων Δομετίῳ Σαβίνῳ τῶν ἀπὸ τοῦ πέμπτου καὶ δεκάτου τάγματος ὀλίγους ἄγων·"},{"number":325,"text":"ἀποσφάξαντες δὲ τοὺς φύλακας εἰσίασιν εἰς τὴν πόλιν, μεθʼ οὓς Σέκστος τις Καλουάριος χιλίαρχος καὶ Πλάκιδος τοὺς ὑπὸ σφίσι τεταγμένους εἰσῆγον."},{"number":326,"text":"κατειλημμένης δὲ τῆς ἄκρας καὶ τῶν πολεμίων ἐν μέσῳ στρεφομένων, ἤδη δὲ καὶ ἡμέρας οὔσης, ὅμως οὔπω τῆς ἁλώσεως τοῖς κρατουμένοις αἴσθησις ἦν·"},{"number":327,"text":"καμάτῳ τε γὰρ οἱ πολλοὶ καὶ ὕπνῳ διαλέλυντο, καὶ τῶν διανισταμένων ὁμίχλη τὰς ὄψεις ἀπήμβλυνεν πολλὴ κατὰ τύχην τότε τῇ πόλει περιχυθεῖσα,"},{"number":328,"text":"μέχρι πάσης τῆς στρατιᾶς εἰσπεσούσης πρὸς μόνην τὴν τῶν κακῶν αἴσθησιν ἐξανέστησαν καὶ τὴν ἅλωσιν ἐπίστευον ἀναιρούμενοι."},{"number":329,"text":"Ῥωμαίους δὲ κατὰ μνήμην ὧν ἐκ τῆς πολιορκίας ἔπαθον οὔτε φειδὼ εἰσῄει τινὸς οὔτʼ ἔλεος, ἀλλʼ εἰς τὸ κάταντες ἀπὸ τῆς ἄκρας τὸν λεὼ συνωθοῦντες ἐφόνευον."},{"number":330,"text":"ἔνθα καὶ τοὺς ἔτι μάχεσθαι δυναμένους ἡ δυσχωρία τὴν ἄμυναν ἀφείλετο· θλιβόμενοι γὰρ ἐν τοῖς στενωποῖς καὶ κατὰ τοῦ πρανοῦς ὑπολισθάνοντες ῥέοντι κατʼ ἄκρας ἐκαλύπτοντο τῷ πολέμῳ."},{"number":331,"text":"τοῦτο πολλοὺς καὶ τῶν περὶ τὸν Ἰώσηπον ἐπιλέκτων ἐπʼ αὐτοχειρίαν παρώξυνεν· κατιδόντες γάρ, ὡς οὐδένα τῶν Ῥωμαίων ἀνελεῖν δύνανται, τό γε πεσεῖν αὐτοὺς ὑπὸ Ῥωμαίων προέλαβον καὶ συναθροισθέντες ἐπὶ τὰ καταλήγοντα τῆς πόλεως σφᾶς αὐτοὺς ἀνεῖλον."},{"number":332,"text":"Ὅσοι γε μὴν ὑπὸ πρώτην τῆς καταλήψεως αἴσθησιν τῶν φυλάκων διαφυγεῖν ἔφθασαν ἀναβάντες εἴς τινα τῶν προσαρκτίων πύργων μέχρι μέν τινος ἀπημύναντο, περισχεθέντες δὲ πλήθει τῶν πολεμίων ὀψὲ παρεῖσαν τὰς δεξιὰς καὶ τοῖς ἐφεστῶσιν τὴν σφαγὴν εὔθυμοι παρέσχον."},{"number":333,"text":"ἀναίμακτον δʼ ἂν ἦν αὐχῆσαι Ῥωμαίοις τὸ τέλος τῆς πολιορκίας, εἰ μὴ κατὰ τὴν ἅλωσιν εἷς ἔπεσέν τις· ἑκατοντάρχης ἦν Ἀντώνιος, θνήσκει δʼ ἐξ ἐνέδρας."},{"number":334,"text":"τῶν γὰρ εἰς τὰ σπήλαιά τις συμπεφευγότων, πολλοὶ δʼ οὗτοι πλῆθος ἦσαν, ἱκετεύει τὸν Ἀντώνιον ὀρέξαι δεξιὰν αὐτῷ πίστιν τε σωτηρίας καὶ βοήθειαν πρὸς ἄνοδον·"},{"number":335,"text":"ὁ δʼ ἀφυλάκτως ὤρεγε τὴν χεῖρα, καὶ φθάσας αὐτὸν ἐκεῖνος νύττει κάτωθεν ὑπὸ τὸν βουβῶνα δόρατι καὶ παραχρῆμα διεργάζεται."},{"number":336,"text":"Κατʼ ἐκείνην μὲν οὖν τὴν ἡμέραν τὸ φανερὸν πλῆθος ἀνεῖλον οἱ Ῥωμαῖοι, ταῖς δʼ ἐπιούσαις ἀνερευνώμενοι τὰς καταδύσεις τοὺς ἐν τοῖς ὑπονόμοις καὶ τοῖς σπηλαίοις ἐπεξῄεσαν καὶ διὰ πάσης ἐχώρουν ἡλικίας πλὴν νηπίων καὶ γυναικῶν."},{"number":337,"text":"καὶ τὰ μὲν αἰχμάλωτα χίλια πρὸς τοῖς διακοσίοις συνήχθη, νεκροὶ δὲ κατὰ τὴν ἅλωσιν καὶ τὰς πρότερον μάχας συνηριθμήθησαν τετρακισμύριοι."},{"number":338,"text":"Οὐεσπασιανὸς δὲ τήν τε πόλιν κατασκάψαι κελεύει καὶ τὰ φρούρια πάντα προσεμπίπρησιν αὐτῆς."},{"number":339,"text":"Ἰωτάπατα μὲν οὖν οὕτως ἑάλω τρεισκαιδεκάτῳ τῆς Νέρωνος ἡγεμονίας ἔτει Πανέμου νουμηνίᾳ."}],"8":[{"number":340,"text":"Ῥωμαῖοι δὲ τὸν Ἰώσηπον ἀναζητοῦντες κατά τε ὀργὴν σφετέραν καὶ σφόδρα τοῦ στρατηγοῦ φιλοτιμουμένου, μεγίστη γὰρ ἦν μοῖρα τοῦ πολέμου ληφθείς, τούς τε νεκροὺς διηρεύνων καὶ τοὺς ἀποκρύφους."},{"number":341,"text":"ὁ δὲ τῆς πόλεως ἁλισκομένης δαιμονίῳ τινὶ συνεργίᾳ χρησάμενος μέσον μὲν ἑαυτὸν ἐκκλέπτει τῶν πολεμίων, καθάλλεται δὲ εἴς τινα βαθὺν λάκκον, ᾧ πλατὺ σπήλαιον διέζευκτο κατὰ πλευρὰν τοῖς ἄνωθεν ἀόρατον."},{"number":342,"text":"ἔνθα τεσσαράκοντα μὲν τῶν ἐπισήμων ἄνδρας καταλαμβάνει λανθάνοντας, παρασκευὴν δʼ ἐπιτηδείων οὐκ ὀλίγαις ἡμέραις διαρκεῖν δυναμένην."},{"number":343,"text":"μεθʼ ἡμέραν μὲν οὖν ὑπεστέλλετο τῶν πολεμίων πάντα διειληφότων, νυκτὸς δʼ ἀνιὼν ἐζήτει δρασμοῦ διάδυσιν καὶ τὰς φυλακὰς κατεσκέπτετο. φρουρουμένων δὲ πανταχόθεν πάντων διʼ αὐτὸν ὡς λαθεῖν οὐκ ἦν, αὖθις εἰς τὸ σπήλαιον κατῄει."},{"number":344,"text":"δύο μὲν οὖν ἡμέραις διαλανθάνει, τῇ δὲ τρίτῃ γυναικὸς ἁλούσης τῶν ἅμα αὐτοῖς μηνύεται, καὶ Οὐεσπασιανὸς αὐτίκα μετὰ σπουδῆς πέμπει δύο χιλιάρχους Παυλῖνον καὶ Γαλλικανόν, δεξιάς τε τῷ Ἰωσήπῳ δοῦναι κελεύσας καὶ προτρεψομένους ἀνελθεῖν."},{"number":345,"text":"Ἀφικόμενοι γοῦν παρεκάλουν οὗτοι τὸν ἄνδρα καὶ πίστεις περὶ σωτηρίας ἐδίδοσαν, οὐ μὴν ἔπειθον·"},{"number":346,"text":"ἐκ γὰρ ὧν εἰκὸς ἦν τοσαῦτα δράσαντα παθεῖν, οὐκ ἐκ τοῦ φύσει τῶν παρακαλούντων ἡμέρου τὰς ὑποψίας συνέλεγεν ἐδεδίει τε ὡς ἐπὶ τιμωρίαν προκαλουμένους, ἕως Οὐεσπασιανὸς τρίτον ἐπιπέμπει χιλίαρχον Νικάνορα γνώριμον τῷ Ἰωσήπῳ καὶ συνήθη πάλαι."},{"number":347,"text":"παρελθὼν δʼ οὗτος τό τε φύσει Ῥωμαίων χρηστὸν πρὸς οὓς ἂν ἅπαξ ἕλωσι διεξῄει, καὶ ὡς διʼ ἀρετὴν αὐτὸς θαυμάζοιτο μᾶλλον ἢ μισοῖτο πρὸς τῶν ἡγεμόνων,"},{"number":348,"text":"σπουδάζειν τε τὸν στρατηγὸν οὐκ ἐπὶ τιμωρίαν ἀναγαγεῖν αὐτόν, εἶναι γὰρ ταύτην καὶ παρὰ μὴ προϊόντος λαβεῖν, ἀλλὰ σῶσαι προαιρούμενον ἄνδρα γενναῖον."},{"number":349,"text":"προσετίθει δʼ ὡς οὔτʼ ἂν Οὐεσπασιανὸς ἐνεδρεύων φίλον ἔπεμπεν, ἵνα τοῦ κακίστου πράγματος προστήσηται τὸ κάλλιστον, ἀπιστίας φιλίαν, οὐδʼ ἂν αὐτὸς ἀπατήσων ἄνδρα φίλον ὑπήκουσεν ἐλθεῖν."},{"number":350,"text":"Ἐνδοιάζοντος δὲ τοῦ Ἰωσήπου καὶ πρὸς τὸν Νικάνορα τὸ μὲν στρατιωτικὸν ὑπʼ ὀργῆς ἐκκαίειν τὸ σπήλαιον ὥρμητο, κατεῖχεν δʼ αὐτοὺς ὁ πολέμαρχος ζωγρῆσαι τὸν ἄνδρα φιλοτιμούμενος."},{"number":351,"text":"ὡς δʼ ὅ τε Νικάνωρ προσέκειτο λιπαρῶν καὶ τὰς ἀπειλὰς τοῦ πολεμίου πλήθους ὁ Ἰώσηπος ἔμαθεν, ἀνάμνησις αὐτὸν τῶν διὰ νυκτὸς ὀνείρων εἰσέρχεται, διʼ ὧν ὁ θεὸς τάς τε μελλούσας αὐτῷ συμφορὰς προεσήμαινεν Ἰουδαίων καὶ τὰ περὶ τοὺς Ῥωμαίων βασιλεῖς ἐσόμενα."},{"number":352,"text":"ἦν δὲ καὶ περὶ κρίσεις ὀνείρων ἱκανὸς συμβαλεῖν τὰ ἀμφιβόλως ὑπὸ τοῦ θείου λεγόμενα, τῶν γε μὴν ἱερῶν βίβλων οὐκ ἠγνόει τὰς προφητείας ὡς ἂν αὐτός τε ὢν ἱερεὺς καὶ ἱερέων ἔγγονος·"},{"number":353,"text":"ὧν ἐπὶ τῆς τότε ὥρας ἔνθους γενόμενος καὶ τὰ φρικώδη τῶν προσφάτων ὀνείρων σπάσας φαντάσματα προσφέρει τῷ θεῷ λεληθυῖαν εὐχήν,"},{"number":354,"text":"κἀπειδὴ τὸ Ἰουδαίων, ἔφη, φῦλον ὀκλάσαι δοκεῖ σοι τῷ κτίσαντι, μετέβη δὲ πρὸς Ῥωμαίους ἡ τύχη πᾶσα, καὶ τὴν ἐμὴν ψυχὴν ἐπελέξω τὰ μέλλοντα εἰπεῖν, δίδωμι μὲν Ῥωμαίοις τὰς χεῖρας ἑκὼν καὶ ζῶ, μαρτύρομαι δὲ ὡς οὐ προδότης, ἀλλὰ σὸς εἶμι διάκονος."},{"number":355,"text":"Ταῦτʼ εἰπὼν ἐνεδίδου τῷ Νικάνορι. καὶ τῶν Ἰουδαίων οἱ συγκαταφυγόντες ὡς τὸν Ἰώσηπον συνίεσαν εἴκοντα τοῖς παρακαλοῦσιν,"},{"number":356,"text":"ἀθρόοι περιστάντες, ἦ μεγάλα γʼ ἂν στενάξειαν, ἐβόων, οἱ πάτριοι νόμοι, οὓς κατέφησεν θεὸς Ἰουδαίοις ὁ κτίσας ψυχὰς θανάτου καταφρονούσας."},{"number":357,"text":"φιλοζωεῖς, ὦ Ἰώσηπε, καὶ φῶς ὑπομένεις ὁρᾶν δοῦλον; ὡς ταχέως ἐπελάθου σαυτοῦ. πόσους ὑπὲρ ἐλευθερίας ἀποθνήσκειν ἔπεισας."},{"number":358,"text":"ψευδῆ μὲν ἄρα δόξαν ἀνδρείας, ψευδῆ δὲ καὶ συνέσεως εἶχες, εἴ γε σωτηρίαν μὲν ἔχειν ἐλπίζεις παρʼ οἷς οὕτως ἐπολέμησας, σώζεσθαι δὲ ὑπʼ ἐκείνων, κἂν ᾖ βέβαιον, θέλεις."},{"number":359,"text":"ἀλλʼ εἰ καὶ σοὶ λήθην σεαυτοῦ κατέχεεν ἡ Ῥωμαίων τύχη, προνοητέον ἡμῖν τοῦ πατρίου κλέους. χρήσομέν σοι δεξιὰν καὶ ξίφος· σὺ δʼ ἂν μὲν ἑκὼν θνήσκῃς, Ἰουδαίων στρατηγός, ἂν δʼ ἄκων, προδότης τεθνήξῃ."},{"number":360,"text":"ταῦθʼ ἅμα λέγοντες ἐπανετείναντο τὰ ξίφη καὶ διηπείλουν ἀναιρήσειν αὐτόν, εἰ τοῖς Ῥωμαίοις ἐνδιδοίη."},{"number":361,"text":"Δείσας δὲ τὴν ἔφοδον ὁ Ἰώσηπος καὶ προδοσίαν ἡγούμενος εἶναι τῶν τοῦ θεοῦ προσταγμάτων, εἰ προαποθάνοι τῆς διαγγελίας, ἤρχετο πρὸς αὐτοὺς φιλοσοφεῖν ἐπὶ τῆς ἀνάγκης·"},{"number":362,"text":"τί γὰρ τοσοῦτον, ἔφη, σφῶν αὐτῶν, ἑταῖροι, φονῶμεν; ἢ τί τὰ φίλτατα διαστασιάζομεν, σῶμα καὶ ψυχήν; ἠλλάχθαι τις ἐμέ φησιν."},{"number":363,"text":"ἀλλʼ οἴδασιν Ῥωμαῖοι τοῦτό γε. καλὸν ἐν πολέμῳ θνήσκειν, ἀλλὰ πολέμου νόμῳ, τουτέστιν ὑπὸ τῶν κρατούντων."},{"number":364,"text":"εἰ μὲν οὖν τὸν Ῥωμαίων ἀποστρέφομαι σίδηρον, ἄξιος ἀληθῶς εἰμι τοὐμοῦ ξίφους καὶ χειρὸς τῆς ἐμῆς· εἰ δʼ ἐκείνους εἰσέρχεται φειδὼ πολεμίου, πόσῳ δικαιότερον ἂν ἡμᾶς ἡμῶν αὐτῶν εἰσέλθοι; καὶ γὰρ ἠλίθιον ταῦτα δρᾶν σφᾶς αὐτούς, περὶ ὧν πρὸς ἐκείνους διιστάμεθα."},{"number":365,"text":"καλὸν γὰρ ὑπὲρ τῆς ἐλευθερίας ἀποθνήσκειν· φημὶ κἀγώ, μαχομένους μέντοι, καὶ ὑπὸ τῶν ἀφαιρουμένων αὐτήν. νῦν δʼ οὔτʼ εἰς μάχην ἀντιάζουσιν ἡμῖν οὔτʼ ἀναιροῦσιν ἡμᾶς· δειλὸς δὲ ὁμοίως ὅ τε μὴ βουλόμενος θνήσκειν ὅταν δέῃ καὶ ὁ βουλόμενος, ὅταν μὴ δέῃ."},{"number":366,"text":"τί δὲ καὶ δεδοικότες πρὸς Ῥωμαίους οὐκ ἄνιμεν;"},{"number":367,"text":"ἆρʼ οὐχὶ θάνατον; εἶθʼ ὃν δεδοίκαμεν ἐκ τῶν ἐχθρῶν ὑποπτευόμενον ἑαυτοῖς βέβαιον ἐπιστήσομεν; ἀλλὰ δουλείαν, ἐρεῖ τις. πάνυ γοῦν νῦν ἐσμὲν ἐλεύθεροι."},{"number":368,"text":"γενναῖον γὰρ ἀνελεῖν ἑαυτόν, φήσει τις. οὐ μὲν οὖν, ἀλλʼ ἀγενέστατον, ὡς ἔγωγε καὶ κυβερνήτην ἡγοῦμαι δειλότατον, ὅστις χειμῶνα δεδοικὼς πρὸ τῆς θυέλλης ἐβάπτισεν ἑκὼν τὸ σκάφος."},{"number":369,"text":"ἀλλὰ μὴν ἡ αὐτοχειρία καὶ τῆς κοινῆς ἁπάντων ζῴων φύσεως ἀλλότριον καὶ πρὸς τὸν κτίσαντα θεὸν ἡμᾶς ἐστιν ἀσέβεια."},{"number":370,"text":"τῶν μέν γε ζῴων οὐδέν ἐστιν ὃ θνήσκει μετὰ προνοίας ἢ διʼ αὐτοῦ· φύσεως γὰρ νόμος ἰσχυρὸς ἐν ἅπασιν τὸ ζῆν ἐθέλειν· διὰ τοῦτο καὶ τοὺς φανερῶς ἀφαιρουμένους ἡμᾶς τούτου πολεμίους ἡγούμεθα καὶ τοὺς ἐξ ἐνέδρας τιμωρούμεθα."},{"number":371,"text":"τὸν δὲ θεὸν οὐκ οἴεσθε ἀγανακτεῖν, ὅταν ἄνθρωπος αὐτοῦ τὸ δῶρον ὑβρίζῃ; καὶ γὰρ εἰλήφαμεν παρʼ ἐκείνου τὸ εἶναι καὶ τὸ μηκέτι εἶναι πάλιν ἐκείνῳ δίδομεν."},{"number":372,"text":"τὰ μέν γε σώματα θνητὰ πᾶσιν καὶ ἐκ φθαρτῆς ὕλης δεδημιούργηται, ψυχὴ δὲ ἀθάνατος ἀεὶ καὶ θεοῦ μοῖρα τοῖς σώμασιν ἐνοικίζεται· εἶτʼ ἐὰν μὲν ἀφανίσῃ τις ἀνθρώπου παρακαταθήκην ἢ διαθῆται κακῶς, πονηρὸς εἶναι δοκεῖ καὶ ἄπιστος, εἰ δέ τις τοῦ σφετέρου σώματος ἐκβάλλει τὴν παρακαταθήκην τοῦ θεοῦ, λεληθέναι δοκεῖ τὸν ἀδικούμενον;"},{"number":373,"text":"καὶ κολάζειν μὲν τοὺς ἀποδράντας οἰκέτας δίκαιον νενόμισται κἂν πονηροὺς καταλείπωσι δεσπότας, αὐτοὶ δὲ κάλλιστον δεσπότην ἀποδιδράσκοντες τὸν θεὸν οὐ δοκοῦμεν ἀσεβεῖν;"},{"number":374,"text":"ἆρʼ οὐκ ἴστε ὅτι τῶν μὲν ἐξιόντων τοῦ βίου κατὰ τὸν τῆς φύσεως νόμον καὶ τὸ ληφθὲν παρὰ τοῦ θεοῦ χρέος ἐκτινύντων, ὅταν ὁ δοὺς κομίσασθαι θέλῃ, κλέος μὲν αἰώνιον, οἶκοι δὲ καὶ γενεαὶ βέβαιοι, καθαραὶ δὲ καὶ ἐπήκοοι μένουσιν αἱ ψυχαί, χῶρον οὐράνιον λαχοῦσαι τὸν ἁγιώτατον, ἔνθεν ἐκ περιτροπῆς αἰώνων ἁγνοῖς πάλιν ἀντενοικίζονται σώμασιν·"},{"number":375,"text":"ὅσοις δὲ καθʼ ἑαυτῶν ἐμάνησαν αἱ χεῖρες, τούτων ᾅδης μὲν δέχεται τὰς ψυχὰς σκοτεινότερος, ὁ δὲ τούτων πατὴρ θεὸς εἰς ἐγγόνους τιμωρεῖται τοὺς τῶν πατέρων ὑβριστάς."},{"number":376,"text":"διὰ τοῦτο μεμίσηται παρὰ θεῷ τοῦτο καὶ παρὰ τῷ σοφωτάτῳ κολάζεται νομοθέτῃ·"},{"number":377,"text":"τοὺς γοῦν ἀναιροῦντας ἑαυτοὺς παρὰ μὲν ἡμῖν μέχρις ἡλίου δύσεως ἀτάφους ἐκρίπτειν ἔκριναν καίτοι καὶ πολεμίους θάπτειν θεμιτὸν ἡγούμενοι,"},{"number":378,"text":"παρʼ ἑτέροις δὲ καὶ τὰς δεξιὰς τῶν τοιούτων νεκρῶν ἀποκόπτειν ἐκέλευσαν, αἷς ἐστρατεύσαντο καθʼ ἑαυτῶν, ἡγούμενοι καθάπερ τὸ σῶμα τῆς ψυχῆς ἀλλότριον, οὕτως καὶ τὴν χεῖρα τοῦ σώματος."},{"number":379,"text":"καλὸν οὖν, ἑταῖροι, δίκαια φρονεῖν καὶ μὴ ταῖς ἀνθρωπίναις συμφοραῖς προσθεῖναι τὴν εἰς τὸν κτίσαντα ἡμᾶς δυσσέβειαν."},{"number":380,"text":"εἰ σώζεσθαι δοκεῖ, σωζώμεθα· καὶ γὰρ οὐκ ἄδοξος ἡ σωτηρία παρʼ οἷς διὰ τοσούτων ἔργων ἐπεδειξάμεθα τὰς ἀρετάς· εἰ τεθνάναι, καλὸν ὑπὸ τῶν ἑλόντων."},{"number":381,"text":"οὐ μεταβήσομαι δʼ ἐγὼ εἰς τὴν τῶν πολεμίων τάξιν, ἵνʼ ἐμαυτοῦ προδότης γένωμαι· καὶ γὰρ ἂν εἴην πολὺ τῶν αὐτομολούντων πρὸς τοὺς πολεμίους ἠλιθιώτερος, εἴ γʼ ἐκεῖνοι μὲν ἐπὶ σωτηρίᾳ τοῦτο πράττουσιν, ἐγὼ δὲ ἐπὶ ἀπωλείᾳ, καί γε τῇ ἐμαυτοῦ."},{"number":382,"text":"τὴν μέντοι Ῥωμαίων ἐνέδραν εὔχομαι· μετὰ γὰρ δεξιὰν ἀναιρούμενος ὑπʼ αὐτῶν εὔθυμος τεθνήξομαι, τὴν τῶν ψευσαμένων ἀπιστίαν νίκης μείζονα ἀποφέρων παραμυθίαν."},{"number":383,"text":"Ὁ μὲν οὖν Ἰώσηπος πολλὰ τοιαῦτα πρὸς ἀποτροπὴν τῆς αὐτοχειρίας ἔλεγεν·"},{"number":384,"text":"οἱ δὲ πεφραγμένας ἀπογνώσει τὰς ἀκοὰς ἔχοντες ὡς ἂν πάλαι καθοσιώσαντες ἑαυτοὺς τῷ θανάτῳ παρωξύνοντο πρὸς αὐτόν, καὶ προστρέχων ἄλλος ἄλλοθεν ξιφήρεις ἐκάκιζόν τε εἰς ἀνανδρίαν καὶ ὡς ἕκαστος αὐτίκα πλήξων δῆλος ἦν."},{"number":385,"text":"ὁ δὲ τὸν μὲν ὀνομαστὶ καλῶν, τῷ δὲ στρατηγικώτερον ἐμβλέπων, τοῦ δὲ δρασσόμενος τῆς δεξιᾶς, ὃν δὲ δεήσει δυσωπῶν, καὶ ποικίλοις διαιρούμενος πάθεσιν ἐπὶ τῆς ἀνάγκης εἶργεν ἀπὸ τῆς σφαγῆς πάντων τὸν σίδηρον, ὥσπερ τὰ κυκλωθέντα τῶν θηρίων ἀεὶ πρὸς τὸν καθαπτόμενον ἀντιστρεφόμενος."},{"number":386,"text":"τῶν δὲ καὶ παρὰ τὰς ἐσχάτας συμφορὰς ἔτι τὸν στρατηγὸν αἰδουμένων παρελύοντο μὲν αἱ δεξιαί, περιωλίσθανεν δὲ τὰ ξίφη, καὶ πολλοὶ τὰς ῥομφαίας ἐπιφέροντες αὐτομάτως παρεῖσαν."},{"number":387,"text":"Ὁ δʼ ἐν ταῖς ἀμηχανίαις οὐκ ἠπόρησεν ἐπινοίας, ἀλλὰ πιστεύων τῷ κηδεμόνι θεῷ τὴν σωτηρίαν παραβάλλεται,"},{"number":388,"text":"κἀπεὶ δέδοκται τὸ θνήσκειν, ἔφη, φέρε κλήρῳ τὰς ἀλλήλων σφαγὰς ἐπιτρέψωμεν,"},{"number":389,"text":"ὁ λαχὼν δʼ ὑπὸ τοῦ μετʼ αὐτὸν πιπτέτω, καὶ διοδεύσει πάντων οὕτως ἡ τύχη, μηδʼ ἐπὶ τῆς ἰδίας κείσθω δεξιᾶς ἕκαστος· ἄδικον γὰρ οἰχομένων τινὰ τῶν ἄλλων μετανοήσαντα σωθῆναι. πιστὸς ἔδοξεν ταῦτα εἰπὼν καὶ συνεκληροῦτο πείσας."},{"number":390,"text":"ἑτοίμην δʼ ὁ λαχὼν τῷ μεθʼ αὑτὸν παρεῖχεν τὴν σφαγὴν ὡς αὐτίκα τεθνηξομένου καὶ τοῦ στρατηγοῦ· ζωῆς γὰρ ἡδίω τὸν μετὰ [τοῦ] Ἰωσήπου θάνατον ἡγοῦντο."},{"number":391,"text":"καταλείπεται δʼ οὗτος εἴτε ὑπὸ τύχης χρὴ λέγειν, εἴτε ὑπὸ θεοῦ προνοίας σὺν ἑτέρῳ, καὶ σπουδάζων μήθʼ ὑπὸ τοῦ κλήρου καταδικασθῆναι μήτε, εἰ τελευταῖος λείποιτο, μιᾶναι τὴν δεξιὰν ὁμοφύλῳ φόνῳ πείθει κἀκεῖνον ἐπὶ πίστει ζῆν."},{"number":392,"text":"Ὁ μὲν οὖν οὕτως τόν τε Ῥωμαίων καὶ τὸν οἰκείων διαφυγὼν πόλεμον ἐπὶ Οὐεσπασιανὸν ἤγετο ὑπὸ [τοῦ] Νικάνορος."},{"number":393,"text":"οἱ δὲ Ῥωμαῖοι πάντες ἐπὶ θέαν αὐτοῦ συνέτρεχον, καὶ τοῦ πλήθους συνθλιβομένου περὶ τῷ στρατηγῷ θόρυβος ἦν ποικίλος, τῶν μὲν γεγηθότων ἐπὶ τῷ ληφθέντι, τῶν δʼ ἀπειλούντων, τῶν δʼ ἐγγύθεν ἰδεῖν βιαζομένων."},{"number":394,"text":"καὶ οἱ μὲν πόρρωθεν κολάζειν ἐβόων τὸν πολέμιον, τῶν δὲ πλησίον ἀνάμνησις αὐτοῦ τῶν ἔργων εἰσῄει καὶ πρὸς τὴν μεταβολὴν θάμβος,"},{"number":395,"text":"τῶν τε ἡγεμόνων οὐδεὶς ἦν, ὃς εἰ καὶ πρότερον ὠργίζετο, τότε πρὸς τὴν ὄψιν οὐκ ἐνέδωκεν αὐτοῦ."},{"number":396,"text":"μάλιστα δὲ τὸν Τίτον ἐξαιρέτως τό τε καρτερικὸν ἐν ταῖς συμφοραῖς ᾕρει τοῦ Ἰωσήπου καὶ πρὸς τὴν ἡλικίαν ἔλεος, ἀναμιμνησκομένῳ τε τὸν πάλαι μαχόμενον καὶ τὸν ἐν χερσὶν ἐχθρῶν ἄρτι κείμενον ὁρῶντι παρῆν [δὲ] νοεῖν, ὅσον δύναται τύχη, καὶ ὡς ὀξεῖα μὲν πολέμου ῥοπή, τῶν δʼ ἀνθρωπίνων οὐδὲν βέβαιον·"},{"number":397,"text":"παρὸ καὶ τότε συνδιέθηκεν μὲν πλείστους ἑαυτῷ καὶ πρὸς οἶκτον τοῦ Ἰωσήπου, πλείστη δʼ αὐτῷ καὶ παρὰ τῷ πατρὶ μοῖρα σωτηρίας ἐγένετο."},{"number":398,"text":"ὁ μέντοι Οὐεσπασιανὸς φρουρεῖν αὐτὸν μετὰ πάσης ἀσφαλείας προσέταττεν ὡς ἀναπέμψων αὐτίκα Νέρωνι."},{"number":399,"text":"Τοῦτο ἀκούσας ὁ Ἰώσηπος μόνῳ τι διαλεχθῆναι θέλειν ἔλεγεν αὐτῷ. μεταστησαμένου δʼ ἐκείνου πλὴν τοῦ παιδὸς Τίτου καὶ δυοῖν φίλων τοὺς ἄλλους ἅπαντας"},{"number":400,"text":"σὺ μέν, ἔφη, Οὐεσπασιανέ, νομίζεις αἰχμάλωτον αὐτὸ μόνον εἰληφέναι Ἰώσηπον, ἐγὼ δὲ ἄγγελος ἥκω σοι μειζόνων. μὴ γὰρ ὑπὸ θεοῦ προπεμπόμενος ᾔδειν τὸν Ἰουδαίων νόμον, καὶ πῶς στρατηγοῖς ἀποθνήσκειν πρέπει."},{"number":401,"text":"Νέρωνί με πέμπεις· τί γάρ; οἱ μετὰ Νέρωνα μέχρι σοῦ διάδοχοι μενοῦσιν. σὺ Καῖσαρ, Οὐεσπασιανέ, καὶ αὐτοκράτωρ, σὺ καὶ παῖς ὁ σὸς οὗτος."},{"number":402,"text":"δέσμει δέ με νῦν ἀσφαλέστερον, καὶ τήρει σεαυτῷ· δεσπότης μὲν γὰρ οὐ μόνον ἐμοῦ σὺ Καῖσαρ, ἀλλὰ καὶ γῆς καὶ θαλάττης καὶ παντὸς ἀνθρώπων γένους, ἐγὼ δὲ ἐπὶ τιμωρίαν δέομαι φρουρᾶς μείζονος, εἰ κατασχεδιάζω καὶ θεοῦ."},{"number":403,"text":"ταῦτʼ εἰπόντος παραχρῆμα μὲν Οὐεσπασιανὸς ἀπιστεῖν ἐδόκει καὶ τὸν Ἰώσηπον ὑπελάμβανεν ταῦτα περὶ σωτηρίας πανουργεῖν,"},{"number":404,"text":"κατὰ μικρὸν δὲ εἰς πίστιν ὑπήγετο τοῦ θεοῦ διεγείροντος αὐτὸν εἰς τὴν ἡγεμονίαν ἤδη καὶ τὰ σκῆπτρα διʼ ἑτέρων σημείων προδεικνύντος."},{"number":405,"text":"ἀτρεκῆ δὲ τὸν Ἰώσηπον καὶ ἐν ἄλλοις κατελάμβανεν· τῶν γὰρ τοῖς ἀπορρήτοις παρατυχόντων φίλων ὁ ἕτερος θαυμάζειν ἔφη πῶς οὔτε τοῖς ἐπὶ τῶν Ἰωταπάτων περὶ ἁλώσεως, οὔθʼ ἑαυτῷ προμαντεύσαιτο αἰχμαλωσίαν, εἰ μὴ ταῦτα λῆρος εἴη διακρουομένου τὰς ἐπʼ αὐτὸν ὀργάς."},{"number":406,"text":"ὁ δὲ Ἰώσηπος καὶ τοῖς Ἰωταπατηνοῖς ὅτι μετὰ τεσσαρακοστὴν ἑβδόμην ἡμέραν ἁλώσονται προειπεῖν ἔφη, καὶ ὅτι πρὸς Ῥωμαίων αὐτὸς ζωγρηθήσεται."},{"number":407,"text":"ταῦτα παρὰ τῶν αἰχμαλώτων κατʼ ἰδίαν ὁ Οὐεσπασιανὸς ἐκπυθόμενος ὡς εὕρισκεν ἀληθῆ, οὕτω πιστεύειν περὶ τῶν κατʼ αὐτὸν ἦρκτο."},{"number":408,"text":"φρουρᾶς μὲν οὖν καὶ δεσμῶν οὐκ ἀνίει τὸν Ἰώσηπον, ἐδωρεῖτο δʼ ἐσθῆτι καὶ τοῖς ἄλλοις κειμηλίοις φιλοφρονούμενός τε καὶ περιέπων διετέλει τὰ πολλὰ Τίτου τῇ τιμῇ συνεργοῦντος."}],"9":[{"number":409,"text":"Τετάρτῃ δὲ Πανέμου μηνὸς ἀναζεύξας εἰς Πτολεμαΐδα κἀκεῖθεν εἰς τὴν παράλιον ἀφικνεῖται Καισάρειαν, μεγίστην τῆς τε Ἰουδαίας πόλιν καὶ τὸ πλέον ὑφʼ Ἑλλήνων οἰκουμένην."},{"number":410,"text":"ἐδέχοντο δὲ καὶ τὴν στρατιὰν καὶ τὸν στρατηγὸν μετὰ πάσης εὐφημίας καὶ φιλοφροσύνης οἱ ἐπιχώριοι, καὶ κατʼ εὔνοιαν μὲν τὴν πρὸς Ῥωμαίους, τὸ δὲ πλέον ἔχθει τῶν κατεστραμμένων· διὸ καὶ τὸν Ἰώσηπον ἀθρόοι καταβοῶντες ἠξίουν κολάζειν."},{"number":411,"text":"Οὐεσπασιανὸς δὲ τὴν περὶ τούτου δέησιν ὡς ὑπʼ ἀκρίτου γινομένην πλήθους ἐξέλυσεν ἡσυχίᾳ·"},{"number":412,"text":"τῶν δὲ ταγμάτων τὰ μὲν δύο χειμερίσοντα ἐκάθισεν ἐπὶ τῆς Καισαρείας ἐπιτήδειον ὁρῶν τὴν πόλιν, τὸ δέκατον δὲ καὶ πέμπτον εἰς Σκυθόπολιν, ὡς μὴ θλίβοι παντὶ τῷ στρατῷ τὴν Καισάρειαν."},{"number":413,"text":"ἀλεεινὴ δʼ ἦν κἀκείνη χειμῶνος ὥρᾳ καθʼ ὅσον πνιγώδης θέρους ὑπὸ καυμάτων, πεδιὰς οὖσα καὶ παράλιος."},{"number":414,"text":"Ἐν δὲ τούτῳ συναθροισθέντες οἵ τε κατὰ στάσιν ἐκπίπτοντες τῶν πόλεων καὶ οἱ διαφυγόντες ἐκ τῶν κατεστραμμένων, πλῆθος οὐκ ὀλίγον, ἀνακτίζουσιν Ἰόππην ὁρμητήριον σφίσιν, ἐρημωθεῖσαν ὑπὸ Κεστίου πρότερον,"},{"number":415,"text":"καὶ τῆς χώρας ἐκπεπολεμωμένης ἀνειργόμενοι μεταβαίνειν ἔγνωσαν εἰς τὴν θάλασσαν."},{"number":416,"text":"πηξάμενοί τε πειρατικὰ σκάφη πλεῖστα τόν τε Συρίας καὶ Φοινίκης καὶ τὸν ἐπʼ Αἰγύπτου πόρον ἐλῄστευον, ἄπλωτά τε πᾶσιν ἐποίουν τὰ τῇδε πελάγη."},{"number":417,"text":"Οὐεσπασιανὸς δὲ ὡς ἔγνω τὴν σύνταξιν αὐτῶν, πέμπει πεζούς τε καὶ ἱππεῖς ἐπὶ τὴν Ἰόππην, οἳ νύκτωρ ὡς ἀφύλακτον εἰσέρχονται τὴν πόλιν."},{"number":418,"text":"οἱ δʼ ἐν αὐτῇ προῄσθοντο μὲν τὴν εἰσβολὴν καὶ καταδείσαντες τοῦ μὲν εἴργειν τοὺς Ῥωμαίους ἀπετρέποντο, συμφυγόντες δὲ εἰς τὰς ναῦς ἐξωτέρω βέλους διενυκτέρευσαν."},{"number":419,"text":"Ἀλιμένου δʼ οὔσης φύσει τῆς Ἰόππης, αἰγιαλῷ γὰρ ἐπιλήγει τραχεῖ καὶ τὸ μὲν ἄλλο πᾶν ὀρθίῳ, βραχὺ δὲ συννεύοντι κατὰ τὰς κεραίας ἑκατέρωθεν·"},{"number":420,"text":"αἱ δέ εἰσιν κρημνοὶ βαθεῖς καὶ προύχουσαι σπιλάδες εἰς τὸ πέλαγος, ἔνθα καὶ τῶν Ἀνδρομέδας δεσμῶν ἔτι δεικνύμενοι τύποι πιστοῦνται τὴν ἀρχαιότητα τοῦ μύθου,"},{"number":421,"text":"τύπτων δὲ τὸν αἰγιαλὸν ἐναντίος βορέας καὶ πρὸς ταῖς δεχομέναις πέτραις ὑψηλὸν ἀναπέμπων τὸ κῦμα σφαλερώτερον ἐρημίας τὸν ὅρμον ἀπεργάζεται·"},{"number":422,"text":"κατὰ τοῦτον σαλεύουσιν τοῖς ἀπὸ τῆς Ἰόππης ὑπὸ τὴν ἕω πνεῦμα βίαιον ἐπιπίπτει· μελαμβόριον ὑπὸ τῶν ταύτῃ πλοϊζομένων καλεῖται·"},{"number":423,"text":"καὶ τὰς μὲν ἀλλήλαις τῶν νεῶν αὐτόθι συνήραξεν, τὰς δὲ πρὸς ταῖς πέτραις, πολλὰς δὲ πρὸς ἀντίον κῦμα βιαζομένας εἰς τὸ πέλαγος, τόν τε γὰρ αἰγιαλὸν ὄντα πετρώδη καὶ τοὺς ἐπʼ αὐτοῦ πολεμίους ἐδεδοίκεσαν, μετέωρος ὑπεραρθεὶς ὁ κλύδων ἐβάπτιζεν."},{"number":424,"text":"ἦν δʼ οὔτε φυγῆς τόπος οὔτε μένουσιν σωτηρία, βίᾳ μὲν ἀνέμου τῆς θαλάσσης ἐξωθουμένοις, Ῥωμαίων δὲ τῆς πόλεως. καὶ πολλὴ μὲν οἰμωγὴ συρρηγνυμένων ἐγίνετο τῶν σκαφῶν, πολὺς δʼ ἀγνυμένων ὁ ψόφος."},{"number":425,"text":"καὶ τοῦ πλήθους οἱ μὲν ὑπὸ τῶν κυμάτων καλυπτόμενοι διεφθείροντο, πολλοὶ δὲ τοῖς ναυαγίοις ἐμπλεκόμενοι· τινὲς δὲ ὡς κουφοτέρῳ τὴν θάλατταν ἔφθανον τῷ σιδήρῳ σφᾶς αὐτοὺς ἀναιροῦντες."},{"number":426,"text":"τό γε μὴν πλεῖστον ὑπὸ τῶν κυμάτων ἐκφερόμενον περιεξαίνετο ταῖς ἀπορρῶξιν, ὡς αἱμαχθῆναι μὲν ἐπὶ πλεῖστον τὸ πέλαγος, πληρωθῆναι δὲ νεκρῶν τὴν παράλιον· καὶ γὰρ τοὺς ἐπὶ τὸν αἰγιαλὸν ἐκφερομένους ἐφεστῶτες οἱ Ῥωμαῖοι διέφθειρον."},{"number":427,"text":"ἀριθμὸς δὲ τῶν ἐκβρασθέντων σωμάτων τετρακισχίλιοι πρὸς τοῖς διακοσίοις ἦν. Ῥωμαῖοι δὲ λαβόντες ἀμαχητὶ τὴν πόλιν κατασκάπτουσιν."},{"number":428,"text":"Ἰόππη μὲν οὖν ἐν ὀλίγῳ χρόνῳ δεύτερον ὑπὸ Ῥωμαίοις ἑάλω."},{"number":429,"text":"Οὐεσπασιανὸς δὲ ὡς μὴ πάλιν οἱ πειραταὶ συναλισθεῖεν εἰς αὐτήν, στρατόπεδόν τε ἐπὶ τῆς ἀκροπόλεως ἐγείρει καὶ τὸ ἱππικὸν ἐν αὐτῷ καταλείπει μετὰ πεζῶν ὀλίγων,"},{"number":430,"text":"ἵνʼ οὗτοι μὲν κατὰ χώραν μένοντες φρουρῶσι τὸ στρατόπεδον, οἱ δʼ ἱππεῖς προνομεύωσι τὴν πέριξ καὶ τὰς περιοίκους κώμας τε καὶ πολίχνας ἐξαιρῶσιν τῆς Ἰόππης."},{"number":431,"text":"οἱ μὲν οὖν κατὰ τὰ προσταχθέντα τὴν χώραν κατατρέχοντες καθʼ ἡμέραν ἔτεμνόν τε καὶ ἠρήμουν ἅπασαν."},{"number":432,"text":"Ὡς δὲ εἰς τὰ Ἱεροσόλυμα τὸ κατὰ τὴν Ἰωταπάτην πάθος ἠγγέλη, τὸ μὲν πρῶτον ἠπίστουν οἱ πολλοὶ καὶ διὰ τὸ μέγεθος τῆς συμφορᾶς καὶ διὰ τὸ μηδένα τῶν λεγομένων αὐτόπτην παρεῖναι·"},{"number":433,"text":"διεσώθη γὰρ οὐδὲ ἄγγελος, ἀλλʼ αὐτοματὶ διεκήρυσσεν φήμη τὴν ἅλωσιν οἰκεία φύσει τῶν σκυθρωποτέρων."},{"number":434,"text":"κατʼ ὀλίγον δὲ διὰ τῶν προσχώρων ὥδευε τἀληθὲς καὶ παρὰ πᾶσιν ἀμφιβολίας ἦν ἤδη βεβαιότερον, προσεσχεδιάζετό γε μὴν τοῖς πεπραγμένοις καὶ τὰ μὴ γενόμενα· τεθνεὼς γὰρ ἐπὶ τῆς ἁλώσεως καὶ ὁ Ἰώσηπος ἠγγέλλετο."},{"number":435,"text":"τοῦτο μεγίστου τὰ Ἱεροσόλυμα πένθους ἐπλήρωσεν· κατὰ μέν γε οἴκους καὶ κατὰ συγγενείας οἷς προσήκων ἕκαστος ἦν τῶν ἀπολωλότων ἐθρηνεῖτο,"},{"number":436,"text":"τὸ δʼ ἐπὶ τῷ στρατηγῷ πένθος ἐδημεύθη, καὶ οἱ μὲν ξένους, οἱ δὲ συγγενεῖς, οἱ δὲ φίλους ἐθρήνουν, τὸν Ἰώσηπον δὲ πάντες,"},{"number":437,"text":"ὡς ἐπὶ τριακοστὴν μὲν ἡμέραν μὴ διαλιπεῖν τὰς ὀλοφύρσεις ἐν τῇ πόλει, πλείστους δὲ μισθοῦσθαι τοὺς αὐλητάς, οἳ θρήνων αὐτοῖς ἐξῆρχον."},{"number":438,"text":"Ὡς δὲ τἀληθῆ διεκαλύπτετο τῷ χρόνῳ καὶ τὰ μὲν κατὰ τὴν Ἰωταπάτην ὥσπερ εἶχεν, ἐσχεδιασμένον δὲ τὸ κατὰ τὸν Ἰώσηπον πάθος εὑρίσκετο, ζῆν δʼ αὐτὸν ἔγνωσαν καὶ παρὰ Ῥωμαίοις ὄντα καὶ πρὸς τῶν ἡγεμόνων πλέον ἢ κατʼ αἰχμαλώτου τύχην περιέπεσθαι, τοσοῦτον ὀργῆς ἐπὶ ζῶντος ὅσον εὐνοίας ἐπὶ τεθνάναι δοκοῦντος πρότερον ἀνελάμβανον."},{"number":439,"text":"καὶ παρʼ οἷς μὲν εἰς ἀνανδρίαν, παρʼ οἷς δὲ εἰς προδοσίαν ἐκακίζετο, πλήρης τε ἀγανακτήσεως ἦν καὶ τῶν κατʼ αὐτοῦ βλασφημιῶν ἡ πόλις."},{"number":440,"text":"παρωξύνοντο δὲ ταῖς πληγαῖς καὶ προσεξεκαίοντο ταῖς κακοπραγίαις· τό γε μὴν πταίειν, ὃ γίνεται τοῖς εὖ φρονοῦσιν ἀσφαλείας καὶ τῶν ὁμοίων φυλακῆς αἴτιον, ἐκείνοις κέντρον ἑτέρων ἐγίνετο συμφορῶν· καὶ τὸ τέλος ἀεὶ τῶν κακῶν αὖθις ἀρχή·"},{"number":441,"text":"μᾶλλον γοῦν ὥρμων ἐπὶ τοὺς Ῥωμαίους ὡς καὶ Ἰώσηπον ἐν αὐτοῖς ἀμυνούμενοι."},{"number":442,"text":"τοὺς μὲν οὖν ἐπὶ τῶν Ἱεροσολύμων τοιοῦτοι θόρυβοι κατεῖχον."},{"number":443,"text":"Οὐεσπασιανὸς δὲ καθʼ ἱστορίαν τῆς Ἀγρίππα βασιλείας, ἐνῆγεν γὰρ βασιλεὺς αὐτόν, ἅμα καὶ δεξιώσασθαι τὸν ἡγεμόνα σὺν τῇ στρατιᾷ τῷ κατὰ τὸν οἶκον ὄλβῳ προαιρούμενος καὶ καταστεῖλαι διʼ αὐτῶν τὰ νοσοῦντα τῆς ἀρχῆς, ἄρας ἀπὸ τῆς παράλου Καισαρείας εἰς τὴν Φιλίππου καλουμένην μεταβαίνει Καισάρειαν."},{"number":444,"text":"ἔνθα μέχρι μὲν ἡμερῶν εἴκοσι τὴν στρατιὰν διαναπαύων καὶ αὐτὸς ἐν εὐωχίαις ἦν, ἀποδιδοὺς τῷ θεῷ χαριστήρια τῶν κατωρθωμένων."},{"number":445,"text":"ὡς δʼ αὐτῷ Τιβεριὰς μὲν νεωτερίζειν, ἀφεστάναι δὲ ἠγγέλλοντο Ταριχέαι, μοῖρα δὲ τῆς Ἀγρίππα βασιλείας ἦσαν ἀμφότεραι, πανταχόθεν τοὺς Ἰουδαίους καταστρέφεσθαι διεγνωκὼς τὴν ἐπὶ τούτους στρατείαν εὔκαιρον ἡγεῖτο καὶ διʼ Ἀγρίππαν, ὡς εἰς ξενίας ἀμοιβὴν σωφρονίσων αὐτῷ τὰς πόλεις."},{"number":446,"text":"πέμπει δὴ τὸν υἱὸν Τίτον εἰς Καισάρειαν μετάξοντα τὴν ἐκεῖθεν στρατιὰν εἰς Σκυθόπολιν· ἡ δʼ ἐστὶν μεγίστη τῆς δεκαπόλεως καὶ γείτων τῆς Τιβεριάδος."},{"number":447,"text":"ἔνθα καὶ αὐτὸς παραγενόμενος ἐκδέχεται τὸν υἱὸν καὶ μετὰ τριῶν ταγμάτων προελθὼν στρατοπεδεύεται μὲν ἀπὸ τριάκοντα τῆς Τιβεριάδος σταδίων κατά τινα σταθμὸν εὐσύνοπτον τοῖς νεωτερίζουσιν·"},{"number":448,"text":"Ἔνναβρις ὀνομάζεται. πέμπει δὲ δεκαδάρχην Οὐαλεριανὸν σὺν ἱππεῦσιν πεντήκοντα διαλεχθησόμενον εἰρηνικὰ τοῖς κατὰ τὴν πόλιν καὶ προτρεψόμενον ἐπὶ πίστεις· ἀκηκόει γάρ, ὡς ἐπιθυμοίη μὲν εἰρήνης ὁ δῆμος, καταστασιάζοιτο δʼ ὑπό τινων πολεμεῖν βιαζομένων."},{"number":449,"text":"προσελάσας δὲ Οὐαλεριανὸς ἐπεὶ πλησίον ἦν τοῦ τείχους, αὐτός τε καταβαίνει καὶ τοὺς σὺν αὐτῷ τῶν ἱππέων ἀπέβησεν, ὡς μὴ δοκοῖεν ἀκροβολιζόμενοι παρεῖναι. καὶ πρὶν εἰς λόγους ἐλθεῖν"},{"number":450,"text":"ἐπεκθέουσιν αὐτῷ τῶν στασιαστῶν οἱ δυνατώτατοι μεθʼ ὅπλων. ἐξηγεῖτο δʼ αὐτῶν Ἰησοῦς τις ὄνομα παῖς Τοῦφα τοῦ λῃστρικοῦ στίφους ὁ κορυφαιότατος."},{"number":451,"text":"Οὐαλεριανὸς δὲ οὔτε παρὰ τὰς ἐντολὰς τοῦ στρατηγοῦ συμβαλεῖν ἀσφαλὲς ἡγούμενος, εἰ καὶ τὸ νικᾶν εἴη βέβαιον, καὶ σφαλερὸν τὸ μάχεσθαι πολλοῖς μετʼ ὀλίγων ἀπαρασκευάστοις τε πρὸς ἑτοίμους,"},{"number":452,"text":"καὶ ἄλλως ἐκπλαγεὶς τὴν ἀδόκητον τῶν Ἰουδαίων τόλμαν, φεύγει πεζός, ἕτεροί τε ὁμοίως πέντε τοὺς ἵππους ἀπέλιπον, οὓς οἱ περὶ τὸν Ἰησοῦν ἀπήγαγον εἰς τὴν πόλιν γεγηθότες ὡς μάχῃ ληφθέντας οὐκ ἐνέδρᾳ."},{"number":453,"text":"Τοῦτο καταδείσαντες οἱ γηραιοὶ τοῦ δήμου καὶ προύχειν δοκοῦντες φεύγουσι μὲν εἰς τὸ τῶν Ῥωμαίων στρατόπεδον,"},{"number":454,"text":"ἐπαγόμενοι δὲ τὸν βασιλέα προσπίπτουσιν ἱκέται Οὐεσπασιανῷ, μὴ σφᾶς περιιδεῖν δεόμενοι, μηδὲ τὴν ὀλίγων ἀπόνοιαν ἡγήσασθαι τῆς πόλεως ὅλης·"},{"number":455,"text":"φείσασθαι δὲ τοῦ δήμου Ῥωμαίοις φίλα φρονοῦντος ἀεί, καὶ τοὺς αἰτίους τιμωρήσασθαι τῆς ἀποστάσεως, ὑφʼ ὧν αὐτοὶ φρουρηθῆναι μέχρι νῦν ἐπὶ δεξιὰς ἐπειγόμενοι πάλαι."},{"number":456,"text":"ταύταις ἐνεδίδου ταῖς ἱκεσίαις ὁ στρατηγὸς καίτοι διὰ τὴν ἁρπαγὴν τῶν ἵππων ἐφʼ ὅλην ὠργισμένος τὴν πόλιν· καὶ γὰρ ἀγωνιῶντα περὶ αὐτῆς τὸν Ἀγρίππαν ἑώρα."},{"number":457,"text":"λαβόντων δὲ τούτων τῷ δήμῳ δεξιὰς οἱ περὶ τὸν Ἰησοῦν οὐκέτι ἀσφαλὲς ἡγούμενοι μένειν ἐπὶ τῆς Τιβεριάδος εἰς Ταριχέας ἀποδιδράσκουσιν."},{"number":458,"text":"καὶ μεθʼ ἡμέραν Οὐεσπασιανὸς σὺν ἱππεῦσιν προπέμπει πρὸς τὴν ἀκρώρειαν Τραϊανὸν ἀποπειραθῆναι τοῦ πλήθους, εἰ πάντες εἰρηνικὰ φρονοῖεν."},{"number":459,"text":"ὡς δʼ ἔγνω τὸν δῆμον ὁμοφρονοῦντα τοῖς ἱκέταις, ἀναλαβὼν τὴν δύναμιν ᾔει πρὸς τὴν πόλιν. οἱ δὲ τάς τε πύλας ἀνοίγουσιν αὐτῷ καὶ μετʼ εὐφημιῶν ὑπήντων σωτῆρα καὶ εὐεργέτην ἀνακαλοῦντες."},{"number":460,"text":"τῆς δὲ στρατιᾶς τριβομένης περὶ τὴν τῶν εἰσόδων στενότητα παραρρῆξαι τοῦ κατὰ μεσημβρίαν τείχους Οὐεσπασιανὸς κελεύσας πλατύνει τὴν εἰσβολὴν αὐτοῖς."},{"number":461,"text":"ἁρπαγῆς μέντοι καὶ ὕβρεως ἀπέχεσθαι παρήγγειλεν τῷ βασιλεῖ χαριζόμενος, τῶν τε τειχῶν διὰ τοῦτον ἐφείσατο συμμενεῖν πρὸς τὸ λοιπὸν ἐγγυωμένου τοὺς ἐν αὐτοῖς, καὶ πολλὰ κεκακωμένην τὴν πόλιν ἐκ τῆς στάσεως ἀνελάμβανεν."}],"10":[{"number":462,"text":"Ἔπειτα προελθὼν αὐτῆς τε μεταξὺ καὶ Ταριχεῶν στρατοπεδεύεται, τειχίζει τε τὴν παρεμβολὴν ὀχυρωτέραν ὑφορώμενος ἐκεῖ πολέμου τριβὴν αὐτῷ γενησομένην·"},{"number":463,"text":"συνέρρει γὰρ εἰς τὰς Ταριχέας πᾶν τὸ νεωτερίζον, τῇ τε τῆς πόλεως ὀχυρότητι καὶ τῇ λίμνῃ πεποιθότες, ἣ καλεῖται Γεννησὰρ πρὸς τῶν ἐπιχωρίων."},{"number":464,"text":"ἡ μὲν γὰρ πόλις, ὥσπερ ἡ Τιβεριὰς ὑπόρειος οὖσα, καθὰ μὴ τῇ λίμνῃ προσεκλύζετο πάντοθεν ὑπὸ τοῦ Ἰωσήπου τετείχιστο καρτερῶς, ἔλασσον μέντοι τῆς Τιβεριάδος·"},{"number":465,"text":"τὸν μὲν γὰρ ἐκεῖ περίβολον ἐν ἀρχῇ τῆς ἀποστάσεως δαψιλείᾳ χρημάτων καὶ δυνάμεως ἐκρατύνατο, Ταριχέαι δʼ αὐτοῦ τὰ λείψανα τῆς φιλοτιμίας μετέλαβον."},{"number":466,"text":"σκάφη δʼ ἦν αὐτοῖς ἐπὶ τῆς λίμνης παρεσκευασμένα πολλὰ πρός τε τὸ συμφεύγειν ἐπὶ γῆς ἡττωμένους, κἂν εἰ δέοι, διαναυμαχεῖν ἐξηρτυμένα."},{"number":467,"text":"περιβαλλομένων δὲ τῶν Ῥωμαίων τὸ στρατόπεδον οἱ περὶ τὸν Ἰησοῦν οὔτε πρὸς τὸ πλῆθος οὔτε πρὸς τὴν εὐταξίαν τῶν πολεμίων ὑποδείσαντες προθέουσιν,"},{"number":468,"text":"καὶ πρὸς τὴν πρώτην ἔφοδον τῶν τειχοποιῶν σκεδασθέντων ὀλίγα τῆς δομήσεως σπαράξαντες, ὡς ἑώρων τοὺς ὁπλίτας ἀθροιζομένους, πρίν τι παθεῖν εἰς τοὺς σφετέρους ἀνέφευγον· ἐπιδιώξαντες δὲ Ῥωμαῖοι συνελαύνουσιν αὐτοὺς εἰς τὰ σκάφη."},{"number":469,"text":"καὶ οἱ μὲν ἀναχθέντες εἰς ὅσον ἐξικνεῖσθαι τῶν Ῥωμαίων βάλλοντες δύναιντο τάς τε ἀγκύρας ἔβαλλον καὶ πυκνώσαντες ὥσπερ φάλαγγα τὰς ναῦς ἐπαλλήλους τοῖς ἐπὶ γῆς πολεμίοις διεναυμάχουν·"},{"number":470,"text":"Οὐεσπασιανὸς δὲ τὸ πολὺ πλῆθος αὐτῶν ἠθροισμένον ἀκούων ἐν τῷ πρὸ τῆς πόλεως πεδίῳ πέμπει τὸν υἱὸν σὺν ἱππεῦσιν ἑξακοσίοις ἐπιλέκτοις."},{"number":471,"text":"Ὁ δʼ ὑπέρογκον εὑρὼν τὴν τῶν πολεμίων πληθὺν πρὸς μὲν τὸν πατέρα πέμπει πλείονος δυνάμεως αὐτῷ δεῖν λέγων. αὐτὸς δὲ τοὺς μὲν πλείους τῶν ἱππέων ὡρμημένους ὁρῶν καὶ πρὶν ἀφικέσθαι βοήθειαν, ἔστιν δʼ οὓς ἡσυχῆ πρὸς τὸ πλῆθος τῶν Ἰουδαίων καταπεπληγότας, ἐν ἐπηκόῳ στὰς ἔλεξεν ὧδε·"},{"number":472,"text":"ἄνδρες, ἔφη, Ῥωμαῖοι, καλὸν γὰρ ἐν ἀρχῇ τῶν λόγων ὑπομνῆσαι τοῦ γένους ὑμᾶς, ἵνʼ εἰδῆτε, τίνες ὄντες πρὸς τίνας μάχεσθαι μέλλομεν."},{"number":473,"text":"τὰς μέν γε ἡμετέρας χεῖρας οὐδὲν εἰς τοῦτο τῶν ἐπὶ τῆς οἰκουμένης διαπέφευγεν, Ἰουδαῖοι δέ, ἵνʼ εἴπωμεν καὶ ὑπὲρ αὐτῶν, μέχρι νῦν οὐ κοπιῶσιν ἡττώμενοι. καὶ δεινὸν ἐκείνων ἑστώτων ἐν ταῖς κακοπραγίαις ἡμᾶς τοῖς εὐτυχήμασιν ἐγκάμνειν."},{"number":474,"text":"προθυμίας μὲν εἰς τὸ φανερὸν ὑμᾶς εὖ ἔχοντας χαίρω βλέπων, δέδοικα δὲ μή τινι τῶν πολεμίων τὸ πλῆθος κατάπληξιν λεληθυῖαν ἐνεργάσηται."},{"number":475,"text":"λογισάσθω δὴ πάλιν οἷος πρὸς οἵους παρατάξεται, καὶ διότι Ἰουδαῖοι μέν, εἰ καὶ σφόδρα τολμηταὶ καὶ θανάτου καταφρονοῦντες, ἀλλʼ ἀσύντακτοί τε καὶ πολέμων ἄπειροι καὶ ὄχλος ἂν ἄλλως, οὐ στρατιὰ λέγοιντο· τὰ δὲ τῆς ἡμετέρας ἐμπειρίας καὶ τάξεως τί δεῖ καὶ λέγειν; ἐπὶ τοῦτο μέντοι γε μόνοι καὶ κατʼ εἰρήνην ἀσκούμεθα τοῖς ὅπλοις, ἵνʼ ἐν πολέμῳ μὴ πρὸς τὸ ἀντίπαλον ἀριθμῶμεν ἑαυτούς."},{"number":476,"text":"ἐπεὶ τίς ὄνησις τῆς διηνεκοῦς στρατείας, ἂν ἴσοι πρὸς ἀστρατεύτους ἀντιτασσώμεθα;"},{"number":477,"text":"λογίζεσθε δέ, ὅτι καὶ πρὸς γυμνῆτας ὁπλῖται καὶ ἱππεῖς πρὸς πεζοὺς καὶ στρατηγούμενοι πρὸς ἀστρατηγήτους διαγωνίζεσθε, καὶ ὡς ὑμᾶς μὲν ταῦτα πολλαπλασίους ποιεῖ τὰ πλεονεκτήματα, πολὺ δὲ τοῦ τῶν πολεμίων ἀριθμοῦ [παραιρεῖται τὰ ἐλαττώματα]."},{"number":478,"text":"κατορθοῖ δὲ τοὺς πολέμους οὐ πλῆθος ἀνθρώπων, κἂν ᾖ μάχιμον, ἀνδρεία δέ, κἂν ἐν ὀλίγοις· οἱ μέν γε καὶ τάξασθαι ῥᾴδιοι καὶ προσαμύνειν ἑαυτοῖς, αἱ δʼ ὑπέρογκοι δυνάμεις ὑφʼ ἑαυτῶν βλάπτονται πλέον ἢ τῶν πολεμίων."},{"number":479,"text":"Ἰουδαίων μὲν οὖν τόλμα καὶ θράσος ἡγεῖται καὶ ἀπόνοια, πάθη κατὰ μὲν τὰς εὐπραγίας εὔτονα, σβεννύμενα δὲ ἐν ἐλαχίστοις σφάλμασιν· ἡμῶν δʼ ἀρετὴ καὶ εὐπείθεια καὶ τὸ γενναῖον, ὃ κἀν τοῖς ἄλλοις εὐτυχήμασιν ἀκμάζει κἀν τοῖς πταίσμασιν οὐ μέχρι τέλους σφάλλεται."},{"number":480,"text":"καὶ ὑπὲρ μειζόνων δὲ ἢ Ἰουδαῖοι διαγωνιεῖσθε· καὶ γὰρ εἰ περὶ ἐλευθερίας καὶ πατρίδων ἐκείνοις ὁ πόλεμος κινδυνεύεται, τί μεῖζον ἡμῖν εὐδοξίας καὶ τοῦ μὴ δοκεῖν μετὰ τὴν τῆς οἰκουμένης ἡγεμονίαν ἐν ἀντιπάλῳ τὰ Ἰουδαίων τίθεσθαι;"},{"number":481,"text":"σκεπτέον δʼ ὅτι καὶ παθεῖν μὲν οὐδὲν ἀνήκεστον ἡμῖν φόβος· πολλοὶ γὰρ οἱ βοηθήσοντες καὶ πλησίον· ἁρπάσαι δὲ τὴν νίκην δυνάμεθα, καὶ χρὴ τοὺς ὑπὸ τοῦ πατρὸς πεμπομένους ἡμῖν συμμάχους φθάνειν, ἵνʼ ἀκοινώνητόν τε ᾖ τὸ κατόρθωμα καὶ μεῖζον."},{"number":482,"text":"νομίζω δʼ ἔγωγε ἐπὶ τῆσδε τῆς ὥρας καὶ τὸν πατέρα τὸν ἐμὸν κρίνεσθαι κἀμὲ καὶ ὑμᾶς, εἰ τῶν μὲν προκατωρθωμένων ἄξιος ἐκεῖνος, ἐγὼ δʼ ἐκείνου παῖς, στρατιῶται δʼ ὑμεῖς ἐμοῦ· καὶ γὰρ ἐκείνῳ τὸ νικᾶν ἔθος, κἀγὼ πρὸς αὐτὸν ὑποστρέφειν οὐκ ἂν ὑπομείναιμι λειφθείς."},{"number":483,"text":"ὑμεῖς δὲ πῶς οὐκ ἂν αἰσχύνοισθε προκινδυνεύοντος ἡγεμόνος ἡττώμενοι; προκινδυνεύσω γάρ, εὖ ἴστε, καὶ πρῶτος εἰς τοὺς πολεμίους ἐμβαλῶ."},{"number":484,"text":"μὴ λείπεσθε δʼ ὑμεῖς ἐμοῦ πεπεισμένοι τὴν ἐμὴν ὁρμὴν παρακροτεῖσθαι θεῷ συμμάχῳ, καὶ προγινώσκετε σαφῶς, ὅτι τῆς ἔξω μάχης πλέον τι κατορθώσομεν."},{"number":485,"text":"Ταῦτα τοῦ Τίτου διεξιόντος προθυμία δαιμόνιος ἐμπίπτει τοῖς ἀνδράσιν, καὶ προσγενομένου πρὶν συμβαλεῖν Τραϊανοῦ μετὰ τετρακοσίων ἱππέων ἤσχαλλον ὡς μειουμένης τῆς νίκης αὐτοῖς διὰ τὴν κοινωνίαν."},{"number":486,"text":"ἔπεμψεν δὲ Οὐεσπασιανὸς καὶ Ἀντώνιον Σίλωνα σὺν δισχιλίοις τοξόταις κελεύσας καταλαβόντας τὸ ἀντικρὺ τῆς πόλεως ὄρος τοὺς ἐπὶ τοῦ τείχους ἀνείργειν."},{"number":487,"text":"καὶ οἱ μὲν ὡς προσετέτακτο τοὺς ταύτῃ πειρωμένους ἐκβοηθεῖν περιέσχον, ὁ δὲ Τίτος πρῶτος τὸν ἵππον ἤλαυνεν εἰς τοὺς πολεμίους καὶ σὺν κραυγῇ μετʼ αὐτὸν οἱ λοιποὶ παρεκτείναντες ἑαυτοὺς εἰς ὅσον ἐπεῖχον οἱ πολέμιοι τὸ πεδίον· παρὸ καὶ πολὺ πλείους ἔδοξαν."},{"number":488,"text":"οἱ δὲ Ἰουδαῖοι καίτοι τήν τε ὁρμὴν καὶ τὴν εὐταξίαν αὐτῶν καταπλαγέντες πρὸς ὀλίγον μὲν ἀντέσχον ταῖς ἐμβολαῖς, νυσσόμενοι δὲ τοῖς κοντοῖς καὶ τῷ ῥοίζῳ τῶν ἱππέων ἀνατρεπόμενοι συνεπατοῦντο."},{"number":489,"text":"πολλῶν δὲ πανταχοῦ φονευομένων διασκίδνανται καὶ πρὸς τὴν πόλιν ὡς ἕκαστος εἶχεν τάχους ἔφευγον."},{"number":490,"text":"Τίτος δὲ τοὺς μὲν κατόπιν προσκείμενος ἀνῄρει, τῶν δὲ διεκπαίων ἀθρόων, οὓς δὲ φθάνων κατὰ στόμα διήλαυνεν, πολλοὺς δὲ συνηλοία περὶ ἀλλήλοις πεσόντας ἐμπηδῶν,"},{"number":491,"text":"πᾶσιν δὲ τὰς πρὸς τὸ τεῖχος φυγὰς ὑπετέμνετο καὶ πρὸς τὸ πεδίον ἀπέστρεφεν, ἕως τῷ πλήθει βιασάμενοι καὶ διεκπεσόντες εἰς τὴν πόλιν συνέφευγον."},{"number":492,"text":"Ἐκδέχεται δὲ αὐτοὺς πάλιν στάσις ἔσω χαλεπή· τοῖς μὲν γὰρ ἐπιχωρίοις διά τε τὰς κτήσεις καὶ τὴν πόλιν οὐκ ἐδόκει πολεμεῖν ἀπʼ ἀρχῆς καὶ τότε διὰ τὴν ἧτταν πλέον·"},{"number":493,"text":"ὁ δʼ ἔπηλυς πολὺς ὢν πλεῖον ἐβιάζετο, καὶ διωργισμένων ἐπʼ ἀλλήλοις κραυγή τε ἦν καὶ θόρυβος ὡς ὅσον οὔπω φερομένων εἰς ὅπλα."},{"number":494,"text":"κατακούσας δὲ τῆς ταραχῆς Τίτος, οὐ γὰρ ἦν ἄπωθεν τοῦ τείχους, οὗτος ἦν ὁ καιρός, ἐκβοᾷ, καὶ τί, συστρατιῶται, μέλλομεν ἐκδιδόντος ἡμῖν Ἰουδαίους θεοῦ; δέξασθε τὴν νίκην."},{"number":495,"text":"οὐκ ἀκούετε βοῆς; στασιάζουσιν οἱ τὰς χεῖρας ἡμῶν διεκφυγόντες. ἔχομεν τὴν πόλιν, ἐὰν ταχύνωμεν· δεῖ δὲ πόνου πρὸς τῷ τάχει καὶ λήματος· οὐδὲν γὰρ τῶν μεγάλων φιλεῖ δίχα κινδύνου κατορθοῦσθαι."},{"number":496,"text":"φθάνειν δʼ οὐ μόνον χρὴ τὴν τῶν πολεμίων ὁμόνοιαν, οὓς ἀνάγκη διαλλάξει ταχέως, ἀλλὰ καὶ τὴν τῶν ἡμετέρων βοήθειαν, ἵνα πρὸς τῷ νικῆσαι τοσοῦτον πλῆθος ὀλίγοι καὶ τὴν πόλιν ἕλωμεν μόνοι."},{"number":497,"text":"Ταῦθʼ ἅμα λέγων ἐπὶ τὸν ἵππον ἀνεπήδα καὶ καθηγεῖται πρὸς τὴν λίμνην, διʼ ἧς ἐλάσας πρῶτος εἰς τὴν πόλιν εἰσέρχεται καὶ μετʼ αὐτὸν οἱ λοιποί."},{"number":498,"text":"δέος δὲ πρὸς τὴν τόλμαν αὐτοῦ τοῖς ἐπὶ τῶν τειχῶν ἐνέπεσεν, καὶ μάχεσθαι μὲν ἢ διακωλύειν οὐδεὶς ὑπέμεινεν, λιπόντες δὲ τὴν φρουρὰν οἱ μὲν περὶ τὸν Ἰησοῦν διὰ τῆς χώρας ἔφευγον,"},{"number":499,"text":"οἱ δʼ ἐπὶ τὴν λίμνην καταθέοντες ὑπαντιάζουσιν τοῖς πολεμίοις περιέπιπτον· ἐκτείνοντο δʼ οἱ μὲν ἐπιβαίνοντες τῶν σκαφῶν, οἱ δὲ τοῖς ἀναχθεῖσιν προσπίπτειν πειρώμενοι. πολὺς δὲ τῶν κατὰ τὴν πόλιν ἦν φόνος,"},{"number":500,"text":"τῶν μὲν ἐπηλύδων ὅσοι μὴ διαφυγεῖν ἔφθασαν ἀντιτασσομένων, ἀμαχητὶ δὲ τῶν ἐπιχωρίων· κατὰ γὰρ ἐλπίδα δεξιᾶς καὶ τὸ συνειδὸς τοῦ μὴ βεβουλεῦσθαι πολεμεῖν μάχης ἀπετρέποντο,"},{"number":501,"text":"μέχρι Τίτος τοὺς μὲν αἰτίους ἀνελών, οἰκτείρας δὲ τοὺς ἐπιχωρίους ἀνεπαύσατο φόνου."},{"number":502,"text":"καὶ οἱ μὲν εἰς τὴν λίμνην καταφυγόντες ἐπεὶ τὴν πόλιν εἶδον ἑαλωκυῖαν, ὡς πορρωτάτω τῶν πολεμίων ἀνήχθησαν·"},{"number":503,"text":"Τίτος δʼ ἐκπέμψας τινὰ τῶν ἱππέων εὐαγγελίζεται τῷ πατρὶ τὸ ἔργον."},{"number":504,"text":"ὁ δʼ, ὡς εἰκός, ὑπερησθεὶς τῇ τε τοῦ παιδὸς ἀρετῇ καὶ τῷ κατορθώματι, μεγίστη γὰρ ἐδόκει καθῃρῆσθαι μοῖρα τοῦ πολέμου, τότε μὲν ἐλθὼν περισχόντας τὴν πόλιν φρουρεῖν ἐκέλευσεν, ὡς μὴ διαλάθοι τις ἐξ αὐτῆς, καὶ κτείνειν προσέταξεν"},{"number":505,"text":"τῇ δʼ ὑστεραίᾳ πρὸς τὴν λίμνην καταβὰς σχεδίας ἐκέλευσεν πήσσειν ἐπὶ τοὺς καταπεφευγότας· αἱ δʼ ἐγίνοντο ταχέως ἀφθονίᾳ τε ὕλης καὶ πλήθει τεχνιτῶν."},{"number":506,"text":"Ἡ δὲ λίμνη Γεννησὰρ μὲν ἀπὸ τῆς προσεχοῦς χώρας καλεῖται, σταδίων δʼ εὖρος οὖσα τεσσαράκοντα καὶ πρὸς τούτοις ἑτέρων ἑκατὸν τὸ μῆκος γλυκεῖά τε ὅμως ἐστὶ καὶ ποτιμωτάτη·"},{"number":507,"text":"καὶ γὰρ τῆς ἑλώδους παχύτητος ἔχει τὸ νᾶμα λεπτότερον καθαρά τʼ ἐστὶν πάντοθεν αἰγιαλοῖς ἐπιλήγουσα καὶ ψάμμῳ, πρὸς δὲ εὔκρατος ἀρύσασθαι, ποταμοῦ μὲν ἢ κρήνης προσηνεστέρα, ψυχροτέρα δὲ ἢ κατὰ λίμνης διάχυσιν ἀεὶ μένουσα."},{"number":508,"text":"τὸ μὲν γὰρ ὕδωρ οὐκ ἀπᾴδει χιόνος ἐξαιθριασθέν, ὅπερ θέρους νυκτὸς ποιεῖν ἔθος τοῖς ἐπιχωρίοις, γένη δὲ ἰχθύων ἐν αὐτῇ διάφορα πρὸς τοὺς ἀλλαχοῦ γεῦσίν τε καὶ ἰδέαν."},{"number":509,"text":"μέση δʼ ὑπὸ τοῦ Ἰορδάνου τέμνεται. καὶ δοκεῖ μὲν Ἰορδάνου πηγὴ τὸ Πάνειον, φέρεται δʼ ὑπὸ γῆν εἰς τοῦτο κρυπτῶς ἐκ τῆς καλουμένης Φιάλης·"},{"number":510,"text":"ἡ δʼ ἐστὶν ἀνιόντων εἰς τὴν Τραχωνῖτιν ἀπὸ σταδίων ἑκατὸν εἴκοσι Καισαρείας τῆς ὁδοῦ κατὰ τὸ δεξιὸν μέρος οὐκ ἄπωθεν."},{"number":511,"text":"ἐκ μὲν οὖν τῆς περιφερείας ἐτύμως Φιάλη καλεῖται τροχοειδὴς οὖσα λίμνη, μένει δʼ ἐπὶ χείλους αὐτῆς ἀεὶ τὸ ὕδωρ μήθʼ ὑπονοστοῦν μήθʼ ὑπερχεόμενον."},{"number":512,"text":"ἀγνοούμενος δὲ τέως ὁ Ἰορδάνης ἐντεῦθεν ἄρχεσθαι διὰ τοῦ τετραρχήσαντος Τραχωνιτῶν ἠλέγχθη Φιλίππου·"},{"number":513,"text":"βαλὼν γὰρ οὗτος εἰς τὴν Φιάλην ἄχυρα κατὰ τὸ Πάνειον, ἔνθεν ἐδόκουν οἱ παλαιοὶ γεννᾶσθαι τὸν ποταμόν, εὗρεν ἀνενεχθέντα."},{"number":514,"text":"τοῦ μὲν οὖν Πανείου τὸ φυσικὸν κάλλος ὑπὸ τῆς βασιλικῆς προσεξήσκηται πολυτελείας τῷ Ἀγρίππα πλούτῳ κεκοσμημένον·"},{"number":515,"text":"ἀρχόμενος δὲ φανεροῦ ῥεύματος ὁ Ἰορδάνης ἀπὸ τοῦδε τοῦ ἄντρου κόπτει μὲν τὰ τῆς Σεμεχωνίτιδος λίμνης ἕλη καὶ τέλματα, διαμείψας δʼ ἑτέρους ἑκατὸν εἴκοσι σταδίους μετὰ πόλιν Ἰουλιάδα διεκπαίει τὴν Γεννησὰρ μέσην, ἔπειτα πολλὴν ἀναμετρούμενος ἐρημίαν εἰς τὴν Ἀσφαλτῖτιν ἔξεισι λίμνην."},{"number":516,"text":"Παρατείνει δὲ τὴν Γεννησὰρ ὁμώνυμος χώρα θαυμαστὴ φύσιν τε καὶ κάλλος· οὔτε γὰρ αὐτή τι φυτὸν ἀρνεῖται διὰ τὴν πιότητα, καὶ πᾶν πεφυτεύκασιν οἱ νεμόμενοι, τοῦ δʼ ἀέρος τὸ εὔκρατον ἁρμόζει καὶ τοῖς διαφόροις."},{"number":517,"text":"καρύαι μέν γε φυτῶν τὸ χειμεριώτατον ἄπειροι τεθήλασιν ἔνθα φοίνικες, οἳ καύματι τρέφονται, συκαῖ δὲ καὶ ἐλαῖαι πλησίον τούτων, αἷς μαλθακώτερος ἀὴρ ἀποδέδεικται."},{"number":518,"text":"φιλοτιμίαν ἄν τις εἴποι τῆς φύσεως βιασαμένης εἰς ἓν συναγαγεῖν τὰ μάχιμα καὶ τῶν ὡρῶν ἀγαθὴν ἔριν ἑκάστης ὥσπερ ἀντιποιουμένης τοῦ χωρίου· καὶ γὰρ οὐ μόνον τρέφει παρὰ δόξαν τὰς διαφόρους ὀπώρας ἀλλὰ καὶ διαφυλάσσει."},{"number":519,"text":"τὰ μέν γε βασιλικώτατα σταφυλήν τε καὶ σῦκον δέκα μησὶν ἀδιαλείπτως χορηγεῖ, τοὺς δὲ λοιποὺς καρποὺς διʼ ἔτους ὅλου περιγηράσκοντας ἑαυτοῖς· πρὸς γὰρ τῇ τῶν ἀέρων εὐκρασίᾳ καὶ πηγῇ διάρδεται γονιμωτάτῃ, Καφαρναοὺμ αὐτὴν οἱ ἐπιχώριοι καλοῦσιν."},{"number":520,"text":"ταύτην φλέβα τινὲς τοῦ Νείλου ἔδοξαν, ἐπεὶ γεννᾷ τῷ κατὰ τὴν Ἀλεξανδρέων λίμνην κορακίνῳ παραπλήσιον."},{"number":521,"text":"μῆκος δὲ τοῦ χωρίου παρατείνει κατὰ τὸν αἰγιαλὸν τῆς ὁμωνύμου λίμνης ἐπὶ σταδίους τριάκοντα, καὶ εὖρος εἴκοσι. ταῦτα μὲν οὕτως φύσεως ἔχει."},{"number":522,"text":"Οὐεσπασιανὸς δέ, ἐπεὶ παρεσκευάσθησαν αἱ σχεδίαι, τῆς δυνάμεως ἐπιβήσας ὅσον ᾤετο τοῖς κατὰ τὴν λίμνην ἀνταρκέσειν ἐπανήγετο. τοῖς δὲ συνελαυνομένοις οὔτʼ ἐπὶ γῆν διαφεύγειν ἦν ἐκπεπολεμωμένων πάντων οὔτʼ ἐξ ἴσου διαναυμαχεῖν·"},{"number":523,"text":"τά τε γὰρ σκάφη μικρὰ ὄντα καὶ λῃστρικὰ πρὸς τὰς σχεδίας ἦν ἀσθενῆ, καὶ καθʼ ἕκαστον ἐμπλέοντες ὀλίγοι πρὸς ἀθρόους ἐφεστῶτας τοὺς Ῥωμαίους ἐγγίζειν ἐδεδοίκεισαν."},{"number":524,"text":"ὅμως δʼ οὖν ἐκπεριπλέοντες τὰς σχεδίας, ἔστιν δʼ ὅπου καὶ πλησιάζοντες, πόρρωθεν τοὺς Ῥωμαίους ἔβαλλον λίθοις καὶ παραξύοντες ἐγγύθεν ἔπαιον."},{"number":525,"text":"ἐκακοῦντο δʼ αὐτοὶ πλέον κατʼ ἀμφότερα· ταῖς τε γὰρ χερμάσιν οὐδὲν δρῶντες ὅτι μὴ κτύπον ἐπάλληλον, εἰς γὰρ πεφραγμένους ἔβαλλον, ἐφικτοὶ τοῖς Ῥωμαίων ἐγίνοντο βέλεσιν, καὶ πλησιάζειν τολμῶντες πρὶν δρᾶσαί τι παθεῖν ἔφθανον καὶ σὺν αὐτοῖς ἐβαπτίζοντο τοῖς σκάφεσιν."},{"number":526,"text":"τῶν δὲ διεκπαίειν πειρωμένων πολλοὺς μὲν ἐφικνούμενοι κοντοῖς διέπειρον, οὓς δὲ ξιφήρεις ἐπιπηδῶντες εἰς τὰ σκάφη, τινὰς δὲ συντρεχούσαις ταῖς σχεδίαις ἐναποληφθέντας μέσους εἷλον ἅμα ταῖς ἁλιάσιν."},{"number":527,"text":"τῶν δὲ βαπτισθέντων τοὺς ἀνανεύοντας ἢ βέλος ἔφθανεν ἢ σχεδία κατελάμβανεν, καὶ προσβαίνειν ὑπʼ ἀμηχανίας εἰς τοὺς ἐχθροὺς πειρωμένων ἢ κεφαλὰς ἢ χεῖρας ἀπέκοπτον οἱ Ῥωμαῖοι."},{"number":528,"text":"πολλή τε ἦν αὐτῶν καὶ ποικίλη φθορὰ πανταχοῦ, μέχρι τραπέντες εἰς γῆν ἐξεώσθησαν οἱ λοιποὶ κεκυκλωμένων αὐτοῖς τῶν ἁλιάδων."},{"number":529,"text":"ἐκχεόμενοι δὲ πολλοὶ μὲν ἐν αὐτῇ κατηκοντίζοντο τῇ λίμνῃ, πολλοὺς δʼ ἐκπηδήσαντας οἱ Ῥωμαῖοι διέφθειραν ἐπὶ γῆς. ἦν δʼ ἰδεῖν κεκερασμένην μὲν αἵματι, πεπληρωμένην δὲ νεκρῶν τὴν λίμνην ἅπασαν· διεσώθη γὰρ οὐδείς."},{"number":530,"text":"δεινὴ δὲ ταῖς ἑξῆς ἡμέραις περιεῖχε τὴν χώραν ὀδμή τε καὶ ὄψις· οἱ μὲν γὰρ αἰγιαλοὶ ναυαγίων ἅμα καὶ διοιδούντων ἔγεμον σωμάτων, ἐκκαιόμενοι δὲ καὶ μυδῶντες οἱ νεκροὶ τὸν ἀέρα διέφθειρον, ὡς μὴ μόνον οἰκτρὸν Ἰουδαίοις γενέσθαι τὸ πάθος, ἀλλὰ καὶ διὰ μίσους τοῖς δράσασιν ἐλθεῖν."},{"number":531,"text":"τοῦτο μὲν ἐκείνης τῆς ναυμαχίας τὸ τέλος, ἀπέθανον δὲ σὺν τοῖς ἐπὶ τῆς πόλεως πρότερον πεσοῦσιν ἑξακισχίλιοι ἑπτακόσιοι."},{"number":532,"text":"Οὐεσπασιανὸς δὲ μετὰ τὴν μάχην καθίζει μὲν ἐπὶ βήματος ἐν Ταριχέαις, διακρίνων δʼ ἀπὸ τῶν ἐπιχωρίων τὸν ἔπηλυν λεώ, κατάρξαι γὰρ οὗτος ἐδόκει πολέμου, μετὰ τῶν ἡγεμόνων εἰ χρὴ καὶ τούτους σώζειν ἐσκέπτετο."},{"number":533,"text":"φαμένων δὲ τούτων βλαβερὰν ἔσεσθαι τὴν ἄφεσιν αὐτῶν, οὐ γὰρ ἠρεμήσειν ἀπολυθέντας ἀνθρώπους ἐστερημένους μὲν τῶν πατρίδων, βιάζεσθαι δὲ καὶ πρὸς οὓς ἂν καταφύγωσιν πολεμεῖν δυναμένους,"},{"number":534,"text":"Οὐεσπασιανὸς ὡς μὲν οὔτʼ ἄξιοι σωτηρίας εἶεν καὶ διαφεύξονται κατὰ τῶν ἀφέντων ἐγίνωσκεν, τὸν δὲ τρόπον αὐτῶν τῆς ἀναιρέσεως διενοεῖτο."},{"number":535,"text":"καὶ γὰρ αὐτόθι κτείνων ἐκπολεμώσειν ὑφωρᾶτο τοὺς ἐπιχωρίους, οὐ γὰρ ἀνέξεσθαι φονευομένων ἱκετῶν τοσούτων παρʼ αὐτοῖς, καὶ μετὰ πίστεις ἐπιθέσθαι προελθοῦσιν οὐχ ὑπέμενεν."},{"number":536,"text":"ἐξενίκων δʼ οἱ φίλοι μηδὲν κατὰ Ἰουδαίων ἀσεβὲς εἶναι λέγοντες καὶ χρῆναι τὸ συμφέρον αἱρεῖσθαι πρὸ τοῦ πρέποντος, ὅταν ᾖ μὴ δυνατὸν ἄμφω."},{"number":537,"text":"κατανεύσας οὖν αὐτοῖς ἄδειαν ἀμφίβολον ἐπέτρεψεν ἐξιέναι διὰ μόνης τῆς ἐπὶ Τιβεριάδα φερούσης ὁδοῦ."},{"number":538,"text":"τῶν δὲ ταχέως πιστευσάντων οἷς ἤθελον καὶ μετὰ φανερῶν ἐν ἀσφαλεῖ τῶν χρημάτων ᾗπερ ἐπετράπη χωρούντων, διαλαμβάνουσιν μὲν οἱ Ῥωμαῖοι τὴν μέχρι Τιβεριάδος πᾶσαν, ὡς μή τις ἀποκλίνειεν, συγκλείουσι δʼ αὐτοὺς εἰς τὴν πόλιν."},{"number":539,"text":"καὶ Οὐεσπασιανὸς ἐπελθὼν ἵστησι πάντας ἐν τῷ σταδίῳ, καὶ γηραιοὺς μὲν ἅμα τοῖς ἀχρήστοις διακοσίους ἐπὶ χιλίοις ὄντας ἀνελεῖν ἐκέλευσεν,"},{"number":540,"text":"τῶν δὲ νέων ἐπιλέξας τοὺς ἰσχυροτάτους ἑξακισχιλίους ἔπεμψεν εἰς τὸν ἰσθμὸν Νέρωνι, καὶ τὸ λοιπὸν πλῆθος εἰς τρισμυρίους καὶ τετρακοσίους ὄντας πιπράσκει χωρὶς τῶν Ἀγρίππᾳ χαρισθέντων·"},{"number":541,"text":"τοὺς γὰρ ἐκ τῆς τούτου βασιλείας ἐπέτρεψεν αὐτῷ ποιεῖν εἴ τι βούλοιτο· πιπράσκει δὲ καὶ τούτους ὁ βασιλεύς."},{"number":542,"text":"ὁ μέντοι γε ἄλλος ὄχλος Τραχωνῖται καὶ Γαυλανῖται καὶ Ἱππηνοὶ καὶ ἐκ τῆς Γαδαρίτιδος τὸ πλέον ὡς στασιασταὶ καὶ φυγάδες καὶ οἷς τὰ τῆς εἰρήνης ὀνείδη τὸν πόλεμον προυξένει ἑάλωσαν δὲ Γορπιαίου μηνὸς ὀγδόῃ."}]},"count":542};})();